    git -C $gitIndexRoot init -q
    if($LASTEXITCODE){throw 'git init'}
    [IO.File]::WriteAllText((Join-Path $gitIndexRoot '.gitignore'),"ignored.ps1`n")
    [IO.File]::WriteAllText((Join-Path $gitIndexRoot 'tracked.ps1'),'function Tracked { 1 }')
    [IO.File]::WriteAllText((Join-Path $gitIndexRoot 'ignored.ps1'),'function Ignored { 1 }')
    git -C $gitIndexRoot add -- .gitignore tracked.ps1
    git -C $gitIndexRoot -c user.name=PSC -c user.email=psc@localhost commit -qm 'fixture'
    if($LASTEXITCODE){throw 'git commit'}
    $gitIndex=$api.OpenSemanticIndex($gitIndexRoot);$gitGraph=$gitIndex.Refresh()
    Assert-Tree ($gitGraph.Files.Count -eq 1 -and $gitGraph.Files[0] -ceq 'tracked.ps1') 'source discovery excludes ignored sources'
    Assert-Tree ($gitGraph.Changes().Count -eq 0) 'Git snapshot starts unchanged'
    [IO.File]::Delete((Join-Path $gitIndexRoot 'tracked.ps1'))
    Assert-Tree ($gitGraph.Changes().Count -eq 1 -and [string]$gitGraph.Changes()[0].Kind -ceq 'Missing') 'tracked deletion observed'
    $missingGraph=$gitIndex.Refresh()
    Assert-Tree ($missingGraph.Changes().Count -eq 0) 'tracked missing source remains unchanged'
    [IO.File]::WriteAllText((Join-Path $gitIndexRoot 'tracked.ps1'),'function Tracked { 1 }')
    Assert-Tree ($missingGraph.Changes().Count -eq 1 -and [string]$missingGraph.Changes()[0].Kind -ceq 'Added') 'tracked missing source restored'
    [IO.File]::WriteAllText((Join-Path $gitIndexRoot 'new.srm1'),'function Resource { 2 }')
    Assert-Tree ($missingGraph.Changes().Count -eq 2) 'new nonignored SM source admitted'
    $inventory=@(& $compiler -Mode Graph -ProjectPath $gitIndexRoot -GraphInventoryOnly)
    Assert-Tree ($inventory.Count -eq 2 -and $inventory -ccontains 'new.srm1') 'Graph inventory matches Git source discovery'
    [IO.File]::WriteAllText((Join-Path $gitIndexRoot 'Case.ps1'),'class Example { static [int] Value(){return 1} }; function Call { [Example]::Value() }; Call')
    if(![IO.File]::Exists((Join-Path $gitIndexRoot 'case.ps1'))){
        [IO.File]::WriteAllText((Join-Path $gitIndexRoot 'case.ps1'),'class Example { static [int] Value(){return 1} }; function Call { [Example]::Value() }; Call')
        $both=$gitIndex.Refresh();$edges=@($both.Edges | Where-Object To -CEQ 'Example.Value')
        Assert-Tree ($edges.Count -eq 2 -and @($edges | Where-Object Resolution -CEQ 'Bound').Count -eq 2 -and $edges[0].ToIdentity -cne $edges[1].ToIdentity) 'case-distinct physical roots bind independently'
        $calls=@($both.Edges | Where-Object To -CEQ 'Call')
        Assert-Tree ($calls.Count -eq 2 -and @($calls | Where-Object Resolution -CEQ 'Bound').Count -eq 2 -and $calls[0].ToIdentity -cne $calls[1].ToIdentity) 'case-distinct lexical roots bind independently'
    }
} finally { [IO.Directory]::Delete($work, $true) }

'@)
    [PscSourceResource]::new('Tests/Test-Guard.ps1', @'
#requires -Version 7.7
[CmdletBinding()]
param([Parameter(Mandatory)][string]$Compiler)
$ErrorActionPreference='Stop'
$compiler=[IO.Path]::GetFullPath($Compiler)
$root=[IO.Directory]::CreateDirectory([IO.Path]::Combine([IO.Path]::GetTempPath(),'psc-guard-review-'+[Guid]::NewGuid().ToString('N'))).FullName
function Test-Case([string]$label,[string]$before,[string]$after,[bool]$expected,[string]$reason='new finding') {
    [IO.File]::WriteAllText($base,$before)
    git -C $root add source.ps1
    if($LASTEXITCODE -ne 0){throw 'git add failed'}
    git -C $root -c user.name=PSC -c user.email=psc@localhost commit --allow-empty -qm $label
    if($LASTEXITCODE -ne 0){throw 'git commit failed'}
    [IO.File]::WriteAllText($candidate,$after)
    $passed=$false
    try{$result=$api.GuardCandidate($candidate,$base,'');$passed=$result.Passed}catch{if($expected -or !$_.Exception.Message.Contains($reason,[StringComparison]::Ordinal)){throw}}
    if($passed -ne $expected){throw "$label expected $expected actual $passed"}
    "PASS $label ($passed)"
}
try {
    $base=Join-Path $root 'source.ps1';$candidate=Join-Path $root 'candidate.ps1'
    git -C $root init -q
    if($LASTEXITCODE -ne 0){throw 'git init failed'}
    $api=& $compiler -Mode Api
    # Git identity describes the committed bytes, not the checkout or normalized AST text.
    foreach($committedText in @("# baseline`r`n", "# baseline`r`n# no terminal newline")){
        $committedBytes=[Text.UTF8Encoding]::new($false).GetBytes($committedText)
        [IO.File]::WriteAllBytes($base,$committedBytes)
        git -C $root -c core.autocrlf=false add -- source.ps1
        if($LASTEXITCODE -ne 0){throw 'git add failed'}
        git -C $root -c user.name=PSC -c user.email=psc@localhost commit --allow-empty -qm 'exact baseline identity'
        if($LASTEXITCODE -ne 0){throw 'git commit failed'}
        $blobId=git -C $root rev-parse --verify HEAD:source.ps1
        if($LASTEXITCODE -ne 0){throw 'git blob resolution failed'}
        $expectedDigest=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($committedBytes))
        [IO.File]::WriteAllText($base,'# dirty checkout')
        [IO.File]::WriteAllBytes($candidate,$committedBytes)
        $identityVerdict=$api.GuardCandidate($candidate,$base,'')
        if(!$identityVerdict.Passed -or $identityVerdict.BaselineBlobId -cne $blobId -or $identityVerdict.BaselineSha256 -cne $expectedDigest -or $identityVerdict.CandidateSha256 -cne $expectedDigest){throw 'Guard lost exact committed identity.'}
        'PASS exact committed baseline bytes despite dirty checkout'
        [IO.File]::WriteAllBytes($base,$committedBytes)
        $standalone=& $compiler -Mode Guard -LintFiles $base
        if(!$standalone.Passed -or $standalone.BaselineCommit -cne $identityVerdict.BaselineCommit -or $standalone.BaselineBlobId -cne $blobId -or $standalone.BaselineSha256 -cne $expectedDigest -or $standalone.CandidateSha256 -cne $expectedDigest){throw 'Standalone Guard lost exact committed identity.'}
        'PASS standalone exact committed identity' 
    }
    Test-Case 'equal count replacement' '$x = 1; $X = 2' '$y = 1; $Y = 2' $false
    Test-Case 'lower count replacement' '$x = 1; $X = 2; $z = 1; $Z = 2' '$y = 1; $Y = 2' $false
    Test-Case 'same identity' '$x = 1; $X = 2' '$x = 3; $X = 4' $true
    Test-Case 'new scope with same spelling' 'function First { $x = 1; $X = 2 }' 'function Second { $x = 1; $X = 2 }' $false
    Test-Case 'removed finding' '$x = 1; $X = 2' '$x = 1' $true
    Test-Case 'duplicate identity replaces another' 'Foo(1,2); Bar(1,2)' 'Foo(1,2); Foo(1,2)' $false
    $clobber='function Example { $value = 0; foreach ($item in 1,2) { $value = $item }; Write-Output $value }'
    Test-Case 'clobber shifted by lines' $clobber ("# comment`n`n"+$clobber) $true
    Test-Case 'clobber changed symbol' $clobber ($clobber.Replace('$value','$other')) $false
    Test-Case 'new direct evaluation rejected' 'Write-Output $text' 'Invoke-Expression $text' $false
    Test-Case 'new certificate override rejected' 'Invoke-WebRequest -Uri $uri' 'Invoke-WebRequest -Uri $uri -SkipCertificateCheck' $false
    Test-Case 'new insecure formatter rejected' 'Write-Output 1' 'New-Object BinaryFormatter' $false
    function New-ResourceFixture([string]$path,[string]$payload) {
        return "function Get-PscEmbeddedSources {`n    [PscSourceResource]::new('$path', @'`n$payload`n'@)`n}"
    }
    $clean=New-ResourceFixture 'SM/One.sm1' 'Write-Output 1'
    $finding=New-ResourceFixture 'SM/One.sm1' 'Invoke-Expression $text'
    Test-Case 'embedded SM finding rejected' $clean $finding $false 'SM/One.sm1: DynamicCodeExecution: new finding'
    Test-Case 'embedded existing finding retained' $finding ($finding.Replace('Invoke-Expression $text',"# shifted`nInvoke-Expression `$text")) $true
    Test-Case 'embedded finding removed' $finding $clean $true
    Test-Case 'embedded finding not transferable across paths' $finding ($finding.Replace('One.sm1','Two.sm1')) $false 'SM/Two.sm1: DynamicCodeExecution: new finding'
    Test-Case 'embedded duplicate finding rejected' $finding ($finding.Replace('Invoke-Expression $text','Invoke-Expression $text; Invoke-Expression $text')) $false 'SM/One.sm1: DynamicCodeExecution: new finding'
    foreach($extension in '.ps1','.psm1','.srm1','.sexe'){
        $resourcePath='Tests/Resource'+$extension
        Test-Case ('new source resource '+$extension) $clean (New-ResourceFixture $resourcePath 'Invoke-Expression $text') $false ($resourcePath+': DynamicCodeExecution: new finding')
    }
    Test-Case 'non-source resource inert' $clean (New-ResourceFixture 'SM/Notes.md' 'Invoke-Expression $text') $true
    Test-Case 'embedded invalid syntax rejected' $clean (New-ResourceFixture 'SM/One.sm1' 'if (') $false 'Invalid source SM/One.sm1'
    Test-Case 'embedded missing faculty type admitted' $clean (New-ResourceFixture 'SM/One.sm1' 'class ExternalUse { [ExternalFaculty] $Role }') $true
    Test-Case 'resource holder removed rejected' $clean 'Write-Output 1' $false 'Embedded resource holder removed or emptied'
    Test-Case 'resource expression rejected' $clean ($clean.Replace("@'`nWrite-Output 1`n'@",'$text')) $false 'Embedded resource coverage failed'
    $duplicate=$clean.Insert($clean.LastIndexOf('}'),$clean.Substring($clean.IndexOf('[PscSourceResource]'),$clean.LastIndexOf('}')-$clean.IndexOf('[PscSourceResource]')))
    Test-Case 'duplicate resource path rejected' $clean $duplicate $false 'Duplicate resource path'
    Test-Case 'ambiguous holder rejected' $clean ($clean+"`n"+$clean) $false 'Ambiguous resource holder'
}finally{[IO.Directory]::Delete($root,$true)}
$root=[IO.Directory]::CreateDirectory([IO.Path]::Combine([IO.Path]::GetTempPath(),'psc-guard-scope-'+[Guid]::NewGuid().ToString('N'))).FullName
try {
 $fixture=Join-Path $root 'scope.ps1'
 function Assert-Lint([string]$label,[string]$source,[string]$rule,[int]$expected) {
   [IO.File]::WriteAllText($fixture,$source)
   $lines=@($api.Lint(@($fixture)) | Where-Object Rule -CEQ $rule)
   if($lines.Count -ne $expected){throw "$label expected $expected actual $($lines.Count): $lines"}
   foreach($item in $lines){if(!$item.Extent -or $item.Extent.StartOffset -ge $item.Extent.EndOffset -or !$item.Identity -or !$item.Scope){throw 'Incomplete typed lint reference.'}}
   "PASS $label ($expected)"
 }
 Assert-Lint 'independent function locals' 'function First { $node = 1 }; function Second { $Node = 2 }' 'CaseSpelledTwoWays' 0
 Assert-Lint 'same function casing' 'function First { $node = 1; $Node = 2 }' 'CaseSpelledTwoWays' 1
 Assert-Lint 'enclosing variable read' '$node = 1; function First { return $Node }' 'CaseSpelledTwoWays' 1
 Assert-Lint 'explicit script scope' '$node = 1; function First { return $script:Node }' 'CaseSpelledTwoWays' 1
 Assert-Lint 'parameter shadow of script parameter' 'param($node); function First { param($Node); $Node }' 'CaseSpelledTwoWays' 0
 Assert-Lint 'two shadowed properties, duplicate reads' 'class Sample { [int] $A; [int] $B; [int] Read() { return $A + $B + $A } }' 'LocalShadowsProperty' 2
 Assert-Lint 'independent method overloads' 'class Sample { [int] M([int]$v){return $v}; [double] M([double]$V){return $V} }' 'CaseSpelledTwoWays' 0
 Assert-Lint 'class method is not a command declaration' 'class Sample { [void] Verify() {} }; verify' 'CaseSpelledTwoWays' 0
 Assert-Lint 'direct string evaluation' 'Invoke-Expression $text' 'DynamicCodeExecution' 1
 Assert-Lint 'stock evaluation alias' 'iex $text' 'DynamicCodeExecution' 1
 Assert-Lint 'qualified evaluation command' 'Microsoft.PowerShell.Utility\Invoke-Expression $text' 'DynamicCodeExecution' 1
 Assert-Lint 'static script construction' '[scriptblock]::Create($text)' 'DynamicCodeExecution' 1
 Assert-Lint 'inline source compilation' 'Add-Type -TypeDefinition $text' 'DynamicCodeExecution' 1
 Assert-Lint 'existing assembly reference' 'Add-Type -AssemblyName System.Xml' 'DynamicCodeExecution' 0
 Assert-Lint 'inert evaluation string' '$description = "Invoke-Expression text"' 'DynamicCodeExecution' 0
 Assert-Lint 'typed scriptblock literal' '& { Write-Output 1 }' 'DynamicCodeExecution' 0
 Assert-Lint 'certificate override' 'Invoke-WebRequest -Uri $uri -SkipCertificateCheck' 'CertificateValidationDisabled' 1
 Assert-Lint 'certificate validation retained' 'Invoke-WebRequest -Uri $uri -SkipCertificateCheck:$false' 'CertificateValidationDisabled' 0
 Assert-Lint 'ordinary web request' 'Invoke-WebRequest -Uri $uri' 'CertificateValidationDisabled' 0
 Assert-Lint 'formatter constructor' '[System.Runtime.Serialization.Formatters.Binary.BinaryFormatter]::new()' 'UnsafeDeserialization' 1
 Assert-Lint 'formatter named construction' 'New-Object -TypeName System.Runtime.Serialization.Formatters.Binary.BinaryFormatter' 'UnsafeDeserialization' 1
 Assert-Lint 'formatter positional construction' 'New-Object BinaryFormatter' 'UnsafeDeserialization' 1
 Assert-Lint 'ordinary object construction' 'New-Object System.Text.StringBuilder' 'UnsafeDeserialization' 0
 Assert-Lint 'security policy mutation' 'Set-MpPreference @settings' 'SecurityControlMutation' 1
 Assert-Lint 'security policy inspection' 'Get-MpPreference' 'SecurityControlMutation' 0
}finally{[IO.Directory]::Delete($root,$true)}


# Verification inventory is ordered and complete, in both Guard entry points.
$inventoryRoot=[IO.Directory]::CreateDirectory([IO.Path]::Combine([IO.Path]::GetTempPath(),'psc-inventory-'+[Guid]::NewGuid().ToString('N'))).FullName
$markerFirst='function First { [PscVerify()] param() }'
$markerSecond='function Second { [PscVerify()] param() }'
$unmarkedSecond='function Second { param() }'
$inventorySource=[IO.Path]::Combine($inventoryRoot,'source.ps1')
$inventoryCandidate=[IO.Path]::Combine($inventoryRoot,'candidate.ps1')
function Test-VerificationInventory([string]$Name,[string]$Before,[string]$After,[bool]$Expected,[string]$Reason){
    [IO.File]::WriteAllText($inventorySource,$Before)
    git -C $inventoryRoot add -- source.ps1
    if($LASTEXITCODE -ne 0){throw 'git add failed'}
    git -C $inventoryRoot -c user.name=PSC -c user.email=psc@localhost commit --allow-empty -qm $Name
    if($LASTEXITCODE -ne 0){throw 'git commit failed'}
    [IO.File]::WriteAllText($inventoryCandidate,$After)
    foreach($entryPoint in 'Candidate','Standalone'){
        $accepted=$false
        try {
            if($entryPoint -ceq 'Candidate'){$verdict=& $compiler -Mode Guard -LintFiles $inventoryCandidate -AgainstPath $inventorySource}
            else{[IO.File]::WriteAllText($inventorySource,$After);$verdict=& $compiler -Mode Guard -LintFiles $inventorySource}
            $accepted=$verdict.Passed
        } catch {if($Expected -or !$_.Exception.Message.Contains($Reason,[StringComparison]::Ordinal)){throw}}
        if($accepted -ne $Expected){throw "$Name / $entryPoint expected $Expected actual $accepted"}
        "PASS $Name / $entryPoint"
    }
}
try {
    git -C $inventoryRoot init -q
    if($LASTEXITCODE -ne 0){throw 'git init failed'}
    Test-VerificationInventory 'unchanged' "$markerFirst`n$markerSecond" "$markerFirst`n$markerSecond" $true ''
    Test-VerificationInventory 'non-marker edit' "$markerFirst`n$unmarkedSecond" "$markerFirst`n$unmarkedSecond`n# comment" $true ''
    Test-VerificationInventory 'added marker' $markerFirst "$markerFirst`n$markerSecond" $false 'verification inventory count differs from HEAD'
    Test-VerificationInventory 'first marker' $unmarkedSecond $markerSecond $false 'verification inventory count differs from HEAD'
    Test-VerificationInventory 'removed marker' "$markerFirst`n$markerSecond" $markerFirst $false 'verification inventory count differs from HEAD'
    Test-VerificationInventory 'reordered markers' "$markerFirst`n$markerSecond" "$markerSecond`n$markerFirst" $false 'verification inventory order differs from HEAD'
    Test-VerificationInventory 'duplicate marker name' $markerFirst "$markerFirst`n$markerFirst" $false 'verification inventory count differs from HEAD'
    Test-VerificationInventory 'duplicate baseline identity unchanged' "$markerFirst`n$markerFirst" "$markerFirst`n$markerFirst" $false 'ambiguous baseline verification declaration'
    Test-VerificationInventory 'case-insensitive duplicate identity' $markerFirst ($markerFirst+"`n"+$markerFirst.Replace('First','FIRST')) $false 'ambiguous candidate verification declaration'
    Test-VerificationInventory 'same count substitution' $markerFirst $markerSecond $false 'verification inventory order differs from HEAD'
    Test-VerificationInventory 'changed body' $markerFirst 'function First { [PscVerify()] param() return 1 }' $false 'checker function First differs from HEAD'
}finally{[IO.Directory]::Delete($inventoryRoot,$true)}

# Runner identity and Git routing are independent of the marked verification inventory.
$identityRoot=[IO.Directory]::CreateDirectory([IO.Path]::Combine([IO.Path]::GetTempPath(),'psc-authority-'+[Guid]::NewGuid().ToString('N'))).FullName
function Assert-AuthorityRefusal([string]$Label,[hashtable]$Arguments,[string]$Reason){
    $refused=$false
    try{$null=& $compiler @Arguments}catch{if(!$_.Exception.Message.Contains($Reason,[StringComparison]::Ordinal)){throw};$refused=$true}
    if(!$refused){throw "$Label admitted"};"PASS $Label"
}
try{
    $authorityBase=Join-Path $identityRoot 'source.ps1';$authorityCandidate=Join-Path $identityRoot 'candidate.ps1'
    git -C $identityRoot init -q
    if($LASTEXITCODE -ne 0){throw 'git init failed'}
    [IO.File]::WriteAllText($authorityBase,'Write-Output 1')
    git -C $identityRoot add -- source.ps1
    git -C $identityRoot -c user.name=PSC -c user.email=psc@localhost commit -qm 'approved source'
    if($LASTEXITCODE -ne 0){throw 'git commit failed'}
    $approvedCommit=git -C $identityRoot rev-parse HEAD
    $approvedBlob=git -C $identityRoot rev-parse HEAD:source.ps1
    [IO.File]::WriteAllText($authorityCandidate,'Write-Output 1')
    $runnerDigest=(Get-FileHash -LiteralPath $compiler).Hash
    $candidateArgs=@{Mode='Guard';LintFiles=$authorityCandidate;AgainstPath=$authorityBase}
    $standaloneArgs=@{Mode='Guard';LintFiles=$authorityBase}
    $pinned=& $compiler @candidateArgs -ExpectedRunnerSha256 $runnerDigest
    if(!$pinned.Passed -or $pinned.RunnerSha256 -cne $runnerDigest -or $pinned.RunnerPath -cne $compiler){throw 'Runner pin was not retained.'}
    'PASS exact runner identity recorded'
    $gitName=if([OperatingSystem]::IsWindows()){'git.exe'}else{'git'}
    $gitPath=(Get-Command $gitName -CommandType Application | Select-Object -First 1).Path
    $gitDigest=(Get-FileHash -LiteralPath $gitPath).Hash
    $wrongGit=if($gitDigest[0] -eq '0'){'1'+$gitDigest.Substring(1)}else{'0'+$gitDigest.Substring(1)}
    $gitPinned=& $compiler @candidateArgs -ExpectedGitSha256 $gitDigest
    if(!$gitPinned.Passed -or $gitPinned.GitExecutablePath -cne $gitPath -or $gitPinned.GitExecutableSha256 -cne $gitDigest){throw 'Git acquisition identity not retained.'}
    'PASS candidate Guard records independently pinned Git executable'
    $gitPinned=& $compiler @standaloneArgs -ExpectedGitSha256 $gitDigest
    if(!$gitPinned.Passed -or $gitPinned.GitExecutablePath -cne $gitPath -or $gitPinned.GitExecutableSha256 -cne $gitDigest){throw 'Standalone Git acquisition identity not retained.'}
    'PASS standalone Guard records independently pinned Git executable'
    Assert-AuthorityRefusal 'candidate Guard rejects wrong Git executable pin' ($candidateArgs+@{ExpectedGitSha256=$wrongGit}) 'Expected Git executable SHA-256 mismatch'
    Assert-AuthorityRefusal 'standalone Guard rejects wrong Git executable pin' ($standaloneArgs+@{ExpectedGitSha256=$wrongGit}) 'Expected Git executable SHA-256 mismatch'
    Assert-AuthorityRefusal 'Conform rejects wrong Git executable pin' @{Mode='Conform';SourcePath=$authorityCandidate;AgainstPath=$authorityBase;ExpectedGitSha256=$wrongGit;DevelopmentOnly=$true} 'Expected Git executable SHA-256 mismatch'
    $wrongDigest=if($runnerDigest[0] -eq '0'){'1'+$runnerDigest.Substring(1)}else{'0'+$runnerDigest.Substring(1)}
    Assert-AuthorityRefusal 'candidate Guard rejects wrong runner' ($candidateArgs+@{ExpectedRunnerSha256=$wrongDigest}) 'Expected runner SHA-256 mismatch'
    Assert-AuthorityRefusal 'standalone Guard rejects wrong runner' ($standaloneArgs+@{ExpectedRunnerSha256=$wrongDigest}) 'Expected runner SHA-256 mismatch'
    Assert-AuthorityRefusal 'Conform rejects wrong runner' @{Mode='Conform';SourcePath=$authorityCandidate;AgainstPath=$authorityBase;ExpectedRunnerSha256=$wrongDigest;DevelopmentOnly=$true} 'Expected runner SHA-256 mismatch'
    $baselineDigest=(Get-FileHash -LiteralPath $authorityBase).Hash
    $wrongBaseline=if($baselineDigest[0] -eq '0'){'1'+$baselineDigest.Substring(1)}else{'0'+$baselineDigest.Substring(1)}
    Assert-AuthorityRefusal 'Conform rejects wrong committed baseline' @{Mode='Conform';SourcePath=$authorityCandidate;AgainstPath=$authorityBase;ExpectedRunnerSha256=$runnerDigest;ExpectedBaselineSha256=$wrongBaseline;DevelopmentOnly=$true} 'Expected committed baseline SHA-256 mismatch'
    foreach($variable in 'GIT_DIR','GIT_CONFIG_COUNT'){
        $priorPresent=Test-Path -LiteralPath ('Env:'+$variable)
        $priorValue=[Environment]::GetEnvironmentVariable($variable)
        try{
            [Environment]::SetEnvironmentVariable($variable,'1')
            Assert-AuthorityRefusal ('candidate rejects '+$variable) $candidateArgs 'Ambient Git repository override not admitted'
            Assert-AuthorityRefusal ('standalone rejects '+$variable) $standaloneArgs 'Ambient Git repository override not admitted'
        }finally{if($priorPresent){[Environment]::SetEnvironmentVariable($variable,$priorValue)}else{Remove-Item -LiteralPath ('Env:'+$variable) -ErrorAction SilentlyContinue}}
    }
    [IO.File]::WriteAllText($authorityBase,'Invoke-Expression $text')
    git -C $identityRoot add -- source.ps1
    git -C $identityRoot -c user.name=PSC -c user.email=psc@localhost commit -qm 'replacement source'
    if($LASTEXITCODE -ne 0){throw 'git commit failed'}
    $replacementCommit=git -C $identityRoot rev-parse HEAD
    git -C $identityRoot reset --hard $approvedCommit | Out-Null
    if($LASTEXITCODE -ne 0){throw 'git reset failed'}
    git -C $identityRoot replace $approvedCommit $replacementCommit
    if($LASTEXITCODE -ne 0){throw 'git replace failed'}
    $unredirected=& $compiler @candidateArgs
    if(!$unredirected.Passed -or $unredirected.BaselineCommit -cne $approvedCommit -or $unredirected.BaselineBlobId -cne $approvedBlob){throw 'Replacement reference redirected the baseline.'}
    'PASS candidate Guard retains original commit and blob despite replacement ref'
    [IO.File]::WriteAllText($authorityCandidate,'Invoke-Expression $text')
    Assert-AuthorityRefusal 'replacement ref cannot admit new finding' $candidateArgs 'DynamicCodeExecution: new finding'
    function git { $global:LASTEXITCODE=1 }
    Assert-AuthorityRefusal 'standalone refuses replacement refs despite shadowed Git command' $standaloneArgs 'Git replacement references are not admitted'
    Remove-Item -LiteralPath Function:git
    Assert-AuthorityRefusal 'standalone refuses replacement refs' $standaloneArgs 'Git replacement references are not admitted'
}finally{[IO.Directory]::Delete($identityRoot,$true)}
# Missing sources and failed Git reads are deliberately different states.
$directRoot=[IO.Directory]::CreateDirectory([IO.Path]::Combine([IO.Path]::GetTempPath(),'psc-guard-direct-'+[Guid]::NewGuid().ToString('N'))).FullName
try{
    $directPath=Join-Path $directRoot 'source.ps1'
    [IO.File]::WriteAllText($directPath,'Write-Output 1')
    $directArgs=@{Mode='Guard';LintFiles=$directPath}
    $untracked=& $compiler @directArgs
    if(!$untracked.Passed -or $untracked.BaselineBlobId -or $untracked.CandidateSha256 -cne (Get-FileHash -LiteralPath $directPath).Hash){throw 'Nonrepository source identity lost.'}
    'PASS standalone source outside repository'
    git -C $directRoot init -q
    if($LASTEXITCODE -ne 0){throw 'git init failed'}
    $unborn=& $compiler @directArgs
    if(!$unborn.Passed -or $unborn.BaselineBlobId){throw 'Unborn baseline unexpectedly acquired.'}
    'PASS standalone unborn repository'
    git -C $directRoot -c user.name=PSC -c user.email=psc@localhost commit --allow-empty -qm 'empty baseline'
    if($LASTEXITCODE -ne 0){throw 'git commit failed'}
    $absent=& $compiler @directArgs
    if(!$absent.Passed -or $absent.BaselineBlobId){throw 'Absent path unexpectedly acquired.'}
    'PASS standalone absent committed path'
    [IO.File]::WriteAllText($directPath,'Invoke-Expression $text')
    Assert-AuthorityRefusal 'untracked source must not introduce findings' $directArgs 'DynamicCodeExecution: new finding'
    $directCandidate=Join-Path $directRoot 'candidate.ps1'
    [IO.File]::WriteAllText($directCandidate,'Write-Output 1')
    Assert-AuthorityRefusal 'explicit candidate baseline must exist' @{Mode='Guard';LintFiles=$directCandidate;AgainstPath=$directPath} 'Committed baseline path is absent'
    $nested=[IO.Directory]::CreateDirectory((Join-Path $directRoot 'nested')).FullName
    $literalPath=Join-Path $nested 'source[1].ps1'
    [IO.File]::WriteAllText($literalPath,'Write-Output 2')
    git --literal-pathspecs -C $directRoot add -- 'nested/source[1].ps1'
    if($LASTEXITCODE -ne 0){throw 'git add failed'}
    git -C $directRoot -c user.name=PSC -c user.email=psc@localhost commit -qm 'literal nested source'
    if($LASTEXITCODE -ne 0){throw 'git commit failed'}
    $literalBlob=git -C $directRoot rev-parse --verify 'HEAD:nested/source[1].ps1'
    $literalVerdict=& $compiler -Mode Guard -LintFiles $literalPath
    if(!$literalVerdict.Passed -or $literalVerdict.BaselineBlobId -cne $literalBlob){throw 'Literal nested path resolved incorrectly.'}
    'PASS literal nested committed path'
    $blobPath=Join-Path $directRoot ('.git/objects/'+$literalBlob.Substring(0,2)+'/'+$literalBlob.Substring(2))
    [IO.File]::Delete($blobPath)
    Assert-AuthorityRefusal 'missing committed object is not an absent baseline' @{Mode='Guard';LintFiles=$literalPath} 'Git object acquisition failed'
}finally{[IO.Directory]::Delete($directRoot,$true)}
# A fixture must not leave another stage executing different compiler bytes, even if
# a subsequent fixture could restore the initial digest before the final report.
$driftRoot=[IO.Directory]::CreateTempSubdirectory('psc-stage-drift-').FullName
try{
    $driftBase=Join-Path $driftRoot 'source.ps1';$driftCandidate=Join-Path $driftRoot 'candidate.ps1'
    $payloads=[Collections.Generic.Dictionary[string,string]]::new([StringComparer]::Ordinal)
    $payloads.Add('Tests/Test-Document.ps1','param([string]$Compiler); [IO.File]::AppendAllText($Compiler,"`n# drift")')
    $payloads.Add('Tests/Test-Worktree.ps1','param([string]$Compiler); $source=[IO.File]::ReadAllText($Compiler); [IO.File]::WriteAllText($Compiler,$source.Substring(0,$source.Length-8))')
    $payloads.Add('Tests/Test-Guard.ps1','param([string]$Compiler)')
    $payloads.Add('SM/Test-Formats.ps1','param([string]$Compiler)')
    $lines=[Collections.Generic.List[string]]::new()
    $lines.Add('param([string]$Mode,[string]$TreeDirectory)');$lines.Add('function Get-PscEmbeddedSources {')
    foreach($entry in $payloads.GetEnumerator()){$lines.Add("[PscSourceResource]::new('$($entry.Key)', @'");$lines.Add($entry.Value);$lines.Add("'@)")}
    $lines.Add('}')
    $driftText=$lines -join "`n"
    [IO.File]::WriteAllText($driftBase,$driftText);[IO.File]::WriteAllText($driftCandidate,$driftText)
    git -C $driftRoot init -q
    if($LASTEXITCODE -ne 0){throw 'git init failed'}
    git -C $driftRoot add source.ps1
    if($LASTEXITCODE -ne 0){throw 'git add failed'}
    git -C $driftRoot -c user.name=PSC -c user.email=psc@localhost commit -qm 'stage drift control'
    if($LASTEXITCODE -ne 0){throw 'git commit failed'}
    Assert-AuthorityRefusal 'Conform rejects interstage compiler mutation before restoration' @{Mode='Conform';SourcePath=$driftCandidate;AgainstPath=$driftBase;ExpectedRunnerSha256=(Get-FileHash -LiteralPath $compiler).Hash;ExpectedBaselineSha256=(Get-FileHash -LiteralPath $driftBase).Hash;DevelopmentOnly=$true} 'Candidate changed during conformance after Tests/Test-Document.ps1'
    if((Get-FileHash -LiteralPath $driftCandidate).Hash -ceq (Get-FileHash -LiteralPath $driftBase).Hash){throw 'Restoration fixture executed after mutation.'}
    'PASS conformance stops before restoration stage'
}finally{[IO.Directory]::Delete($driftRoot,$true)}

# Scope is independently constrained even when each observation matches its reported requirement.
function Test-RequiredConformanceScope([string]$Compiler){
$root=[IO.Directory]::CreateTempSubdirectory('psc-scope-').FullName
try {
    $base=Join-Path $root 'source.ps1';$candidate=Join-Path $root 'candidate.ps1'
    $payloads=[Collections.Generic.Dictionary[string,string]]::new([StringComparer]::Ordinal)
    foreach($fixture in 'Tests/Test-Document.ps1','Tests/Test-Worktree.ps1','Tests/Test-Guard.ps1','SM/Test-Formats.ps1'){$payloads.Add($fixture,'param([string]$Compiler)')}
    $lines=[Collections.Generic.List[string]]::new()
    $lines.Add('param([string]$Mode,[string]$TreeDirectory)');$lines.Add('function Get-PscEmbeddedSources {')
    foreach($entry in $payloads.GetEnumerator()){$lines.Add("[PscSourceResource]::new('$($entry.Key)', @'");$lines.Add($entry.Value);$lines.Add("'@)")}
    $lines.Add('}')
    $text=$lines -join "`n"
    [IO.File]::WriteAllText($base,$text);[IO.File]::WriteAllText($candidate,$text)
    git -C $root init -q;git -C $root add source.ps1;git -C $root -c user.name=PSC -c user.email=psc@localhost commit -qm fixture
    if($LASTEXITCODE -ne 0){throw 'Fixture Git failed'}
    $argsMap=@{Mode='Conform';SourcePath=$candidate;AgainstPath=$base;ExpectedRunnerSha256=(Get-FileHash $Compiler).Hash;ExpectedBaselineSha256=(Get-FileHash $base).Hash}
    $report=& $Compiler @argsMap -DevelopmentOnly
    if(!$report.Passed -or $report.Complete -or !$report.VerifyScope($true) -or $report.VerifyScope($false)){throw 'Development scope failure'}
    'PASS development scope exact mandatory inventory'
    $hostPath=[Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
    $hostDigest=(Get-FileHash -LiteralPath $hostPath).Hash
    if($report.ProcessHostPath -cne $hostPath -or $report.ProcessHostSha256 -cne $hostDigest){throw 'Observed host identity differs from independent file digest'}
    foreach($observed in $report.Stages){
        if($observed.State -ceq 'Skipped'){
            if($observed.ProcessHostPath -or $observed.ProcessHostSha256){throw 'Skipped stage claims host execution'}
        }elseif($observed.ProcessHostPath -cne $hostPath -or $observed.ProcessHostSha256 -cne $hostDigest){throw 'Executed stage has incorrect host identity'}
    }
    'PASS executed stage host identities and skipped scope'
    $report.Stages[0].ProcessHostSha256='0'*64
    if($report.VerifyScope($true)){throw 'Substituted stage host digest admitted'}
    $report.Stages[0].ProcessHostSha256=$hostDigest
    'PASS substituted stage host digest rejected'
    $report.Stages[-1].ProcessHostPath=$hostPath
    if($report.VerifyScope($true)){throw 'Skipped host observation admitted'}
    $report.Stages[-1].ProcessHostPath=''
    'PASS skipped stage host claim rejected'
    $badHost=if($hostDigest[0] -eq '0'){'1'+$hostDigest.Substring(1)}else{'0'+$hostDigest.Substring(1)}
    $refused=$false
    try{$null=& $Compiler @argsMap -ExpectedHostSha256 $badHost -DevelopmentOnly}catch{$refused=$_.Exception.Message.Contains('Expected process host SHA-256 mismatch')}
    if(!$refused){throw 'Incorrect independent process host digest admitted'}
    'PASS incorrect independent process host pin rejected before assessment'
    $argsMap.ExpectedHostSha256=$hostDigest
    if(!(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedHostSha256 $hostDigest -DevelopmentOnly)){throw 'Correct host pin refused'}
    if(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedHostSha256 $badHost -DevelopmentOnly){throw 'Incorrect host pin verified'}
    'PASS report verification respects independent host pin'
    $runtime=$report.RuntimeInventory
    $runtimeRoot=[IO.Path]::GetDirectoryName($hostPath)
    $nativeNames=if([OperatingSystem]::IsWindows()){@('coreclr.dll','clrjit.dll','hostfxr.dll','hostpolicy.dll')}elseif([OperatingSystem]::IsMacOS()){@('libcoreclr.dylib','libclrjit.dylib','libhostfxr.dylib','libhostpolicy.dylib')}else{@('libcoreclr.so','libclrjit.so','libhostfxr.so','libhostpolicy.so')}
    $names=@('pwsh.dll','pwsh.deps.json','pwsh.runtimeconfig.json','Microsoft.PowerShell.ConsoleHost.dll','System.Management.Automation.dll','System.Private.CoreLib.dll')+$nativeNames
    $platform=if([OperatingSystem]::IsWindows()){'Windows'}elseif([OperatingSystem]::IsMacOS()){'MacOS'}else{'Linux'}
    $lines=[Collections.Generic.List[string]]::new();$lines.Add('PSC Runtime Inventory v1');$lines.Add($platform)
    foreach($name in $names){$lines.Add($name+' '+(Get-FileHash -LiteralPath ([IO.Path]::Combine($runtimeRoot,$name))).Hash)}
    $runtimeDigest=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($lines -join "`n")))
    if($null -eq $runtime -or $runtime.Root -cne $runtimeRoot -or $runtime.Sha256 -cne $runtimeDigest -or $runtime.Files.Count -ne 10){throw 'Runtime inventory differs from independent measurement'}
    'PASS exact bounded runtime inventory independently reproduced'
    foreach($observed in $report.Stages){if($observed.State -ceq 'Skipped'){if($observed.RuntimeSha256){throw 'Skipped stage claims runtime inventory'}}elseif($observed.RuntimeSha256 -cne $runtimeDigest){throw 'Executed stage missing runtime inventory'}}
    'PASS runtime inventory stage scope'
    $report.Stages[0].RuntimeSha256='0'*64
    if($report.VerifyScope($true)){throw 'Changed stage runtime digest admitted'}
    $report.Stages[0].RuntimeSha256=$runtimeDigest
    $report.Stages[-1].RuntimeSha256=$runtimeDigest
    if($report.VerifyScope($true)){throw 'Skipped stage runtime digest admitted'}
    $report.Stages[-1].RuntimeSha256=''
    'PASS changed and skipped runtime claims refused'
    $files=$runtime.Files;$runtime.Files=@($files[1..9])
    if($report.VerifyScope($true)){throw 'Incomplete runtime inventory admitted'}
    $runtime.Files=$files
    $digest=$files[0].Sha256;$files[0].Sha256='0'*64
    if($report.VerifyScope($true)){throw 'Changed runtime file digest admitted'}
    $files[0].Sha256=$digest
    'PASS omitted and changed runtime file records refused'
    $badRuntime=if($runtimeDigest[0] -eq '0'){'1'+$runtimeDigest.Substring(1)}else{'0'+$runtimeDigest.Substring(1)}
    $refused=$false
    try{$null=& $Compiler @argsMap -ExpectedRuntimeSha256 $badRuntime -DevelopmentOnly}catch{$refused=$_.Exception.Message.Contains('Expected runtime inventory SHA-256 mismatch')}
    if(!$refused){throw 'Incorrect runtime pin admitted'}
    'PASS wrong runtime pin refused before assessment'
    if(!(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedRuntimeSha256 $runtimeDigest -DevelopmentOnly)){throw 'Correct runtime pin refused'}
    if(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedRuntimeSha256 $badRuntime -DevelopmentOnly){throw 'Incorrect runtime pin verified'}
    'PASS independent runtime inventory verification'
    $report.RuntimeInventory=$null
    foreach($observed in $report.Stages){$observed.RuntimeSha256=''}
    if(!$report.VerifyScope($true) -or (& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedRuntimeSha256 $runtimeDigest -DevelopmentOnly)){throw 'Legacy runtime scope pin policy violated'}
    $report.RuntimeInventory=$runtime
    foreach($observed in $report.Stages){if($observed.State -cne 'Skipped'){$observed.RuntimeSha256=$runtimeDigest}}
    'PASS legacy receipt cannot satisfy runtime pin'
    $argsMap.ExpectedRuntimeSha256=$runtimeDigest
    $gitName=if([OperatingSystem]::IsWindows()){'git.exe'}else{'git'}
    $gitPath=(Get-Command $gitName -CommandType Application | Select-Object -First 1).Path
    $gitDigest=(Get-FileHash -LiteralPath $gitPath).Hash
    $badGit=if($gitDigest[0] -eq '0'){'1'+$gitDigest.Substring(1)}else{'0'+$gitDigest.Substring(1)}
    if($report.Guard.GitExecutablePath -cne $gitPath -or $report.Guard.GitExecutableSha256 -cne $gitDigest -or $report.BaselineSource.GitExecutablePath -cne $gitPath -or $report.BaselineSource.GitExecutableSha256 -cne $gitDigest){throw 'Conformance Git evidence differs from independent digest.'}
    'PASS Conform retains baseline Git executable identity'
    if(!(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedGitSha256 $gitDigest -DevelopmentOnly)){throw 'Correct Git pin refused'}
    if(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedGitSha256 $badGit -DevelopmentOnly){throw 'Wrong Git pin verified'}
    'PASS VerifyConformance respects independent Git pin'
    $report.BaselineSource.GitExecutableSha256=$badGit
    if(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -DevelopmentOnly){throw 'Inconsistent acquisition evidence verified'}
    $report.BaselineSource.GitExecutableSha256=$gitDigest
    'PASS inconsistent committed-source Git identity rejected'
    $report.Guard.GitExecutablePath='relative-git'
    if($report.VerifyScope($true)){throw 'Relative Git path admitted'}
    $report.Guard.GitExecutablePath=$gitPath
    'PASS malformed Git path refused by scope verification'
    $report.Guard.GitExecutablePath='';$report.Guard.GitExecutableSha256=''
    $report.BaselineSource.GitExecutablePath='';$report.BaselineSource.GitExecutableSha256=''
    if(!$report.VerifyScope($true) -or (& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -ExpectedGitSha256 $gitDigest -DevelopmentOnly)){throw 'Legacy report Git pin policy violated'}
    'PASS legacy scope report cannot satisfy independent Git pin'
    $report.Guard.GitExecutablePath=$gitPath;$report.Guard.GitExecutableSha256=$gitDigest
    $report.BaselineSource.GitExecutablePath=$gitPath;$report.BaselineSource.GitExecutableSha256=$gitDigest
    $argsMap.ExpectedGitSha256=$gitDigest
    $report=& $Compiler @argsMap
    if(!$report.Passed -or !$report.Complete -or !$report.VerifyScope($false) -or $report.VerifyScope($true)){throw 'Full scope failure'}
    'PASS full scope exact mandatory inventory'
    $requirements=$report.Requirements;$observations=$report.Stages
    $report.Requirements=@($requirements | Where-Object Name -CNE 'Tests/Test-Guard.ps1');$report.Stages=@($observations | Where-Object Name -CNE 'Tests/Test-Guard.ps1')
    if(!$report.VerifyStages() -or $report.VerifyScope($false)){throw 'Omitted paired stage was admitted'}
    'PASS paired requirement and stage omission rejected'
    $report.Requirements=$requirements;$report.Stages=$observations
    $report.Requirements=@($requirements[1],$requirements[0]) + @($requirements[2..($requirements.Length-1)]);$report.Stages=@($observations[1],$observations[0]) + @($observations[2..($observations.Length-1)])
    if(!$report.VerifyStages() -or $report.VerifyScope($false)){throw 'Reordered pair admitted'}
    'PASS paired reorder rejected'
    $report.Requirements=$requirements;$report.Stages=$observations
    $digest=$requirements[2].Sha256;$requirements[2].Sha256=$report.CandidateSha256;$observations[2].Sha256=$report.CandidateSha256
    if(!$report.VerifyStages() -or $report.VerifyScope($false)){throw 'Substituted fixture digest admitted'}
    'PASS paired digest substitution rejected'
    $requirements[2].Sha256=$digest;$observations[2].Sha256=$digest
    [IO.File]::WriteAllText($candidate,$text.Replace('param([string]$Compiler)','param([string]$Compiler) # changed'))
    $report=& $Compiler @argsMap -DevelopmentOnly
    if(!$report.Passed -or !$report.VerifyScope($true) -or $report.Requirements.Count -ne 11){throw 'Supplementary scope failure'}
    'PASS changed resources require supplementary inventory'
    if(!(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -DevelopmentOnly)){throw 'Verified source inventory refused'}
    'PASS independently pinned source inventories verified after cleanup'
    $reportedCandidate=$report.CandidateResources
    $savedRequirements=$report.Requirements;$savedStages=$report.Stages
    $report.CandidateResources=$report.BaselineResources
    $report.Requirements=@($savedRequirements | Where-Object { !$_.Name.StartsWith('Candidate/',[StringComparison]::Ordinal) })
    $report.Stages=@($savedStages | Where-Object { !$_.Name.StartsWith('Candidate/',[StringComparison]::Ordinal) })
    if(!$report.VerifyScope($true)){throw 'Paired inventory substitution control did not reproduce scope-only admission'}
    if(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -DevelopmentOnly){throw 'Substituted inventory admitted'}
    'PASS paired resource inventory and supplementary omission rejected by input verification'
    $report.CandidateResources=$reportedCandidate;$report.Requirements=$savedRequirements;$report.Stages=$savedStages
    $report.BaselineSource.Bytes[0]=$report.BaselineSource.Bytes[0] -bxor 1
    if(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $argsMap.ExpectedBaselineSha256 -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -DevelopmentOnly){throw 'Modified retained bytes admitted'}
    'PASS modified committed source bytes rejected'
    $report.BaselineSource.Bytes[0]=$report.BaselineSource.Bytes[0] -bxor 1
    $wrongPin=if($argsMap.ExpectedBaselineSha256[0] -eq '0'){'1'+$argsMap.ExpectedBaselineSha256.Substring(1)}else{'0'+$argsMap.ExpectedBaselineSha256.Substring(1)}
    if(& $Compiler -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidate -ExpectedBaselineSha256 $wrongPin -ExpectedRunnerSha256 $argsMap.ExpectedRunnerSha256 -DevelopmentOnly){throw 'Incorrect external baseline pin admitted'}
    'PASS incorrect independent baseline digest rejected'
    $report.Requirements=@($report.Requirements | Where-Object { !$_.Name.StartsWith('Candidate/',[StringComparison]::Ordinal) });$report.Stages=@($report.Stages | Where-Object { !$_.Name.StartsWith('Candidate/',[StringComparison]::Ordinal) })
    if(!$report.VerifyStages() -or $report.VerifyScope($true)){throw 'Supplementary omission admitted'}
    'PASS supplementary omission rejected'
}finally{[IO.Directory]::Delete($root,$true)}
}
