                [bool]$duplicate=$false
                foreach($prior in $items){
                    [bool]$same=$true
                    for([int]$i=0;$i -lt $Arity;$i++){
                        if(![string]::Equals($prior.ParameterTypeIdentities[$i],$member.ParameterTypeIdentities[$i],[StringComparison]::Ordinal) -or [string]::IsNullOrEmpty($member.ParameterTypeIdentities[$i])){$same=$false;break}
                    }
                    if($same){$duplicate=$true;break}
