    [ScriptTypeMember] Find([string]$Name,[string[]]$Parameters){
        [ScriptTypeMember]$result=$null
        foreach($member in $this.Members){
            if(![string]::Equals($member.Name,$Name,[StringComparison]::OrdinalIgnoreCase) -or !$member.Operation -or $member.ParameterTypes.Length -ne $Parameters.Length){continue}
            [bool]$same=$true
            for([int]$i=0;$i -lt $Parameters.Length;$i++){
                if(![string]::Equals($member.ParameterTypes[$i],$Parameters[$i],[StringComparison]::OrdinalIgnoreCase)){$same=$false;break}
            }
            if($same){if($null -ne $result){return $null};$result=$member}
        }
        return $result
    }
}
# Keep the original AST witness, its STS owner/member and the compatibility
# signature together. These are authoring records, not additional runtime types.
class PscMaterializedSignature {
    [System.Management.Automation.Language.MemberAst] $Declaration
    [ScriptTypeContract] $Owner
    [ScriptTypeMember] $Member
    [type] $Result
    [type[]] $Parameters
}
