        for([int]$i=0;$i -lt $members.Length;$i++){
            foreach($call in $this.Calls){
                if(![object]::ReferenceEquals($call.Member,$members[$i])){continue}
                if($null -ne $result[$i] -or $null -eq $call.Target -or $call.Parameters.Length -ne $Arity){throw [InvalidOperationException]::new('Invalid call realization')}
                for([int]$j=0;$j -lt $Arity;$j++){
                    if($null -eq $call.Parameters[$j] -or ![string]::Equals($call.Parameters[$j].AssemblyQualifiedName,$members[$i].ParameterTypeIdentities[$j],[StringComparison]::Ordinal)){throw [InvalidOperationException]::new('Unresolved or incompatible source signature')}
                }
                $result[$i]=$call
            }
            if($null -eq $result[$i]){throw [InvalidOperationException]::new('Incomplete source overload realization')}
        }
        return $result
    }
    [Delegate] Find([string]$Name){
        if($this.Operations.ContainsKey($Name)){return $this.Operations[$Name]}
        return $null
    }
}
# A named VOM reference is a location, not a concrete provider identity.
class ScriptTypeRole {
    [Vom] $Space
    [uint64] $Owner
    [string] $Name
    ScriptTypeRole([Vom]$Space,[uint64]$Owner,[string]$Name){$this.Space=$Space;$this.Owner=$Owner;$this.Name=$Name}
}
class ScriptTypeReflection {
    static [object] InvokeRole([ScriptTypeRole]$Role,[string]$SourceContract,[string]$Member,[object[]]$Arguments){
        [ScriptTypeContract]$expected=[ScriptTypeCatalog]::Find($SourceContract)
        if($null -eq $expected){throw [InvalidOperationException]::new('Source contract not loaded')}
        return [ScriptTypeReflection]::InvokeDeclared($Role.Space,$Role.Owner,$Role.Name,$Member,$Arguments,$expected)
    }
    static [object] Invoke([Vom]$Space,[uint64]$Owner,[string]$Name,[string]$Member,[object[]]$Arguments){
        return [ScriptTypeReflection]::InvokeDeclared($Space,$Owner,$Name,$Member,$Arguments,$null)
    }
    static [object] InvokeDeclared([Vom]$Space,[uint64]$Owner,[string]$Name,[string]$Member,[object[]]$Arguments,[ScriptTypeContract]$Expected){
        [VomLease]$lease=$Space.Open($Owner,$Name,[ScriptTypeRealization])
        try{
            [ScriptTypeRealization]$realization=$lease.Value
            [VomPairLease]$dependencies=$Space.OpenPair($realization.ContractHandle,[ScriptTypeContract],$realization.ReceiverHandle,[object])
            try{
                [ScriptTypeContract]$contract=$dependencies.First
                if($null -ne $Expected -and ![object]::ReferenceEquals($Expected,$contract)){throw [InvalidOperationException]::new('Role does not realize the declared source contract')}
                [ScriptTypeCall[]]$calls=$realization.Candidates($contract,$Member,$Arguments.Length)
                [ScriptTypeCall]$exact=[ScriptTypeReflection]::Exact($calls,$Arguments)
                if($null -ne $exact){return $exact.Target.Invoke($dependencies.Second,$Arguments)}
                [VomLease]$semantics=$Space.Open($Owner,'ScriptType.Binding',[ScriptTypeBindingExtension])
                try{
                    [ScriptTypeBindingExtension]$extension=$semantics.Value
                    return [ScriptTypeReflection]::InvokeConverted($extension,$calls,$dependencies.Second,$Arguments)
                }finally{$Space.Close($semantics)}
            }finally{$Space.ClosePair($dependencies)}
        }finally{$Space.Close($lease)}
    }
    hidden static [ScriptTypeCall] Exact([ScriptTypeCall[]]$Calls,[object[]]$Arguments){
        [ScriptTypeCall]$exact=$null
        foreach($call in $Calls){
            [bool]$matches=$true
            for([int]$i=0;$i -lt $Arguments.Length;$i++){
                if($null -eq $Arguments[$i] -or $Arguments[$i].GetType() -ne $call.Parameters[$i]){$matches=$false;break}
            }
            if($matches){if($null -ne $exact){throw [InvalidOperationException]::new('Ambiguous exact operation')};$exact=$call}
        }
        return $exact
    }
    hidden static [object] InvokeConverted([ScriptTypeBindingExtension]$Extension,[ScriptTypeCall[]]$Calls,[object]$Receiver,[object[]]$Arguments){
        [int]$index=$Extension.SelectBound($Calls,$Arguments)
        if($index -lt 0 -or $index -ge $Calls.Length){throw [InvalidOperationException]::new('Invalid selected operation')}
        return [ScriptTypeReflection]::InvokeSelected($Extension,$Calls[$index],$Receiver,$Arguments)
    }
    hidden static [object] InvokeSelected([ScriptTypeBindingExtension]$Extension,[ScriptTypeCall]$Selected,[object]$Receiver,[object[]]$Arguments){
        [object[]]$values=[object[]]::new($Arguments.Length)
        for([int]$i=0;$i -lt $values.Length;$i++){
            if($null -ne $Arguments[$i] -and $Arguments[$i].GetType() -eq $selected.Parameters[$i]){$values[$i]=$Arguments[$i]}
            else{$values[$i]=$Extension.Convert.Invoke($Arguments[$i],$selected.Parameters[$i])}
        }
        return $selected.Target.Invoke($Receiver,$values)
    }
    # Shape comparisons use runtime Type identity, not names. All references to
    # arbitrary types and targets in this path are local to the admitted region.
    hidden static [bool] MatchesShape([type[]]$Types,[object[]]$Arguments){
        for([int]$j=0;$j -lt $Arguments.Length;$j++){
            if($null -eq $Arguments[$j]){if($null -ne $Types[$j]){return $false}}
            elseif($Arguments[$j].GetType() -ne $Types[$j]){return $false}
        }
        return $true
    }
    # One explicitly admitted operation, not N independently acquired invocations.
    # No lease or executable session escapes this method.
    static [object[]] InvokeRegion([ScriptTypeRole]$Role,[string]$SourceContract,[string]$Member,[object[][]]$Rows){
        return [ScriptTypeReflection]::InvokeRegion($Role,$SourceContract,$Member,$Rows,$true)
    }
    # The unspecialized path is retained as a differential/performance control.
    static [object[]] InvokeRegion([ScriptTypeRole]$Role,[string]$SourceContract,[string]$Member,[object[][]]$Rows,[bool]$Specialize){
        if($null -eq $Rows -or $Rows.Length -lt 1 -or $Rows.Length -gt 256){throw [ArgumentException]::new('Region requires 1 to 256 argument rows')}
        if($null -eq $Rows[0]){throw [ArgumentException]::new('Null argument row')}
        [int]$arity=$Rows[0].Length
        foreach($row in $Rows){if($null -eq $row -or $row.Length -ne $arity){throw [ArgumentException]::new('Region requires equal arity')}}
        [ScriptTypeContract]$expected=[ScriptTypeCatalog]::Find($SourceContract)
        if($null -eq $expected){throw [InvalidOperationException]::new('Source contract not loaded')}
        [Vom]$space=$Role.Space
        [uint64]$owner=$Role.Owner
        [VomLease]$lease=$space.Open($owner,$Role.Name,[ScriptTypeRealization])
        try{
            [ScriptTypeRealization]$realization=$lease.Value
            [VomPairLease]$dependencies=$space.OpenPair($realization.ContractHandle,[ScriptTypeContract],$realization.ReceiverHandle,[object])
            try{
                [ScriptTypeContract]$contract=$dependencies.First
                if(![object]::ReferenceEquals($expected,$contract)){throw [InvalidOperationException]::new('Role does not realize the declared source contract')}
                [ScriptTypeCall[]]$calls=$realization.Candidates($contract,$Member,$arity)
                [object[]]$results=[object[]]::new($Rows.Length)
                [VomLease]$semantics=$null
                [ScriptTypeBindingExtension]$extension=$null
                [ScriptTypeCall]$priorExact=$null
                [ScriptTypeCall]$priorSelected=$null
                [type[]]$priorSources=$null
                [ScriptTypeCall]$otherSelected=$null
                [type[]]$otherSources=$null
                [Func[ScriptTypeCall[],object[],int]]$priorSelector=$null
                try{
                    for([int]$i=0;$i -lt $Rows.Length;$i++){
                        [object[]]$args=$Rows[$i]
                        # A previously exact call cannot match a null argument.
                        # Its signature is already validated against the contract.
                        if($Specialize -and $null -ne $priorExact -and [ScriptTypeReflection]::MatchesShape($priorExact.Parameters,$args)){
                            $results[$i]=$priorExact.Target.Invoke($dependencies.Second,$args)
                            continue
                        }
                        # Same runtime shape implies the same exact-match outcome,
                        # but only a type-stable selector permits nonexact reuse.
                        if($Specialize -and $null -ne $priorSelected -and $extension.TypeStable -and [object]::ReferenceEquals($priorSelector,$extension.Select)){
                            if([ScriptTypeReflection]::MatchesShape($priorSources,$args)){
                                $results[$i]=[ScriptTypeReflection]::InvokeSelected($extension,$priorSelected,$dependencies.Second,$args)
                                continue
                            }
                            if($null -ne $otherSelected -and [ScriptTypeReflection]::MatchesShape($otherSources,$args)){
                                $results[$i]=[ScriptTypeReflection]::InvokeSelected($extension,$otherSelected,$dependencies.Second,$args)
                                continue
                            }
                        }
                        [ScriptTypeCall]$exact=[ScriptTypeReflection]::Exact($calls,$args)
                        if($null -ne $exact){
                            if($Specialize){$priorExact=$exact}
                            $results[$i]=$exact.Target.Invoke($dependencies.Second,$args)
                        }else{
                            if($null -eq $semantics){$semantics=$space.Open($owner,'ScriptType.Binding',[ScriptTypeBindingExtension]);$extension=$semantics.Value}
                            if(!$Specialize -or !$extension.TypeStable){
                                $results[$i]=[ScriptTypeReflection]::InvokeConverted($extension,$calls,$dependencies.Second,$args)
                            }else{
                                [Func[ScriptTypeCall[],object[],int]]$selector=$extension.Select
                                [int]$index=$extension.SelectBound($calls,$args)
                                if($index -lt 0 -or $index -ge $calls.Length){throw [InvalidOperationException]::new('Invalid selected operation')}
                                [ScriptTypeCall]$selected=$calls[$index]
                                # Rotate the two local slots on a miss. Reuse the
                                # discarded signature array, not converted values.
                                if(![object]::ReferenceEquals($priorSelector,$selector)){$priorSelected=$null;$otherSelected=$null}
                                [type[]]$reuse=$otherSources
                                $otherSources=$priorSources;$otherSelected=$priorSelected
                                $priorSources=$reuse
                                if($null -eq $priorSources){$priorSources=[type[]]::new($arity)}
                                for([int]$j=0;$j -lt $arity;$j++){
                                    $priorSources[$j]=$null
                                    if($null -ne $args[$j]){$priorSources[$j]=$args[$j].GetType()}
                                }
                                $priorSelected=$selected;$priorSelector=$selector
                                $results[$i]=[ScriptTypeReflection]::InvokeSelected($extension,$selected,$dependencies.Second,$args)
                            }
                        }
                    }
                    return $results
                }finally{if($null -ne $semantics){$space.Close($semantics)}}
            }finally{$space.ClosePair($dependencies)}
        }finally{$space.Close($lease)}
    }
    # The caller holds the realization lease for this whole operation.
    # The returned lease owns the descriptor; it must be closed by the caller.
    static [VomLease] OpenContract([Vom]$Space,[ScriptTypeRealization]$Realization,[type]$ContractType){
        return $Space.Open($Realization.ContractHandle,$ContractType)
    }
    static [VomLease] OpenReceiver([Vom]$Space,[ScriptTypeRealization]$Realization,[type]$ObjectType){
        return $Space.Open($Realization.ReceiverHandle,$ObjectType)
    }
}
# PSC emits the source contract graph into this field at build time.
class ScriptTypeCatalog {
    static [ScriptTypeContract[]] $Contracts
    static [ScriptTypeContract] Find([string]$Name){
        foreach($contract in [ScriptTypeCatalog]::Contracts){
            if([string]::Equals($contract.Name,$Name,[StringComparison]::OrdinalIgnoreCase)){return $contract}
        }
        return $null
    }
}

# Faculty: PrimitiveConversion.ps1
# Independently lowered fixed-arity binding capability. Primitive conversions
# compatible reference conversions and bounded vector/list conversion are supported.
class ScriptTypePrimitiveConversion {
    static [bool] IsNumber([type]$Type){
        return $Type -eq [sbyte] -or $Type -eq [byte] -or $Type -eq [short] -or $Type -eq [ushort] -or $Type -eq [int] -or $Type -eq [uint] -or $Type -eq [long] -or $Type -eq [ulong] -or $Type -eq [single] -or $Type -eq [double] -or $Type -eq [decimal]
    }
    # Fixed-arity primitive conversion ranks, verified against SMA in the test only.
    static [int] Rank([type]$Source,[type]$Target){
        if($null -eq $Target){throw [ArgumentNullException]::new('Target')}
        if($null -eq $Source){
            if($Target -eq [string]){return 31}
            if(!$Target.IsValueType){return 191}
            if($Target -eq [bool] -or [ScriptTypePrimitiveConversion]::IsNumber($Target)){return 175}
            return -1
        }
        if($Source -eq $Target){return 287}
        if($Target.IsAssignableFrom($Source)){return 271}
        # Arrays are reference objects, but PowerShell also admits scalar wrapping
        # and element-wise conversion. Limit conversion to zero-based vectors.
        if($Target.IsSZArray){
            [type]$element=$Target.GetElementType()
            if($Source.IsSZArray){
                if($element.IsAssignableFrom($Source.GetElementType())){return 159}
                return 15
            }
            if([Collections.IList].IsAssignableFrom($Source)){return 159}
            if($Source.IsArray){return -1}
            [int]$er=[ScriptTypePrimitiveConversion]::Rank($Source,$element)
            if($er -lt 0){return -1}
            if($Source -eq [bool] -and $element -eq [string]){return 63}
            if($er -le 0 -or $er -eq 63){return $er}
            return $er -band (-9)
        }
        if($Target -eq [array]){
            if([Collections.IList].IsAssignableFrom($Source)){return 159}
            if([ScriptTypePrimitiveConversion]::IsPrimitive($Source)){return 263}
            return -1
        }
        if($Source -eq [int[]] -and $Target -eq [decimal]){return 111}
        if($Source.IsSZArray -or [Collections.IList].IsAssignableFrom($Source)){
            if($Target -eq [bool]){return 159}
            if($Target -eq [string]){return 31}
            if([ScriptTypePrimitiveConversion]::IsNumber($Target)){return 0}
        }
        [bool]$sn=[ScriptTypePrimitiveConversion]::IsNumber($Source)
        [bool]$tn=[ScriptTypePrimitiveConversion]::IsNumber($Target)
        if($Target -eq [bool] -and ($sn -or $Source -eq [string] -or $Source -eq [object])){return 159}
        if($Target -eq [string]){
            if($sn){return 239}
            if($Source -eq [bool] -or $Source -eq [object]){return 31}
            return -1
        }
        if($tn){
            if($Source -eq [string]){return 239}
            if($Source -eq [bool]){return 63}
            if($Source -eq [object]){return 0}
            if($sn){
                [int]$s=[int][type]::GetTypeCode($Source)
                [int]$t=[int][type]::GetTypeCode($Target)
                if($s -le 12){
                    if($t -ge 13){return 255}
                    if($t -gt $s){
                        if(($s % 2) -eq 1 -and ($t % 2) -eq 0){return 223}
                        return 255
                    }
                    return 207
                }
                if($s -eq 13 -and $t -eq 14){return 255}
                if($s -eq 15 -and ($t -eq 13 -or $t -eq 14)){return 223}
                return 207
            }
        }
        return -1
    }
    static [int] Compare([type[]]$A,[type[]]$B,[type[]]$Sources){
        [int]$score=0
        for([int]$i=0;$i -lt $Sources.Length;$i++){
            [int]$ra=[ScriptTypePrimitiveConversion]::Rank($Sources[$i],$A[$i])
            [int]$rb=[ScriptTypePrimitiveConversion]::Rank($Sources[$i],$B[$i])
            [int]$weight=$Sources.Length-$i
            if($ra -gt $rb){$score+=$weight}
            elseif($ra -lt $rb){$score-=$weight}
        }
        if($score -ne 0){return $score}
        for([int]$i=0;$i -lt $Sources.Length;$i++){
            [int]$ra=[ScriptTypePrimitiveConversion]::Rank($Sources[$i],$A[$i])
            [int]$rb=[ScriptTypePrimitiveConversion]::Rank($Sources[$i],$B[$i])
            if($ra -lt 175 -or $rb -lt 175){continue}
            if(($ra -ge 255) -ne ($rb -ge 255)){continue}
            [int]$ab=[ScriptTypePrimitiveConversion]::Rank($A[$i],$B[$i])
            [int]$ba=[ScriptTypePrimitiveConversion]::Rank($B[$i],$A[$i])
            # When two reference candidates are related by assignment, that
            # relation outranks any ordinary conversion in the opposite direction.
            # This does not assert a rank for the unknown reverse conversion.
            if($ab -lt 0 -or $ba -lt 0){
                if([ScriptTypePrimitiveConversion]::IsReference($A[$i]) -and [ScriptTypePrimitiveConversion]::IsReference($B[$i])){
                    if($ab -eq 271 -and $ba -lt 0){$ba=0}
                    elseif($ba -eq 271 -and $ab -lt 0){$ab=0}
                    else{throw [NotSupportedException]::new('Unresolved reference parameter comparison')}
                }else{throw [NotSupportedException]::new('Unresolved parameter comparison')}
            }
            [int]$weight=$Sources.Length-$i
            if($ra -ge 255){$weight=-$weight}
            if($ab -lt $ba){$score+=$weight}
            elseif($ab -gt $ba){$score-=$weight}
        }
        return $score
    }
    static [bool] IsPrimitive([type]$Type){
        return $Type -eq [object] -or $Type -eq [bool] -or $Type -eq [string] -or [ScriptTypePrimitiveConversion]::IsNumber($Type)
    }
    static [bool] IsReference([type]$Type){
        return $null -ne $Type -and !$Type.IsValueType -and !$Type.IsArray -and !$Type.IsByRef -and !$Type.IsPointer -and !$Type.ContainsGenericParameters
    }
    static [bool] IsAdmitted([type]$Type){
        return [ScriptTypePrimitiveConversion]::IsPrimitive($Type) -or [ScriptTypePrimitiveConversion]::IsReference($Type) -or $Type.IsSZArray
    }
    static [int] Select([ScriptTypeCall[]]$Candidates,[object[]]$Arguments){
        if($Candidates.Length -eq 0){throw [MissingMethodException]::new('No candidate')}
        if($Candidates.Length -eq 1){
            if($Candidates[0].Parameters.Length -ne $Arguments.Length){throw [ArgumentException]::new('Arity mismatch')}
            return 0
        }
        [type[]]$sources=[type[]]::new($Arguments.Length)
        for([int]$i=0;$i -lt $Arguments.Length;$i++){
            if($null -ne $Arguments[$i]){
                $sources[$i]=$Arguments[$i].GetType()
                if(![ScriptTypePrimitiveConversion]::IsAdmitted($sources[$i])){throw [NotSupportedException]::new('Argument outside supported domain')}
            }
        }
        [type[][]]$signatures=[type[][]]::new($Candidates.Length)
        for([int]$c=0;$c -lt $Candidates.Length;$c++){$signatures[$c]=$Candidates[$c].Parameters}
        return [ScriptTypePrimitiveConversion]::SelectSignatures($signatures,$sources)
    }
    # Resolve only the existing closed compiler compatibility domain. These are
    # canonical CTS primitives, never a source declaration's CLR projection.
    static [type] CompilerPrimitive([ScriptTypeReference]$Reference){
        if($null -eq $Reference -or $Reference.Kind -ne [ScriptTypeReferenceKind]::Clr){return $null}
        foreach($candidate in [type[]]@([sbyte],[byte],[short],[ushort],[int],[uint],[long],[ulong],[single],[double],[object],[string],[bool])){
            if([string]::Equals($Reference.ClrIdentity,$candidate.AssemblyQualifiedName,[StringComparison]::Ordinal)){return $candidate}
        }
        return $null
    }
    static [ScriptTypeBinding] BindDeclared([ScriptTypeContract]$Owner,[string]$Name,[ScriptTypeReference[]]$Arguments,[bool]$Static,[bool]$Constructor){
        if($Static -and $Constructor){return $null}
        [ScriptTypeBinding]$exact=$Owner.BindDeclared($Name,$Arguments,$Static,$Constructor)
        if($null -ne $exact){return $exact}
        if($Arguments.Length -eq 0){return $null}
        [type[]]$sources=[type[]]::new($Arguments.Length)
        for([int]$i=0;$i -lt $Arguments.Length;$i++){
            $sources[$i]=[ScriptTypePrimitiveConversion]::CompilerPrimitive($Arguments[$i])
            if($null -eq $sources[$i] -or ![ScriptTypePrimitiveConversion]::IsNumber($sources[$i])){return $null}
        }
        [Collections.Generic.List[ScriptTypeMember]]$members=[Collections.Generic.List[ScriptTypeMember]]::new()
        [Collections.Generic.List[type[]]]$signatures=[Collections.Generic.List[type[]]]::new()
        foreach($member in $Owner.Members){
            if(!$member.Operation -or $member.Static -ne $Static -or $member.Constructor -ne $Constructor -or ![string]::Equals($member.Name,$Name,[StringComparison]::OrdinalIgnoreCase) -or $null -eq $member.ParameterReferences -or $member.ParameterReferences.Length -ne $Arguments.Length){continue}
            [type[]]$signature=[type[]]::new($Arguments.Length)
            for([int]$i=0;$i -lt $Arguments.Length;$i++){
                $signature[$i]=[ScriptTypePrimitiveConversion]::CompilerPrimitive($member.ParameterReferences[$i])
                if($null -eq $signature[$i]){return $null}
            }
            $members.Add($member);$signatures.Add($signature)
        }
        if($members.Count -eq 0){return $null}
        [int]$index=[ScriptTypePrimitiveConversion]::SelectSignatures($signatures.ToArray(),$sources)
        return [ScriptTypeBinding]::new($Owner,$members[$index],$Arguments)
    }
    # Shared fixed-arity primitive compatibility selection; neither samples nor
    # invocation delegates are needed to select from a statically known signature.
    static [int] SelectSignatures([type[][]]$Signatures,[type[]]$Sources){
        [int]$best=-1
        [bool]$ambiguous=$false
        for([int]$c=0;$c -lt $Signatures.Length;$c++){
            [type[]]$signature=$Signatures[$c]
            if($signature.Length -ne $Sources.Length){throw [ArgumentException]::new('Arity mismatch')}
            [bool]$valid=$true
            for([int]$i=0;$i -lt $signature.Length;$i++){
                if(![ScriptTypePrimitiveConversion]::IsAdmitted($signature[$i])){throw [NotSupportedException]::new('Parameter outside supported domain')}
                [int]$rank=[ScriptTypePrimitiveConversion]::Rank($Sources[$i],$signature[$i])
                if($rank -lt 0){throw [NotSupportedException]::new('Conversion rank outside supported domain')}
                if($rank -eq 0){$valid=$false}
            }
            if(!$valid){continue}
            if($best -lt 0){$best=$c;continue}
            [int]$comparison=[ScriptTypePrimitiveConversion]::Compare($Signatures[$best],$signature,$Sources)
            if($comparison -lt 0){$best=$c;$ambiguous=$false}
            elseif($comparison -eq 0){$ambiguous=$true}
        }
        if($best -lt 0){throw [MissingMethodException]::new('No matching dynamic operation')}
        if($ambiguous){throw [Reflection.AmbiguousMatchException]::new('Ambiguous dynamic operation')}
        return $best
    }
    # Radix, fixed-width suffix and binary multiplier syntax. No source
    # execution is involved: the literal is parsed as data.
    static [object] HexFallback([string]$Digits,[type]$Target){
        if($Target -eq [sbyte]){return [System.Convert]::ToSByte($Digits,16)}
        if($Target -eq [byte]){return [System.Convert]::ToByte($Digits,16)}
        if($Target -eq [short]){return [System.Convert]::ToInt16($Digits,16)}
        if($Target -eq [ushort]){return [System.Convert]::ToUInt16($Digits,16)}
        if($Target -eq [int]){return [System.Convert]::ToInt32($Digits,16)}
        if($Target -eq [uint]){return [System.Convert]::ToUInt32($Digits,16)}
        if($Target -eq [long]){return [System.Convert]::ToInt64($Digits,16)}
        if($Target -eq [ulong]){return [System.Convert]::ToUInt64($Digits,16)}
        throw [OverflowException]::new('Radix conversion overflow')
    }
    static [object] ConvertExtendedNumericText([string]$Text,[type]$Target){
        [string]$v=$Text.ToLowerInvariant()
        [bool]$negative=$v.StartsWith('-')
        [bool]$signed=$negative -or $v.StartsWith('+')
        if($signed){$v=$v.Substring(1)}
        [int]$radix=10
        if($v.StartsWith('0x')){$radix=16;$v=$v.Substring(2)}
        elseif($v.StartsWith('0b')){$radix=2;$v=$v.Substring(2)}
        [long]$multiplier=1
        if($v.EndsWith('kb')){$multiplier=1024}
        elseif($v.EndsWith('mb')){$multiplier=1048576}
        elseif($v.EndsWith('gb')){$multiplier=1073741824}
        elseif($v.EndsWith('tb')){$multiplier=1099511627776}
        elseif($v.EndsWith('pb')){$multiplier=1125899906842624}
        if($multiplier -ne 1){$v=$v.Substring(0,$v.Length-2)}
        [type]$suffix=$null
        [int]$width=0
        [bool]$unsigned=$false
        [int]$suffixLength=0
        if($v.EndsWith('uy')){$suffix=[byte];$width=8;$unsigned=$true;$suffixLength=2}
        elseif($v.EndsWith('us')){$suffix=[ushort];$width=16;$unsigned=$true;$suffixLength=2}
        elseif($v.EndsWith('ul')){$suffix=[ulong];$width=64;$unsigned=$true;$suffixLength=2}
        elseif($v.EndsWith('y')){$suffix=[sbyte];$width=8;$suffixLength=1}
        elseif($v.EndsWith('s')){$suffix=[short];$width=16;$suffixLength=1}
        elseif($v.EndsWith('l')){$suffix=[long];$width=64;$suffixLength=1}
        elseif($v.EndsWith('u')){$unsigned=$true;$suffixLength=1}
        elseif($radix -ne 16 -and $v.EndsWith('d')){$suffix=[decimal];$suffixLength=1}
        if($suffixLength -gt 0){$v=$v.Substring(0,$v.Length-$suffixLength)}
        [Globalization.CultureInfo]$culture=[Globalization.CultureInfo]::InvariantCulture
        [object]$number=$null
        if($radix -ne 10){
            if($v.Length -eq 0){
                if($radix -eq 16 -and $suffixLength -eq 0 -and $multiplier -eq 1){return [Activator]::CreateInstance($Target)}
                throw [FormatException]::new('Missing radix digits')
            }
            for([int]$i=0;$i -lt $v.Length;$i++){
                [char]$ch=$v[$i]
                if($radix -eq 2){if($ch -ne [char]48 -and $ch -ne [char]49){throw [FormatException]::new('Invalid binary digit')}}
                elseif(!(($ch -ge [char]48 -and $ch -le [char]57) -or ($ch -ge [char]97 -and $ch -le [char]102))){throw [FormatException]::new('Invalid hexadecimal digit')}
            }
            [int]$bits=$v.Length
            if($radix -eq 16){$bits=$bits*4}
            [decimal]$magnitude=[System.Convert]::ToDecimal([System.Convert]::ToUInt64($v,$radix))
