# Authoring-time metadata extraction; compiled runtime receives the resulting typed graph.
function Get-ScriptTypeReference {
    [OutputType([ScriptTypeReference])]
    param([System.Management.Automation.Language.ITypeName]$Name,[Collections.Generic.Dictionary[string,ScriptTypeContract]]$Catalog,[type]$DefaultType)
    $reference=[ScriptTypeReference]::new();$reference.Arguments=[ScriptTypeReference[]]::new(0)
    if($null -eq $Name){$reference.Kind=[ScriptTypeReferenceKind]::Clr;$reference.Spelling=$DefaultType.FullName;$reference.ClrIdentity=$DefaultType.AssemblyQualifiedName;return $reference}
    $reference.Spelling=$Name.FullName
    # Source identity takes precedence over imported runtime types.
    if(!$Name.AssemblyName -and $Catalog.ContainsKey($Name.FullName)){$reference.Kind=[ScriptTypeReferenceKind]::Source;$reference.Definition=$Catalog[$Name.FullName];return $reference}
    if($Name -is [System.Management.Automation.Language.ArrayTypeName]){
        $reference.Kind=[ScriptTypeReferenceKind]::Array;$reference.Rank=$Name.Rank
        $reference.Element=Get-ScriptTypeReference $Name.ElementType $Catalog ([object])
        if(!$reference.Element.ClrIdentity){return $reference}
    }elseif($Name -is [System.Management.Automation.Language.GenericTypeName]){
        $reference.Kind=[ScriptTypeReferenceKind]::Generic
        $reference.Element=Get-ScriptTypeReference $Name.TypeName $Catalog ([object])
        $reference.Arguments=@(foreach($argument in $Name.GenericArguments){Get-ScriptTypeReference $argument $Catalog ([object])})
        if($reference.Element.Kind -eq [ScriptTypeReferenceKind]::Source){return $reference}
        foreach($argument in $reference.Arguments){if(!$argument.ClrIdentity){return $reference}}
    }
    $resolved=$Name.GetReflectionType()
    if($null -ne $resolved){
        $reference.ClrIdentity=$resolved.AssemblyQualifiedName
        if($reference.Kind -eq [ScriptTypeReferenceKind]::Generic -and $resolved.IsGenericType){
            $reference.Element.Kind=[ScriptTypeReferenceKind]::Clr;$reference.Element.ClrIdentity=$resolved.GetGenericTypeDefinition().AssemblyQualifiedName
        }
        if($reference.Kind -eq [ScriptTypeReferenceKind]::Unresolved){$reference.Kind=[ScriptTypeReferenceKind]::Clr}
    }
    return $reference
}
function Get-ScriptTypeContract {
    param([string[]]$Paths,[System.Management.Automation.Language.TypeDefinitionAst[]]$DefinitionAsts,[switch]$SignaturesOnly,[ScriptTypeContract[]]$ImportedContracts)
    $definitions=[Collections.Generic.List[System.Management.Automation.Language.TypeDefinitionAst]]::new()
    if($null -ne $DefinitionAsts -and $DefinitionAsts.Length){$definitions.AddRange($DefinitionAsts)}
    foreach($path in $Paths){
        $tokens=$null;$errors=$null
        $root=[System.Management.Automation.Language.Parser]::ParseFile($path,[ref]$tokens,[ref]$errors)
        if($errors.Count){throw "Invalid source: $path"}
        foreach($definition in $root.EndBlock.Statements){if($definition -is [System.Management.Automation.Language.TypeDefinitionAst] -and $definition.IsClass){$definitions.Add($definition)}}
    }
    $catalog=[Collections.Generic.Dictionary[string,ScriptTypeContract]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($shape in $definitions){
        if($catalog.ContainsKey($shape.Name)){throw "Duplicate declaration: $($shape.Name)"}
        $description=[ScriptTypeContract]::new();$description.Name=$shape.Name;$description.Source=$shape.Extent.Text
        $catalog.Add($shape.Name,$description)
    }
    # Imported definitions are the original retained objects, not copies. Local
    # declarations take precedence in the same way as the scope's CLR projection.
    foreach($imported in $ImportedContracts){$null=$catalog.TryAdd($imported.Name,$imported)}
    foreach($shape in $definitions){
        $required=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        if(!$SignaturesOnly){foreach($owner in $definitions){foreach($method in $owner.Members){
            if($method -isnot [System.Management.Automation.Language.FunctionMemberAst]){continue}
            foreach($parameter in $method.Parameters){
                $constraint=$parameter.Attributes|Where-Object {$_ -is [System.Management.Automation.Language.TypeConstraintAst]}|Select-Object -First 1
                if(!$constraint -or $constraint.TypeName.FullName -ine $shape.Name){continue}
                foreach($member in $method.Body.FindAll({param($n) $n -is [System.Management.Automation.Language.MemberExpressionAst]},$true)){
                    if($member.Expression -is [System.Management.Automation.Language.VariableExpressionAst] -and $member.Expression.VariablePath.UserPath -ieq $parameter.Name.VariablePath.UserPath -and $member.Member -is [System.Management.Automation.Language.StringConstantExpressionAst]){$null=$required.Add($member.Member.Value)}
                }
            }
        }}}
        $description=$catalog[$shape.Name];$description.BaseTypes=@($shape.BaseTypes|ForEach-Object {$_.TypeName.FullName})
        $description.BaseReferences=@(foreach($baseType in $shape.BaseTypes){Get-ScriptTypeReference $baseType.TypeName $catalog ([object])})
        $description.Members=@(foreach($member in $shape.Members){
            $item=[ScriptTypeMember]::new();$item.Name=$member.Name;$item.Required=$required.Contains($item.Name);$item.Declaration=$member.Extent.Text;$item.Static=$member.IsStatic;$item.Hidden=$member.IsHidden
            if($member -is [System.Management.Automation.Language.FunctionMemberAst]){
                $item.Operation=$true;$item.Constructor=$member.IsConstructor;$item.ResultType=if($member.ReturnType){$member.ReturnType.TypeName.FullName}else{'void'}
                $item.ParameterTypes=@(foreach($parameter in $member.Parameters){$tc=$parameter.Attributes|Where-Object {$_ -is [System.Management.Automation.Language.TypeConstraintAst]}|Select-Object -First 1;if($tc){$tc.TypeName.FullName}else{'object'}})
                $item.ParameterNames=@($member.Parameters|ForEach-Object {$_.Name.VariablePath.UserPath})
                $item.ResultReference=Get-ScriptTypeReference $(if($member.ReturnType){$member.ReturnType.TypeName}) $catalog ([void])
                $item.ParameterReferences=@(foreach($parameter in $member.Parameters){$tc=$parameter.Attributes|Where-Object {$_ -is [System.Management.Automation.Language.TypeConstraintAst]}|Select-Object -First 1;Get-ScriptTypeReference $(if($tc){$tc.TypeName}) $catalog ([object])})
                $item.ResultTypeIdentity=$item.ResultReference.ClrIdentity
                $item.ParameterTypeIdentities=@(foreach($reference in $item.ParameterReferences){$reference.ClrIdentity})
            }else{$item.ResultType=if($member.PropertyType){$member.PropertyType.TypeName.FullName}else{'object'};$item.ParameterTypes=@();$item.ParameterNames=@();$item.ParameterTypeIdentities=@();$item.ResultReference=Get-ScriptTypeReference $(if($member.PropertyType){$member.PropertyType.TypeName}) $catalog ([object]);$item.ResultTypeIdentity=$item.ResultReference.ClrIdentity;$item.ParameterReferences=[ScriptTypeReference[]]::new(0)}
            $item
        })
    }
    foreach($shape in $definitions){
        $description=$catalog[$shape.Name]
        $description.BaseContracts=@(foreach($baseName in $description.BaseTypes){if($catalog.ContainsKey($baseName)){$catalog[$baseName]}})
    }
    foreach($shape in $definitions){$catalog[$shape.Name]}
}

    # Translate the caller's CLR expression type at the compatibility boundary.
    # A projected source class is identified by its scope's actual type, never
    # by spelling or an assembly-qualified name of the temporary projection.
    function ConvertTo-PscBindingReference {
        [OutputType([ScriptTypeReference])]
        param([type]$Type,[PscDeclarationScope[]]$Scopes)
        if($null -eq $Type -or $Type.IsPointer -or $Type.IsByRef -or $Type.ContainsGenericParameters){return $null}
        $reference=[ScriptTypeReference]::new();$reference.Spelling=$Type.FullName;$reference.Arguments=[ScriptTypeReference[]]::new(0)
        if($Type.IsArray){
            if($Type.GetArrayRank() -eq 1 -and !$Type.IsSZArray){return $null}
            $reference.Kind=[ScriptTypeReferenceKind]::Array;$reference.Rank=$Type.GetArrayRank()
            $reference.Element=ConvertTo-PscBindingReference $Type.GetElementType() $Scopes
            if($null -eq $reference.Element){return $null};return $reference
        }
        if($Type.IsConstructedGenericType){
            $reference.Kind=[ScriptTypeReferenceKind]::Generic
            $generic=$Type.GetGenericTypeDefinition()
            if($generic.Assembly.IsDynamic){return $null}
            $reference.Element=[ScriptTypeReference]::new();$reference.Element.Kind=[ScriptTypeReferenceKind]::Clr;$reference.Element.Spelling=$generic.FullName;$reference.Element.ClrIdentity=$generic.AssemblyQualifiedName
            $arguments=$Type.GetGenericArguments();$reference.Arguments=[ScriptTypeReference[]]::new($arguments.Length)
            for($i=0;$i -lt $arguments.Length;$i++){
                $reference.Arguments[$i]=ConvertTo-PscBindingReference $arguments[$i] $Scopes
                if($null -eq $reference.Arguments[$i]){return $null}
            }
            return $reference
        }
        if($Type.Assembly.IsDynamic){
            foreach($scope in $Scopes){
                if($null -eq $scope -or $scope.Types[$Type.Name] -ne $Type){continue}
                foreach($definition in $scope.Contracts.Keys){
                    if($definition.Name -ieq $Type.Name){$reference.Kind=[ScriptTypeReferenceKind]::Source;$reference.Definition=$scope.Contracts[$definition];return $reference}
                }
            }
            return $null
        }
        $reference.Kind=[ScriptTypeReferenceKind]::Clr;$reference.ClrIdentity=$Type.AssemblyQualifiedName
        if(!$reference.ClrIdentity){return $null};return $reference
    }
    if($null -ne $BindingOwner){
        $contract=$DeclarationScope.Contracts[$BindingOwner]
        $references=[ScriptTypeReference[]]::new($BindingArguments.Length)
        for($i=0;$i -lt $references.Length;$i++){
            $references[$i]=ConvertTo-PscBindingReference $BindingArguments[$i] $BindingScopes
            if($null -eq $references[$i]){return $null}
        }
        $exact=$contract.BindDeclared($BindingName,$references,$BindingStatic,$BindingConstructor)
        if($null -ne $exact){return $exact}
        return Get-PscOtherFacultyDeclarations -BindingContract $contract -BindingName $BindingName -BindingReferences $references -BindingStatic $BindingStatic -BindingConstructor $BindingConstructor
    }
    # This is a CLR realization adapter, not a semantic binding operation. Only
    # source-owned leaves use the selected definition map; existing imported and
    # unsupported type forms retain the compatibility resolver during migration.
    function ConvertTo-PscMaterializedSignatureType {
        [OutputType([type])]
        param([ScriptTypeReference]$Reference,[System.Management.Automation.Language.ITypeName]$Witness,[Collections.Generic.Dictionary[ScriptTypeContract,type]]$Types,[type]$DefaultType)
        if($Reference.Kind -eq [ScriptTypeReferenceKind]::Source){
            if(!$Types.ContainsKey($Reference.Definition)){throw 'Missing selected STS definition realization'}
            return $Types[$Reference.Definition]
        }
        if($Reference.Kind -eq [ScriptTypeReferenceKind]::Array){
            $element=ConvertTo-PscMaterializedSignatureType $Reference.Element $Witness.ElementType $Types ([object])
            if($Reference.Rank -eq 1){return $element.MakeArrayType()}
            return $element.MakeArrayType($Reference.Rank)
        }
        if($Reference.Kind -eq [ScriptTypeReferenceKind]::Generic){
            $arguments=[type[]]@(for($index=0;$index -lt $Reference.Arguments.Length;$index++){
                ConvertTo-PscMaterializedSignatureType $Reference.Arguments[$index] $Witness.GenericArguments[$index] $Types ([object])
            })
            $generic=Resolve-AstType ('{0}`{1}' -f $Witness.TypeName.FullName,$arguments.Length)
            return $generic.MakeGenericType($arguments)
        }
        if($null -eq $Witness){return $DefaultType}
        return Resolve-AstType $Witness
    }
    if($null -ne $SelectionSignatures){return Get-PscOtherFacultyDeclarations -SelectionSignatures $SelectionSignatures -SelectionSources $SelectionSources}
    if($null -ne $DeclarationScope -or ($null -ne $CompilerClassAsts -and $CompilerClassAsts.Length)){
        if($null -ne $ContractPaths -and $ContractPaths.Length -or $null -eq $MaterializedTypes){throw 'Compiler signature realization requires one selected source scope'}
        $retainedContracts=[Collections.Generic.Dictionary[System.Management.Automation.Language.TypeDefinitionAst,ScriptTypeContract]]::new()
        $retainedSignatures=[Collections.Generic.Dictionary[System.Management.Automation.Language.MemberAst,PscMaterializedSignature]]::new()
        $imported=[ScriptTypeContract[]]@()
        $types=[Collections.Generic.Dictionary[ScriptTypeContract,type]]::new()
        if($null -ne $DeclarationScope -and $null -ne $DeclarationScope.Resolving){
            $imported=[ScriptTypeContract[]]@($DeclarationScope.Resolving.Contracts.Values)
            foreach($contract in $imported){$types.Add($contract,$DeclarationScope.Resolving.Types[$contract.Name])}
        }
        $contracts=@(Get-ScriptTypeContract -DefinitionAsts $CompilerClassAsts -SignaturesOnly -ImportedContracts $imported)
        foreach($contract in $contracts){
            if(!$MaterializedTypes.ContainsKey($contract.Name)){throw 'Missing selected CLR type builder'}
            $types.Add($contract,$MaterializedTypes[$contract.Name])
        }
        for($ownerIndex=0;$ownerIndex -lt $CompilerClassAsts.Length;$ownerIndex++){
            $owner=$CompilerClassAsts[$ownerIndex];$contract=$contracts[$ownerIndex]
            $retainedContracts.Add($owner,$contract)
            if($owner.Members.Count -ne $contract.Members.Length){throw 'STS member inventory differs from source'}
            for($memberIndex=0;$memberIndex -lt $owner.Members.Count;$memberIndex++){
                $member=$owner.Members[$memberIndex];$descriptor=$contract.Members[$memberIndex]
                $signature=[PscMaterializedSignature]::new();$signature.Declaration=$member;$signature.Owner=$contract;$signature.Member=$descriptor
                if($member -is [System.Management.Automation.Language.FunctionMemberAst]){
                    $signature.Result=ConvertTo-PscMaterializedSignatureType $descriptor.ResultReference $(if($member.ReturnType){$member.ReturnType.TypeName}) $types ([void])
                    $isFunction=Test-ScriptFunctionMember $member
                    $signature.Parameters=@(for($parameterIndex=0;$parameterIndex -lt $member.Parameters.Count;$parameterIndex++){
                        $constraint=$member.Parameters[$parameterIndex].Attributes|Where-Object {$_ -is [System.Management.Automation.Language.TypeConstraintAst]}|Select-Object -First 1
                        $realized=ConvertTo-PscMaterializedSignatureType $descriptor.ParameterReferences[$parameterIndex] $(if($constraint){$constraint.TypeName}) $types ([object])
                        if($isFunction -and $realized -eq [System.Management.Automation.SwitchParameter]){[bool]}else{$realized}
                    })
                }else{
                    $signature.Result=ConvertTo-PscMaterializedSignatureType $descriptor.ResultReference $(if($member.PropertyType){$member.PropertyType.TypeName}) $types ([object])
                    $signature.Parameters=[type[]]::new(0)
                }
                $retainedSignatures.Add($member,$signature)
                $signature
            }
        }
        if($null -ne $DeclarationScope){$DeclarationScope.Contracts=$retainedContracts;$DeclarationScope.Signatures=$retainedSignatures}
    }elseif ($ContractPaths.Count) { Get-ScriptTypeContract -Paths $ContractPaths }
}

# The compilation-unit boundary remains explicit: one physical source does not require one CLR assembly.
class PscFacultyUnit {
    [string] $Name
    [string] $Primary
    [string[]] $Declarations
    [string[]] $Dependencies
    PscFacultyUnit([string]$name,[string]$primary,[string[]]$declarations,[string[]]$dependencies){
        $this.Name=$name; $this.Primary=$primary; $this.Declarations=$declarations; $this.Dependencies=$dependencies
    }
}
function Get-PscFacultyUnits {
    [PscFacultyUnit]::new('Vom','Vom',@('VomState','VomRetention','VomCell','VomInfo','VomLease','VomPairLease','Vom','VomFence'),@())
    [PscFacultyUnit]::new('InquiryPrimitives','InquiryCase',@('InquirySourceCleanReference','InquiryAxis','InquiryPredictiveScalar','InquiryOrigin','InquiryBlock','InquiryReading','InquiryCase','InquirySemanticAttachment','InquiryExecutionTier','InquiryReliance','InquiryWhenClause','InquiryJudgment'),@())
    [PscFacultyUnit]::new('ScriptType','ScriptTypeReflection',@('ScriptTypeReferenceKind','ScriptTypeReference','ScriptTypeMember','ScriptTypeBinding','ScriptTypeContract','ScriptTypeCall','ScriptTypeSelectionMemo','ScriptTypeBindingExtension','ScriptTypeSmaSelector','ScriptTypeRealization','ScriptTypeRole','ScriptTypeReflection','ScriptTypeCatalog'),@('Vom'))
    [PscFacultyUnit]::new('PrimitiveConversion','ScriptTypePrimitiveConversion',@('ScriptTypePrimitiveConversion'),@('Vom','ScriptType'))
    [PscFacultyUnit]::new('ObjectDispatch','ScriptTypeObjectDispatch',@('ScriptTypeObjectDispatch'),@('Vom','InquiryPrimitives','ScriptType'))
    [PscFacultyUnit]::new('NativeEncoding','PscNativeEncoding',@('PscNativeInstruction','PscNativeEncoding','HexagonForm','HexagonFields','HexagonDecoded','HexagonPatternEncoder'),@())
    [PscFacultyUnit]::new('ElfEncoding','PscElfEncoding',@('PscElfLayout','PscElfStringTable','PscElfEncoding','PscElfExport','PscElfCodeLibrary','PscElfProgramRecord','PscElfSectionRecord','PscElfSymbolRecord','PscElfImageRecord','PscElfImageReader'),@())
}
function Build-PscFaculty {
    param([string]$Faculty,[string]$RuntimeDirectory,[string[]]$ContractPaths,[string[]]$ContractReferences)
    $unit = @(Get-PscFacultyUnits | Where-Object Name -ceq $Faculty)
    if ($unit.Count -ne 1) { throw "Unknown PSC faculty: $Faculty" }
    $unit = $unit[0]
    [void][IO.Directory]::CreateDirectory($RuntimeDirectory)
    [void][Reflection.Assembly]::LoadFrom((Join-Path $PSHOME 'Microsoft.PowerShell.Commands.Utility.dll'))
    foreach ($dependency in $unit.Dependencies) {
        [void][Reflection.Assembly]::LoadFrom((Join-Path $RuntimeDirectory ($dependency+'.dll')))
    }
    # Select the original parser-owned declarations. Reparse only their extents as an independent
    # compilation unit so the other faculties' enums and source type names cannot shadow CLR identities.
    $holder = (Get-Command Get-PscFacultyDeclarations -CommandType Function).ScriptBlock.Ast
    if ($holder -is [System.Management.Automation.Language.FunctionDefinitionAst]) { $holder = $holder.Body }
    $declarations = @($holder.FindAll({ param($node) $node -is [System.Management.Automation.Language.TypeDefinitionAst] }, $true) | Where-Object { $_.Name -cin $unit.Declarations })
    if ($declarations.Count -ne $unit.Declarations.Length) { throw "Incomplete declaration set for $Faculty" }
    $source = [string]::Join("`n",[string[]]@($declarations | ForEach-Object { $_.Extent.Text }))
    $parsed = Read-PowerShellClass -Source $source -ClassName $unit.Primary -SourceFile ($Faculty+'.ps1')
    $data=@{}
    if ($Faculty -ceq 'ScriptType') {
        foreach($reference in $ContractReferences){[void][Reflection.Assembly]::LoadFrom([IO.Path]::GetFullPath($reference))}
        if($ContractPaths.Count){$data['ScriptTypeCatalog.Contracts']=@(Get-PscFacultyDeclarations -ContractPaths $ContractPaths)}
        else{$data['ScriptTypeCatalog.Contracts']=[object[]]@()}
    }
    Export-LoweredAssembly -SourceAst $parsed.Ast -DeclarationsOnly -ClassName $unit.Primary -StaticData $data -OutputPath (Join-Path $RuntimeDirectory ($Faculty+'.dll')) -Deterministic
}
function Build-PscRuntime {
    param([string]$RuntimeDirectory,[string[]]$ContractPaths,[string[]]$ContractReferences)
    # External inputs must exist before publishing; earlier faculty outputs are
    # validated by the catalog child after their builds, never loaded here.
    $ContractPaths = [string[]]@(foreach($path in $ContractPaths){[IO.Path]::GetFullPath($path)})
    $ContractReferences = [string[]]@(foreach($path in $ContractReferences){[IO.Path]::GetFullPath($path)})
    $comparison = [StringComparison]::Ordinal
    if($IsWindows){$comparison=[StringComparison]::OrdinalIgnoreCase}
    $earlier = [string[]]@((Join-Path $RuntimeDirectory 'Vom.dll'),(Join-Path $RuntimeDirectory 'InquiryPrimitives.dll'))
    foreach($path in $ContractPaths){if(![IO.File]::Exists($path)){throw "Contract source missing: $path"}}
    foreach($path in $ContractReferences){
        $deferred=$false
        foreach($output in $earlier){if([string]::Equals($path,$output,$comparison)){$deferred=$true;break}}
        if(!$deferred -and ![IO.File]::Exists($path)){throw "Contract reference missing: $path"}
    }
    $exe=Join-Path $PSHOME 'pwsh'
    if($IsWindows){$exe+='.exe'}
    $transportDirectory=[IO.Directory]::CreateTempSubdirectory('psc-contract-').FullName
    $transport=[IO.Path]::Combine($transportDirectory,'inputs.bin')
    try{
        # A data-only length-prefixed path manifest, not source or scriptblocks.
        $writer=[IO.BinaryWriter]::new([IO.File]::Open($transport,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None))
        try{
            $writer.Write([int]$ContractPaths.Length)
            foreach($path in $ContractPaths){$writer.Write([string]$path)}
            $writer.Write([int]$ContractReferences.Length)
            foreach($path in $ContractReferences){$writer.Write([string]$path)}
        }finally{$writer.Dispose()}
        foreach($unit in Get-PscFacultyUnits){
            $arguments=@('-NoProfile','-File',$PSCommandPath,'-Mode','BuildFaculty','-Faculty',$unit.Name,'-RuntimeDirectory',$RuntimeDirectory)
            if($unit.Name -ceq 'ScriptType'){$arguments+=@('-ContractInputsPath',$transport)}
            & $exe @arguments
            if($LASTEXITCODE -ne 0){throw "PSC faculty build failed: $($unit.Name)"}
        }
    }finally{[IO.Directory]::Delete($transportDirectory,$true)}
}
function Read-PscContractInputs([string]$Path){
    $reader=[IO.BinaryReader]::new([IO.File]::OpenRead($Path))
    try{
        $count=$reader.ReadInt32();if($count -lt 0 -or $count -gt 65536){throw 'Invalid contract source count'}
        $sources=[string[]]::new($count);for($i=0;$i -lt $count;$i++){$sources[$i]=$reader.ReadString()}
        $count=$reader.ReadInt32();if($count -lt 0 -or $count -gt 65536){throw 'Invalid contract reference count'}
        $references=[string[]]::new($count);for($i=0;$i -lt $count;$i++){$references[$i]=$reader.ReadString()}
        if($reader.BaseStream.Position -ne $reader.BaseStream.Length){throw 'Trailing contract input data'}
        return @{Sources=$sources;References=$references}
    }finally{$reader.Dispose()}
}

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
if (!$RuntimeDirectory) { $RuntimeDirectory = $PSScriptRoot }

# ============================================================================
# SMA GRAPH, LINT AND PROFILE
# Projects graphed as live objects from SMA's own parser.
# ============================================================================

# The projects beside this script's folder.
$ProjectsRoot = Split-Path -Parent $PSScriptRoot
$ThirdPartyRemotes = 'microsoft/directml', 'microsoft/edit', 'ggml-org/llama.cpp'
$WriteCommands = 'Set-Content','Add-Content','Out-File','New-Item','Remove-Item','Copy-Item','Move-Item','Rename-Item','Export-Clixml','Export-Csv','Clear-Content','Set-Item'
$NetworkCommands = 'Invoke-WebRequest','Invoke-RestMethod','Start-BitsTransfer','New-PSSession','Enter-PSSession'
$ProcessCommands = 'Start-Process','Stop-Process','Invoke-Command','Start-Job'
$DynamicCommands = 'Add-Type','Invoke-Expression','iex'

function Get-ProjectRemote([string] $path) {
    $url = git -C $path remote get-url origin 2>$null
    if (-not $url) { return $null }
    $uri = $null
    if (-not [Uri]::TryCreate($url, [UriKind]::Absolute, [ref]$uri)) { return $url.ToLowerInvariant() }
    $name = $uri.AbsolutePath.Trim('/')
    if ($name.EndsWith('.git', [StringComparison]::OrdinalIgnoreCase)) { $name = $name.Substring(0, $name.Length - 4) }
    $name.ToLowerInvariant()
}

function Get-Projects {
    foreach ($d in Get-ChildItem -LiteralPath $ProjectsRoot -Directory -Force) {
        if ($d.Name.StartsWith('.')) { continue }
        if (Test-Path -LiteralPath (Join-Path $d.FullName '.git')) {
            $remote = Get-ProjectRemote $d.FullName
            if ($remote -and $ThirdPartyRemotes -contains $remote) { continue }
            if (-not $remote) { $remote = '(local) ' + $d.Name.ToLowerInvariant() }
            $files = @(git -C $d.FullName ls-files --cached --others --exclude-standard -- ([PscSourceFormat]::Patterns()) 2>$null | Sort-Object -Unique)
        } else {
            # Project folders outside git: enumerate the file system, leaving out copied upstream references.
            $remote = '(local) ' + $d.Name.ToLowerInvariant()
            $files = @(Get-ChildItem -LiteralPath $d.FullName -Recurse -File -Include ([PscSourceFormat]::Patterns()) -ErrorAction SilentlyContinue |
                Where-Object { $parts = [IO.Path]::GetRelativePath($d.FullName,$_.FullName).Split([IO.Path]::DirectorySeparatorChar); 'reference' -cnotin $parts -and '.git' -cnotin $parts -and 'node_modules' -cnotin $parts } |
                ForEach-Object { $_.FullName.Substring($d.FullName.Length + 1) })
        }
        if ($files.Count) { [pscustomobject]@{ Project = $d.Name; Path = $d.FullName; Remote = $remote; Files = $files } }
    }
}

function Test-DriveRooted([string] $value) {
    if ($value.Length -lt 4 -or $value.Length -gt 259) { return $false }
    try { if (-not [IO.Path]::IsPathFullyQualified($value)) { return $false }; $root = [IO.Path]::GetPathRoot($value) } catch { return $false }
    $root.Length -eq 3 -and [char]::IsLetter($root[0]) -and $root[1] -eq ':'
}

function Get-UnitProfile($project, [string] $file, $node) {
    if ($node -is [System.Management.Automation.Language.FunctionMemberAst]) {
        $name = $node.Parent.Name + '.' + $node.Name; $kind = 'method'; $parameters = @($node.Parameters.Name.VariablePath.UserPath); $help = $null
    } else {
        $name = $node.Name.Replace('global:', '').Replace('script:', ''); $kind = 'function'
        $parameters = @($node.Parameters.Name.VariablePath.UserPath + $node.Body.ParamBlock.Parameters.Name.VariablePath.UserPath | Where-Object { $_ }); $help = $node.GetHelpContent()
    }
    $calls = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $effects = [Collections.Generic.HashSet[string]]::new()
    foreach ($command in $node.Body.FindAll({ $args[0] -is [System.Management.Automation.Language.CommandAst] }, $true)) {
        $commandName = $command.GetCommandName()
        if ($commandName) { $null = $calls.Add($commandName.Replace('global:', '').Replace('script:', '')) }
        elseif ($command.InvocationOperator -ne [System.Management.Automation.Language.TokenKind]::Unknown) { $null = $effects.Add('process') }
    }
    $types = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($t in $node.Body.FindAll({ $args[0] -is [System.Management.Automation.Language.TypeExpressionAst] -or $args[0] -is [System.Management.Automation.Language.TypeConstraintAst] }, $true)) { $null = $types.Add($t.TypeName.FullName) }
    foreach ($c in $calls) {
        if ($WriteCommands -contains $c) { $null = $effects.Add('file-write') }
        if ($NetworkCommands -contains $c) { $null = $effects.Add('network') }
        if ($ProcessCommands -contains $c) { $null = $effects.Add('process') }
        if ($DynamicCommands -contains $c) { $null = $effects.Add('dynamic-code') }
    }
    foreach ($m in $node.Body.FindAll({ $args[0] -is [System.Management.Automation.Language.InvokeMemberExpressionAst] -and $args[0].Static }, $true)) {
        $typeName = $m.Expression.TypeName.FullName; $member = $m.Member.Extent.Text
        $fileType = $typeName -in 'IO.File','System.IO.File','IO.Directory','System.IO.Directory'
        if ($fileType -and ($member.StartsWith('Write') -or $member.StartsWith('Append') -or $member -in 'Delete','Move','Copy','CreateDirectory','Create','Replace')) { $null = $effects.Add('file-write') }
        if ($typeName -in 'scriptblock','System.Management.Automation.ScriptBlock' -and $member -eq 'Create') { $null = $effects.Add('dynamic-code') }
        if ($typeName -in 'Diagnostics.Process','System.Diagnostics.Process') { $null = $effects.Add('process') }
    }
    foreach ($t in $types) { if ($t.StartsWith('Net.Http') -or $t.StartsWith('System.Net.Http') -or $t.StartsWith('Net.Sockets') -or $t.StartsWith('System.Net.Sockets') -or $t -in 'Net.WebClient','System.Net.WebClient') { $null = $effects.Add('network') } }
    $rooted = @($node.Body.FindAll({ $args[0] -is [System.Management.Automation.Language.StringConstantExpressionAst] }, $true) | Where-Object { Test-DriveRooted $_.Value } | ForEach-Object Value | Sort-Object -Unique)
    # Calls the command graph cannot see: instance member invocations ($kernels.Tokenize(...)) and names handed to
    # reflection (GetMethod('Tokenize')). Both are resolved later against units of the same project, as nominations.
    $memberCalls = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $reflected = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($m in $node.Body.FindAll({ $args[0] -is [System.Management.Automation.Language.InvokeMemberExpressionAst] }, $true)) {
        if ($m.Member -isnot [System.Management.Automation.Language.StringConstantExpressionAst]) { continue }
        $memberName = $m.Member.Value
        if (-not $m.Static) { $null = $memberCalls.Add($memberName) }
        if ($memberName -in 'GetMethod', 'GetProperty', 'GetField', 'GetMember' -and $m.Arguments.Count -and $m.Arguments[0] -is [System.Management.Automation.Language.StringConstantExpressionAst]) { $null = $reflected.Add($m.Arguments[0].Value) }
    }
    # Statement structure: each statement of at least 12 nodes as a preorder of node kinds and operators, with every
    # name and literal value removed. Equal hashes in different units are shared structure, whatever the spelling.
    $subtrees = [Collections.Generic.HashSet[string]]::new()
    foreach ($statement in $node.Body.FindAll({ $args[0] -is [System.Management.Automation.Language.StatementAst] -and $args[0] -isnot [System.Management.Automation.Language.FunctionDefinitionAst] -and $args[0] -isnot [System.Management.Automation.Language.TypeDefinitionAst] }, $true)) {
        $kinds = [Collections.Generic.List[string]]::new()
        foreach ($n in $statement.FindAll({ $true }, $true)) {
            $nodeKind = $n.GetType().Name
            if ($n -is [System.Management.Automation.Language.BinaryExpressionAst]) { $nodeKind += ':' + $n.Operator }
            elseif ($n -is [System.Management.Automation.Language.UnaryExpressionAst]) { $nodeKind += ':' + $n.TokenKind }
            elseif ($n -is [System.Management.Automation.Language.AssignmentStatementAst]) { $nodeKind += ':' + $n.Operator }
            $kinds.Add($nodeKind)
        }
        if ($kinds.Count -ge 12) { $null = $subtrees.Add([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($kinds -join ' '))).Substring(0, 16)) }
    }
    $tokens = $errors = $null; $null = [System.Management.Automation.Language.Parser]::ParseInput($node.Extent.Text, [ref]$tokens, [ref]$errors)
    $shape = ($tokens | Where-Object { $_.Kind -notin [System.Management.Automation.Language.TokenKind]::NewLine, [System.Management.Automation.Language.TokenKind]::Comment, [System.Management.Automation.Language.TokenKind]::EndOfInput } | ForEach-Object { if ($_.Kind -eq [System.Management.Automation.Language.TokenKind]::Variable) { 'v' } else { $_.Kind.ToString() + ':' + $_.Text } }) -join ' '
    [pscustomobject]@{
        Project = $project.Project; Remote = $project.Remote; File = $file; Name = $name; Kind = $kind; Line = $node.Extent.StartLineNumber
        Lines = $node.Extent.EndLineNumber - $node.Extent.StartLineNumber + 1; Parameters = $parameters; Calls = @($calls); Types = @($types)
        Effects = @($effects); RootedPaths = $rooted; Synopsis = $(if ($help) { $help.Synopsis } else { $null })
        Shape = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($shape))).Substring(0, 16)
        MemberCalls = @($memberCalls); ReflectedNames = @($reflected); Subtrees = @($subtrees)
    }
}

function Invoke-SmaProfile {
    param()
    $builtin = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($c in Get-Command -CommandType Cmdlet, Function, Alias -ErrorAction SilentlyContinue) { $null = $builtin.Add($c.Name) }
    $projects = @(Get-Projects)
    $units = [Collections.Generic.List[object]]::new()
    foreach ($project in $projects) {
        foreach ($rel in $project.Files) {
            $path = Join-Path $project.Path $rel; if (-not (Test-Path -LiteralPath $path)) { continue }
            $tokens = $errors = $null
            $ast = [System.Management.Automation.Language.Parser]::ParseFile($path, [ref]$tokens, [ref]$errors)
            foreach ($node in $ast.FindAll({ $args[0] -is [System.Management.Automation.Language.FunctionMemberAst] -or ($args[0] -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $args[0].Parent -isnot [System.Management.Automation.Language.FunctionMemberAst]) }, $true)) {
                $units.Add((Get-UnitProfile $project $rel $node))
            }
        }
    }
    $byProject = @{}; foreach ($u in $units) { $k = $u.Project + '|' + $u.Name; if (-not $byProject.ContainsKey($k)) { $byProject[$k] = $u } }
    $byName = $units | Group-Object Name -AsHashTable -AsString
    # Class methods by project and short name, the targets of member invocations and reflected names.
    $methods = @{}
    foreach ($u in $units | Where-Object Kind -eq 'method') { $k = $u.Project + '|' + $u.Name.Split('.')[-1]; if (-not $methods.ContainsKey($k)) { $methods[$k] = [Collections.Generic.List[object]]::new() }; $methods[$k].Add($u) }
    $incoming = @{}
    $addIncoming = { param($target, [string] $via, $source) $key = $target.Project + '|' + $target.Name + '|' + $target.Line; if (-not $incoming.ContainsKey($key)) { $incoming[$key] = [Collections.Generic.List[string]]::new() }; $incoming[$key].Add($via + ':' + $source.Name) }
    foreach ($u in $units) {
        $internal = [Collections.Generic.List[object]]::new(); $elsewhere = [Collections.Generic.List[string]]::new(); $unresolved = [Collections.Generic.List[string]]::new()
        foreach ($c in $u.Calls) {
            if ($byProject.ContainsKey($u.Project + '|' + $c)) { $internal.Add($byProject[$u.Project + '|' + $c]); & $addIncoming $byProject[$u.Project + '|' + $c] 'command' $u }
            elseif ($byName.ContainsKey($c)) { $elsewhere.Add($c + ' <- ' + ((@($byName[$c].Project | Sort-Object -Unique)) -join ',')) }
            elseif (-not $builtin.Contains($c)) { $unresolved.Add($c) }
        }
        # Member and reflection edges are nominations by name within the project; they are kept apart from command calls.
        $nominated = [Collections.Generic.List[string]]::new()
        foreach ($pair in @(@($u.MemberCalls, 'member'), @($u.ReflectedNames, 'reflection'))) {
            foreach ($n in $pair[0]) {
                $k = $u.Project + '|' + $n
                if ($methods.ContainsKey($k)) { foreach ($t in $methods[$k]) { if ($t -ne $u) { $nominated.Add($pair[1] + ':' + $t.Name); & $addIncoming $t $pair[1] $u } } }
                elseif ($pair[1] -eq 'reflection' -and $byProject.ContainsKey($k)) { $nominated.Add('reflection:' + $n); & $addIncoming $byProject[$k] 'reflection' $u }
            }
        }
        $u | Add-Member Internal $internal; $u | Add-Member NameMatchedElsewhere @($elsewhere); $u | Add-Member Unresolved @($unresolved); $u | Add-Member Nominated @($nominated)
    }
    foreach ($u in $units) { $key = $u.Project + '|' + $u.Name + '|' + $u.Line; $u | Add-Member Incoming @($(if ($incoming.ContainsKey($key)) { $incoming[$key] } else { @() })) }
    $memo = @{}
    $testPure = {
        param($u, $seen)
        $key = $u.Project + '|' + $u.Name + '|' + $u.Line
        if ($memo.ContainsKey($key)) { return $memo[$key] }
        if ($seen.Contains($key)) { return $true }
        $null = $seen.Add($key)
        $ok = $u.Effects.Count -eq 0 -and $u.RootedPaths.Count -eq 0 -and $u.NameMatchedElsewhere.Count -eq 0 -and $u.Unresolved.Count -eq 0
        if ($ok) { foreach ($d in $u.Internal) { if (-not (& $testPure $d $seen)) { $ok = $false; break } } }
        $memo[$key] = $ok; $ok
    }
    foreach ($u in $units) { $u | Add-Member PureClosure (& $testPure $u ([Collections.Generic.HashSet[string]]::new())) }
    @($units | Select-Object Project, Remote, File, Name, Kind, Line, Lines, Parameters, Calls, Types, Effects, RootedPaths, Synopsis, Shape, @{ n = 'Internal'; e = { @($_.Internal.Name) } }, NameMatchedElsewhere, Unresolved, PureClosure, MemberCalls, ReflectedNames, Subtrees, Nominated, Incoming)
}

function Get-SmaUnits($profiled) {
    # One unit per function, and one per class with its methods rolled up.
    foreach ($f in $profiled | Where-Object Kind -eq 'function') { $f | Select-Object *, @{ n = 'Pure'; e = { $_.PureClosure } } }
    foreach ($g in $profiled | Where-Object Kind -eq 'method' | Group-Object Project, File, { $_.Name.Split('.')[0] }) {
        $m = $g.Group
        [pscustomobject]@{ Project = $m[0].Project; Remote = $m[0].Remote; File = $m[0].File; Name = $m[0].Name.Split('.')[0]; Kind = 'class'
            Line = ($m.Line | Measure-Object -Minimum).Minimum; Lines = ($m.Lines | Measure-Object -Sum).Sum
            Calls = @($m.Calls | Sort-Object -Unique); Types = @($m.Types | Sort-Object -Unique); Effects = @($m.Effects | Sort-Object -Unique)
            RootedPaths = @($m.RootedPaths | Sort-Object -Unique); NameMatchedElsewhere = @($m.NameMatchedElsewhere | Sort-Object -Unique)
            Unresolved = @($m.Unresolved | Sort-Object -Unique); Shape = (($m | Sort-Object Name).Shape -join ''); Pure = -not ($m | Where-Object { -not $_.PureClosure })
            Subtrees = @($m.Subtrees | Sort-Object -Unique); Nominated = @($m.Nominated | Sort-Object -Unique)
            Incoming = @($m.Incoming | Where-Object { $_ -and $_.Split(':', 2)[1] -notlike ($m[0].Name.Split('.')[0] + '.*') } | Sort-Object -Unique) }
    }
}

# Units that only checks can reach. Roots are units nothing else calls (entry points and script-level dispatch
# targets). A check is a unit named Test-*, Verify-*, Assert-*, or *Judge*. A unit reachable from a check root and
# from no other root works only inside its own proofs: green checks, unreachable from the product.
function Get-SmaCheckOnly($profiled) {
    $byKey = @{}
    foreach ($u in $profiled) { $k = $u.Project + '|' + $u.Name; if (-not $byKey.ContainsKey($k)) { $byKey[$k] = [Collections.Generic.List[object]]::new() }; $byKey[$k].Add($u) }
    $edges = @{}
    foreach ($u in $profiled) {
        $targets = [Collections.Generic.List[object]]::new()
        foreach ($n in $u.Internal) { if ($byKey.ContainsKey($u.Project + '|' + $n)) { $targets.AddRange($byKey[$u.Project + '|' + $n]) } }
        foreach ($n in $u.Nominated) { $name = $n.Split(':', 2)[1]; if ($byKey.ContainsKey($u.Project + '|' + $name)) { $targets.AddRange($byKey[$u.Project + '|' + $name]) } }
        $edges[$u] = $targets
    }
    $isCheck = { param($u) $short = $u.Name.Split('.')[-1]; $short -match '^(Test|Verify|Assert)-' -or $short -match '(?i)judge' -or $u.File -match '(?i)(^|[\\/])(tests?|.*judges?)[\\/.]' }
    $reach = { param([object[]] $roots) $seen = [Collections.Generic.HashSet[object]]::new(); $stack = [Collections.Generic.Stack[object]]::new(); foreach ($r in $roots) { if ($seen.Add($r)) { $stack.Push($r) } }
        while ($stack.Count) { $x = $stack.Pop(); foreach ($t in $edges[$x]) { if ($seen.Add($t)) { $stack.Push($t) } } }; , $seen }
    $roots = @($profiled | Where-Object { -not $_.Incoming.Count })
    $fromChecks = & $reach @($roots | Where-Object { & $isCheck $_ })
    $fromProduct = & $reach @($roots | Where-Object { -not (& $isCheck $_) })
    foreach ($u in $fromChecks) {
        if ($fromProduct.Contains($u) -or (& $isCheck $u)) { continue }
        $callers = @($profiled | Where-Object { $edges[$_] -contains $u } | ForEach-Object Name | Sort-Object -Unique)
        [pscustomobject]@{ Project = $u.Project; File = $u.File; Line = $u.Line; Name = $u.Name; Lines = $u.Lines; CalledBy = $callers; Status = 'UnverifiedNomination'; ExecutionCoverage = 'Unknown' }
    }
}

function Get-SmaReport {
    param($units, $profiled)
    '=== projects'
    $units | Group-Object Project | Sort-Object Count -Descending | ForEach-Object { '{0,-28} {1,5} units  {2,4} pure  {3}' -f $_.Name, $_.Count, @($_.Group | Where-Object Pure).Count, $_.Group[0].Remote }
    '=== copies of one remote: identical, diverged, not in every copy'
    foreach ($r in $units | Group-Object Remote | Where-Object { @($_.Group.Project | Sort-Object -Unique).Count -gt 1 }) {
        $copies = @($r.Group.Project | Sort-Object -Unique); $map = @{}
        foreach ($c in $copies) { $map[$c] = @{}; foreach ($u in $r.Group | Where-Object Project -eq $c) { $map[$c][$u.Kind + ':' + $u.Name] = $u.Shape } }
        $same = 0; $diff = 0; $one = 0
        foreach ($n in @($map.Values | ForEach-Object { $_.Keys } | Sort-Object -Unique)) {
            $present = @($copies | Where-Object { $map[$_].ContainsKey($n) })
            if ($present.Count -lt $copies.Count) { $one++ } elseif (@($present | ForEach-Object { $map[$_][$n] } | Sort-Object -Unique).Count -eq 1) { $same++ } else { $diff++ }
        }
        '{0,-34} {1}: identical {2}, diverged {3}, not in every copy {4}' -f $r.Name, ($copies -join ' / '), $same, $diff, $one
    }
    $primary = @{}; foreach ($r in $units | Group-Object Remote) { $primary[$r.Name] = ($r.Group | Group-Object Project | Sort-Object Count -Descending | Select-Object -First 1).Name }
    $distinct = @($units | Where-Object { $primary[$_.Remote] -eq $_.Project })
    '=== distinct work (largest copy of each remote)'
    '{0} units: {1} functions, {2} classes; pure closures {3}' -f $distinct.Count, @($distinct | Where-Object Kind -eq 'function').Count, @($distinct | Where-Object Kind -eq 'class').Count, @($distinct | Where-Object Pure).Count
    'effects: ' + (($distinct | ForEach-Object { $_.Effects } | Group-Object | Sort-Object Count -Descending | ForEach-Object { "$($_.Name)=$($_.Count)" }) -join '  ')
    '=== identical structure in more than one remote (at least 5 lines)'
    $distinct | Where-Object { $_.Lines -ge 5 } | Group-Object Shape | Where-Object { @($_.Group.Remote | Sort-Object -Unique).Count -gt 1 } | Sort-Object { $_.Group[0].Lines } -Descending | ForEach-Object { '{0,4} lines  {1}' -f $_.Group[0].Lines, (($_.Group | ForEach-Object { "$($_.Project):$($_.Name)" }) -join ' = ') }
    '=== same name, different structure, in more than one remote'
    $distinct | Group-Object Kind, Name | Where-Object { @($_.Group.Remote | Sort-Object -Unique).Count -gt 1 -and @($_.Group.Shape | Sort-Object -Unique).Count -gt 1 } | Sort-Object Count -Descending | ForEach-Object { '{0,-40} {1}' -f $_.Group[0].Name, (($_.Group | ForEach-Object Project | Sort-Object -Unique) -join ', ') }
    '=== dynamic code'
    $distinct | Where-Object { $_.Effects -contains 'dynamic-code' } | Sort-Object Project, File, Line | ForEach-Object { '  {0}:{1}:{2} {3}' -f $_.Project, $_.File, $_.Line, $_.Name }
    '=== drive-rooted path literals'
    $distinct | Where-Object { $_.RootedPaths.Count } | Sort-Object Project, File, Line | ForEach-Object { '  {0}:{1}:{2} {3}  {4}' -f $_.Project, $_.File, $_.Line, $_.Name, ($_.RootedPaths -join ' | ') }
    '=== calls matched by name to another project (nominated, not established)'
    $distinct | ForEach-Object { $u = $_; $u.NameMatchedElsewhere | ForEach-Object { "$($u.Project) -> " + $_ } } | Group-Object | Sort-Object Count -Descending | ForEach-Object { '  {0,4}  {1}' -f $_.Count, $_.Name }
    '=== reached only through members or reflection (invisible to the command graph)'
    $distinct | Where-Object { $_.Incoming.Count -and -not ($_.Incoming | Where-Object { $_ -like 'command:*' }) } | Sort-Object Project, File, Line | ForEach-Object { '  {0}:{1}:{2} {3}  <- {4}' -f $_.Project, $_.File, $_.Line, $_.Name, (($_.Incoming | ForEach-Object { $_ } | Select-Object -First 4) -join ' | ') }
    '=== no incoming edge from any unit (entry points, script-level dispatch, or unused), by project'
    $distinct | Where-Object { -not $_.Incoming.Count } | Group-Object Project | Sort-Object Count -Descending | ForEach-Object { '  {0,-28} {1,5} of {2}' -f $_.Name, $_.Count, @($distinct | Where-Object Project -eq $_.Name).Count }
    '=== experimental check-root nominations; script dispatch, dynamic binding and product reachability are not established'
    if ($profiled) { Get-SmaCheckOnly $profiled | Sort-Object Project, File, Line | ForEach-Object { '  {0}:{1}:{2} {3} ({4} lines)  <- {5}' -f $_.Project, $_.File, $_.Line, $_.Name, $_.Lines, (($_.CalledBy | Select-Object -First 4) -join ', ') } }
    '=== statement structure shared by different units (12+ nodes, names and literals removed), widest first'
    $owners = @{}
    foreach ($u in $distinct) { foreach ($s in $u.Subtrees) { if (-not $owners.ContainsKey($s)) { $owners[$s] = [Collections.Generic.List[object]]::new() }; $owners[$s].Add($u) } }
    $owners.GetEnumerator() | Where-Object { @($_.Value | ForEach-Object { $_.Project + '|' + $_.Name } | Sort-Object -Unique).Count -gt 2 } | Sort-Object { @($_.Value).Count } -Descending | Select-Object -First 60 | ForEach-Object {
        $names = @($_.Value | ForEach-Object { $_.Project + ':' + $_.Name } | Sort-Object -Unique)
        '  {0} x{1,-4} {2}{3}' -f $_.Key, $names.Count, (($names | Select-Object -First 6) -join ' = '), $(if ($names.Count -gt 6) { ' ...' } else { '' }) }
}

# Lint: defects PowerShell's own rules make easy to write and hard to see, found from the parser.
#   CaseSpelledTwoWays  a variable or function name written with different casing (one name to PowerShell).
#   VariableClobbered   a variable assigned at a function's top level and again inside a loop (loops share the
#                       function's scope), then read at top level after that loop.
#   MethodSyntaxCall    a command called as name(a, b): one array argument, not two.
#   CommaBindsFirst     an arithmetic, comparison or format operator with a bare comma list as an operand:
#                       the comma binds first, so the operator receives an array.
#   CaselessSymbol      a case-insensitive comparison against a literal containing letters, in a file that also
#                       uses case-sensitive operators, so case matters to its author there.
#   EnumNameAsString    a string literal compared with, or switched over, an enum-typed property: the member's name
#                       in place of the member. The finding carries the edit when exactly one enum fits.
#   EnumNameByPattern   a regex or wildcard matched against an enum-typed property's name.
#   EnumNameUnknown     a string compared with an enum-typed value that names no member of the enum: never equal.
function Get-SmaLint {
    # With $text, the findings are of that text, reported under $file's name (Guard: the committed version).
    [PscVerify()]
    param([string] $file, [string] $text)
    $tokens = $errors = $null
    $ast = if ($PSBoundParameters.ContainsKey('text')) { [System.Management.Automation.Language.Parser]::ParseInput($text, $file, [ref]$tokens, [ref]$errors) }
        else { [System.Management.Automation.Language.Parser]::ParseFile($file, [ref]$tokens, [ref]$errors) }
    # Named authoring scopes, not a claim to resolve arbitrary dynamic caller scope or invoked scriptblocks.
    $scopeOf = {
        param($node)
        for ($parent = $node; $null -ne $parent; $parent = $parent.Parent) {
            if ($parent -is [System.Management.Automation.Language.FunctionMemberAst]) { return $parent }
            if ($parent -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $parent.Parent -isnot [System.Management.Automation.Language.FunctionMemberAst]) { return $parent }
        }
        return $ast
    }
    $scopeName = {
        param($scope)
        $parts = [Collections.Generic.List[string]]::new()
        while ($scope -ne $ast) {
            if ($scope -is [System.Management.Automation.Language.FunctionMemberAst]) {
                $signature = @($scope.Parameters | ForEach-Object { $constraint = @($_.Attributes | Where-Object { $_ -is [System.Management.Automation.Language.TypeConstraintAst] }); if ($constraint.Count) { $constraint[0].TypeName.FullName } else { 'object' } }) -join ','
                $parts.Insert(0, ('{0}.{1}({2})' -f $scope.Parent.Name, $scope.Name, $signature))
            } else { $parts.Insert(0, ('function:' + $scope.Name)) }
            $scope = & $scopeOf $scope.Parent
        }
        return 'script/' + ($parts -join '/')
    }
    $finding = {
        param([string] $rule, $node, [string] $detail, [object[]] $edits = @(), [string] $identity = '')
        $scope = & $scopeName (& $scopeOf $node)
        if (!$identity) { $identity = $scope + '|' + $detail }
        [SmaLintFinding]@{ File = $file; Line = $node.Extent.StartLineNumber; Rule = $rule; Detail = $detail; Identity = $identity; Scope = $scope; Extent = $node.Extent; Edits = $edits }
    }
    $variables = @($ast.FindAll({ $args[0] -is [System.Management.Automation.Language.VariableExpressionAst] }, $true))
    $locals = [Collections.Generic.Dictionary[System.Management.Automation.Language.Ast,Collections.Generic.HashSet[string]]]::new()
    $scopeOfVariable = [Collections.Generic.Dictionary[System.Management.Automation.Language.Ast,System.Management.Automation.Language.Ast]]::new()
    foreach ($variable in $variables) {
        $path = $variable.VariablePath
        if ($path.IsDriveQualified -and !$path.IsScript -and !$path.IsLocal -and !$path.IsPrivate) { continue }
        $scope = if ($path.IsScript) { $ast } else { & $scopeOf $variable }
        $scopeOfVariable.Add($variable,$scope)
        if (!$locals.ContainsKey($scope)) { $locals.Add($scope,[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)) }
        $name = $path.UserPath
        if ($name.Contains(':')) { $name = $name.Substring($name.IndexOf(':') + 1) }
        $target = $variable
        while ($target.Parent -is [System.Management.Automation.Language.ConvertExpressionAst]) { $target = $target.Parent }
        $parent = $target.Parent
        if ($path.IsScript -or $path.IsLocal -or $path.IsPrivate -or $parent -is [System.Management.Automation.Language.ParameterAst] -or ($parent -is [System.Management.Automation.Language.AssignmentStatementAst] -and [object]::ReferenceEquals($parent.Left,$target)) -or ($parent -is [System.Management.Automation.Language.ForEachStatementAst] -and [object]::ReferenceEquals($parent.Variable,$variable))) { $null = $locals[$scope].Add($name) }
    }
    $groups = [Collections.Generic.Dictionary[string,Collections.Generic.List[System.Management.Automation.Language.VariableExpressionAst]]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($variable in $variables) {
        if (!$scopeOfVariable.ContainsKey($variable)) { continue }
        $path = $variable.VariablePath; $name = $path.UserPath; $scope = $scopeOfVariable[$variable]
        if ($name.Contains(':')) { $name = $name.Substring($name.IndexOf(':') + 1) }
        if (!$path.IsScript -and !$path.IsLocal -and !$path.IsPrivate) {
            $enclosing = $scope
            while ($enclosing -ne $ast -and (!$locals.ContainsKey($enclosing) -or !$locals[$enclosing].Contains($name))) { $enclosing = & $scopeOf $enclosing.Parent }
            if ($locals.ContainsKey($enclosing) -and $locals[$enclosing].Contains($name)) { $scope = $enclosing }
        }
        $key = (& $scopeName $scope) + '|' + $name.ToLowerInvariant()
        if (!$groups.ContainsKey($key)) { $groups.Add($key,[Collections.Generic.List[System.Management.Automation.Language.VariableExpressionAst]]::new()) }
        $groups[$key].Add($variable)
    }
    foreach ($entry in $groups.GetEnumerator()) {
        $spellings = @($entry.Value | ForEach-Object { $name = $_.VariablePath.UserPath; if ($name.Contains(':')) { $name.Substring($name.IndexOf(':') + 1) } else { $name } } | Sort-Object -Unique -CaseSensitive)
