    [bool] VerifyConformance([PscConformanceReport]$report,[string]$candidateFile,[string]$baselineDigest,[string]$runnerDigest,[bool]$development){return $this.VerifyConformance($report,$candidateFile,$baselineDigest,$runnerDigest,$development,'')}
    [bool] VerifyConformance([PscConformanceReport]$report,[string]$candidateFile,[string]$baselineDigest,[string]$runnerDigest,[bool]$development,[string]$expectedHost){return $this.VerifyConformance($report,$candidateFile,$baselineDigest,$runnerDigest,$development,$expectedHost,'')}
    [bool] VerifyConformance([PscConformanceReport]$report,[string]$candidateFile,[string]$baselineDigest,[string]$runnerDigest,[bool]$development,[string]$expectedHost,[string]$expectedGit){return $this.VerifyConformance($report,$candidateFile,$baselineDigest,$runnerDigest,$development,$expectedHost,$expectedGit,'')}
    [bool] VerifyConformance([PscConformanceReport]$report,[string]$candidateFile,[string]$baselineDigest,[string]$runnerDigest,[bool]$development,[string]$expectedHost,[string]$expectedGit,[string]$expectedRuntime){
        if([Convert]::ToHexString([Security.Cryptography.SHA512]::HashData([IO.File]::ReadAllBytes($this.Script))) -cne $this.SourceSha512){throw 'Conformance verification API source has changed.'}
        return & $this.Script -Mode VerifyConformance -AssessmentReport $report -SourcePath $candidateFile -ExpectedBaselineSha256 $baselineDigest -ExpectedRunnerSha256 $runnerDigest -ExpectedHostSha256 $expectedHost -ExpectedGitSha256 $expectedGit -ExpectedRuntimeSha256 $expectedRuntime -DevelopmentOnly:$development
    }
    [PscConformanceReport] Conform([string]$candidateFile,[string]$baselineFile,[bool]$development){return $this.Conform($candidateFile,$baselineFile,$development,'')}
    [PscConformanceReport] Conform([string]$candidateFile,[string]$baselineFile,[bool]$development,[string]$expectedRunner){return $this.Conform($candidateFile,$baselineFile,$development,$expectedRunner,'')}
    [PscConformanceReport] Conform([string]$candidateFile,[string]$baselineFile,[bool]$development,[string]$expectedRunner,[string]$expectedBaseline){return $this.Conform($candidateFile,$baselineFile,$development,$expectedRunner,$expectedBaseline,'')}
    [PscConformanceReport] Conform([string]$candidateFile,[string]$baselineFile,[bool]$development,[string]$expectedRunner,[string]$expectedBaseline,[string]$expectedHost){return $this.Conform($candidateFile,$baselineFile,$development,$expectedRunner,$expectedBaseline,$expectedHost,'')}
    [PscConformanceReport] Conform([string]$candidateFile,[string]$baselineFile,[bool]$development,[string]$expectedRunner,[string]$expectedBaseline,[string]$expectedHost,[string]$expectedGit){return $this.Conform($candidateFile,$baselineFile,$development,$expectedRunner,$expectedBaseline,$expectedHost,$expectedGit,'')}
    [PscConformanceReport] Conform([string]$candidateFile,[string]$baselineFile,[bool]$development,[string]$expectedRunner,[string]$expectedBaseline,[string]$expectedHost,[string]$expectedGit,[string]$expectedRuntime){return & $this.Script -Mode Conform -SourcePath $candidateFile -AgainstPath $baselineFile -DevelopmentOnly:$development -ExpectedRunnerSha256 $expectedRunner -ExpectedBaselineSha256 $expectedBaseline -ExpectedHostSha256 $expectedHost -ExpectedGitSha256 $expectedGit -ExpectedRuntimeSha256 $expectedRuntime}
    [string] $TypeSystemContract = 'PSC owns first-class typed representations of the ScriptType System (STS) and the Common Type System (CTS). STS supports independently acquired structural contracts, identity, composition, binding, refinement and realization; CTS preserves faithful CLI interoperability. Semantic analysis must not require runtime materialization. Mappings between STS and CTS are explicit, typed and reversible where representable. SMA is the authoring and source-evidence substrate. Managed CLI, NativeAOT and independent native ISA are supported realization paths; neither CLR nor the C runtime is intrinsic to STS. Independent native realization shall support explicit static, dynamic or absent C runtime linkage. Source, semantic and realization retention are explicit artifact requirements, independent of execution dependencies.'
    [string] $SourceExecutionContract = 'PSC realizes SM source; realized execution is SMA-free. File roles do not prohibit execution. Stock pwsh execution is not a compatibility requirement.'
    [PscSemanticIndex] OpenSemanticIndex([string]$root){return [PscSemanticIndex]::new($this.Script,$root)}
    [PscDocument] OpenDocument([string]$path){return [PscDocument]::new($path)}
    [PscQueryCursor] OpenQuery([string[]]$paths,[PscQueryKind]$kind,[string]$name,[string]$owner,[string]$literal,[int]$take){
        if($literal -and $kind -in [PscQueryKind]::CilMethod,[PscQueryKind]::CilOp){throw 'Literal containment requires a source query.'}
        $spec=[PscQuerySpec]::new($kind,$name,$owner,$take);$spec.Literal=$literal
        return [PscQueryCursor]::new($paths,$spec)
    }
    [void] AssertSurface(){
        $allowed=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $dispatched=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach($parameter in $this.Parameters){if($parameter.Name -eq 'Mode'){foreach($value in $parameter.AllowedValues){if(!$allowed.Add([string]$value)){throw 'Duplicate admitted mode.'}}}}
        foreach($operation in $this.Modes){if(!$dispatched.Add($operation.Mode)){throw 'Duplicate dispatched mode.'}}
        if(!$allowed.SetEquals($dispatched) -or !$allowed.Contains($this.DefaultMode)){throw 'PSC mode admission and dispatch disagree.'}
        foreach($parameter in $this.Parameters){if([string]::IsNullOrWhiteSpace($parameter.Description)){throw "Undocumented PSC parameter: $($parameter.Name)"}}
        [void]$this.AssessRoadmap()
    }
    [string] $Synopsis
    [string] $Script
    [string] $SourceSha512
    [string] $DefaultMode
    [PscOperation[]] $Modes
    [PscParameter[]] $Parameters
    [PscMeasure[]] $Measures
    [string[]] $Functions
    [string[]] $Classes
    [PscEnvironment] $Environment
    # The script help's notes as one paragraph; the README prints it as prose, not as a table column.
    hidden [string] $Notes
    hidden [System.Management.Automation.Language.ScriptBlockAst] $Ast

    # Sets a binding in this API's environment; the newest binding for its target wins.
    [PscBinding] SetBinding([PscBinding] $binding) { return $this.Environment.Set($binding) }

    # Parses a PowerShell source file and takes every measure of it, with the location of each finding.
    [PscSource] ReadSource([string] $path) { return [PscSource]::new($path) }

    # The classes of a source (all of them when $classNames is empty), lowered by PSC and loaded from the assembly's bytes.
    [System.Reflection.Assembly] Lower([System.Management.Automation.Language.ScriptBlockAst] $source, [string[]] $classNames) {
        return [PscDifferential]::Lower($this.Script, $source, $classNames)
    }

    # PSC's PowerShellSemantics, lowered as every program that needs a helper receives it.
    [type] Semantics() {
        return [PscDifferential]::Lower($this.Script, [PscDifferential]::SemanticsSource($this.Script), [string[]]@('PowerShellSemantics')).GetType('PowerShellSemantics')
    }

    # The same classes defined by SMA, interpreted: the reference implementation of a lowered class.
    [System.Collections.Generic.Dictionary[string, type]] Interpret([System.Management.Automation.Language.ScriptBlockAst] $source) {
        return [PscDifferential]::Interpret($source)
    }

    [PscOutcome] Invoke([System.Reflection.MethodInfo] $method, [object] $instance, [object[]] $arguments) {
        return [PscDifferential]::Invoke($method, $instance, $arguments, 0)
    }

    # SMA running PowerShell code on the given arguments, with strict mode version Latest or off: the reference
    # implementation for any construct PSC lowers.
    [PscOutcome] Reference([scriptblock] $code, [object[]] $arguments, [bool] $strict) {
        return [PscDifferential]::Reference($code, $arguments, $strict)
    }

    [PscRelation] Compare([PscOutcome] $lowered, [PscOutcome] $reference) {
        return [PscDifferential]::Compare($lowered, $reference)
    }

    # Boundary values of a type, and every combination of them for a parameter list, up to a limit.
    [System.Collections.Generic.List[object]] Values([type] $type) { return [PscDifferential]::Values($type) }
    [System.Collections.Generic.List[object[]]] ArgumentSets([type[]] $types, [int] $limit) { return [PscDifferential]::ArgumentSets($types, $limit) }

    # Every instrument applied to the given files and directories and to each file they reference. Instruments call
    # this script's functions, so the investigation runs in an invocation of the script.
    [object] Investigate([string[]] $paths) {
        return & $this.Script -Mode Investigate -InvestigatePath $paths
    }

    # The source's script variables used only as records, each with its slots and their types, or the use that
    # disqualifies it; and the source with each record given its class, as PSC lowers it. Both run in an invocation of
    # the script, whose functions they are.
    [object[]] Records([System.Management.Automation.Language.ScriptBlockAst] $source) { return & $this.Script -Mode Records -SourceAst $source }
    [System.Management.Automation.Language.ScriptBlockAst] TypeRecords([System.Management.Automation.Language.ScriptBlockAst] $source) {
        [PscRecord[]] $records = @($this.Records($source) | Where-Object { $null -eq $_.Disqualified })
        if ($records.Count -eq 0) { return $source }
        return [PscRecordRewrite]::new($source, $records).Rebuild($source)
    }

    # The source run by SMA with its native stubs filled just in time, given its parameters by name.
    [object] Run([System.Management.Automation.Language.ScriptBlockAst] $source, [hashtable] $parameters) { return & $this.Script -Mode Run -SourceAst $source -RunParameters $parameters }

    # A new tree of the same structure, every node constructed again by SMA.
    [System.Management.Automation.Language.ScriptBlockAst] Rebuild([System.Management.Automation.Language.ScriptBlockAst] $source) {
        return [PscAstRebuild]::new().Rebuild($source)
    }

    # The source with each operator whose token is a key evaluated by its method, for SMA to run.
    # The script with -Values' parameters fixed as constants, branches they decide pruned (PscFixedParameters), and
    # functions no longer reachable left out (PscReachability).
    [System.Management.Automation.Language.ScriptBlockAst] FixParameters([System.Management.Automation.Language.ScriptBlockAst] $source, [hashtable] $values) {
        return [PscReachability]::Prune([PscFixedParameters]::new($values).Fix($source))
    }

    [System.Management.Automation.Language.ScriptBlockAst] BindOperators([System.Management.Automation.Language.ScriptBlockAst] $source, [System.Collections.Generic.Dictionary[System.Management.Automation.Language.TokenKind, System.Reflection.MethodInfo]] $methods) {
        return [PscOperatorRebinding]::new($methods).Rebuild($source)
    }
}

function Get-PscApi {
    [CmdletBinding()]
    [OutputType([PscApi])]
    param()
    $source = [PscSource]::new($PSCommandPath)
    $ast = $source.Ast
    if ($source.ParseErrors.Count) { throw 'This script has parse errors; its API cannot be described.' }
    $help = $ast.GetHelpContent()
    if ($null -eq $help) { throw 'PSC script-level help is missing.' }
    $scriptParameters = [System.Collections.Generic.Dictionary[string, System.Management.Automation.Language.ParameterAst]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($parameter in $ast.ParamBlock.Parameters) { $scriptParameters[$parameter.Name.VariablePath.UserPath] = $parameter }
    $functions = [System.Collections.Generic.Dictionary[string, System.Management.Automation.Language.FunctionDefinitionAst]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($function in $ast.BeginBlock.FindAll({ param($node) $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $node.Parent -isnot [System.Management.Automation.Language.FunctionMemberAst] }, $false)) {
        $functions[$function.Name] = $function
    }
    $switch = $ast.ProcessBlock.Find({ param($node) $node -is [System.Management.Automation.Language.SwitchStatementAst] }, $false)
    $operations = [System.Collections.Generic.List[PscOperation]]::new()
    foreach ($clause in $switch.Clauses) {
        $body = $clause.Item2
        $used = [System.Collections.Generic.SortedSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($variable in $body.FindAll({ param($node) $node -is [System.Management.Automation.Language.VariableExpressionAst] }, $true)) {
            $name = $variable.VariablePath.UserPath
            if ($scriptParameters.ContainsKey($name) -and $name -ne 'Mode') { $null = $used.Add($name) }
        }
        $calls = [System.Collections.Generic.SortedSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($command in $body.FindAll({ param($node) $node -is [System.Management.Automation.Language.CommandAst] }, $true)) {
            $name = $command.GetCommandName()
            if (-not $name -or -not $functions.ContainsKey($name)) { continue }
            $null = $calls.Add($name)
            $splatted = @($command.CommandElements | Where-Object { $_ -is [System.Management.Automation.Language.VariableExpressionAst] -and $_.Splatted }).Count
            if (-not $splatted) { continue }
            $target = $functions[$name]
            $targetParameters = if ($target.Body.ParamBlock) { $target.Body.ParamBlock.Parameters } else { $target.Parameters }
            foreach ($parameter in @($targetParameters)) {
                $parameterName = $parameter.Name.VariablePath.UserPath
                if ($scriptParameters.ContainsKey($parameterName) -and $parameterName -ne 'Mode') { $null = $used.Add($parameterName) }
            }
        }
        $operation = [PscOperation]::new()
        $operation.DispatchExtent = $body.Extent
        $operation.Mode = $clause.Item1.SafeGetValue()
        $operation.Parameters = [PscParameter[]]@(foreach ($name in $used) { Get-PscApiParameter $scriptParameters[$name] $help.Parameters[$name.ToUpperInvariant()] })
        $operation.Calls = [string[]]@($calls)
        $operation.Definitions = [System.Management.Automation.Language.FunctionDefinitionAst[]]@(foreach ($name in $calls) { $functions[$name] })
        $operations.Add($operation)
    }
    $api = [PscApi]::new()
    $api.Synopsis = if ($help) { $help.Synopsis.Trim() } else { $null }
    $api.Notes = if ($help -and $help.Notes) { [string]::Join(' ', [string[]]@($help.Notes.Split("`n").Trim() | Where-Object { $_ })) } else { $null }
    $api.Script = $PSCommandPath
    $api.SourceSha512 = $source.Sha512
    $api.DefaultMode = $scriptParameters['Mode'].DefaultValue.SafeGetValue()
    $api.Modes = $operations.ToArray()
    $api.Parameters = [PscParameter[]]@(foreach ($parameter in $ast.ParamBlock.Parameters) { Get-PscApiParameter $parameter $help.Parameters[$parameter.Name.VariablePath.UserPath.ToUpperInvariant()] })
    $api.Measures = $source.Measures
    $api.Functions = [string[]]@($functions.Keys)
    $api.Classes = [string[]]@($ast.BeginBlock.FindAll({ param($node) $node -is [System.Management.Automation.Language.TypeDefinitionAst] }, $false) | ForEach-Object Name)
    $api.Environment = $script:PscEnvironment
    $api.Ast = $ast
    $api.FacultyUnits = @(Get-PscFacultyUnits)
    $api.AssertSurface()
    $api
}

function Get-PscApiParameter {
    [CmdletBinding()]
    [OutputType([PscParameter])]
    param([Parameter(Mandatory)][System.Management.Automation.Language.ParameterAst] $Parameter, [string] $Description)
    $allowed = [System.Collections.Generic.List[object]]::new()
    $pipeline = $false
    foreach ($attribute in $Parameter.Attributes) {
        if ($attribute -isnot [System.Management.Automation.Language.AttributeAst]) { continue }
        $attributeType = $attribute.TypeName.GetReflectionAttributeType()
        if ($attributeType -eq [System.Management.Automation.ValidateSetAttribute]) {
            foreach ($argument in $attribute.PositionalArguments) { $allowed.Add($argument.SafeGetValue()) }
        }
        if ($attributeType -eq [System.Management.Automation.ParameterAttribute]) {
            foreach ($argument in $attribute.NamedArguments) { if ($argument.ArgumentName -eq 'ValueFromPipeline') { $pipeline = $true } }
        }
    }
    $described = [PscParameter]::new()
    $described.Name = $Parameter.Name.VariablePath.UserPath
    $described.Description = $Description.Trim()
    $described.Type = $Parameter.StaticType
    $described.Default = if ($Parameter.DefaultValue) { $Parameter.DefaultValue.SafeGetValue() } else { $null }
    $described.AllowedValues = $allowed.ToArray()
    $described.Pipeline = $pipeline
    $described.Ast = $Parameter
    $described
}

# The properties a type presents: its public properties that are not hidden, in declaration order.
function Get-PscPresentedProperty {
    [CmdletBinding()]
    [OutputType([System.Reflection.PropertyInfo])]
    param([Parameter(Mandatory)][type] $Type)
    foreach ($property in $Type.GetProperties()) {
        if (-not $property.IsDefined([System.Management.Automation.HiddenAttribute], $false)) { $property }
    }
}

# One Markdown table cell: each element's ToString, joined; cell and row delimiters escaped.
function ConvertTo-PscMarkdownCell {
    [CmdletBinding()]
    [OutputType([string])]
    param([object] $Value)
    $parts = [System.Collections.Generic.List[string]]::new()
    foreach ($item in @($Value)) { if ($null -ne $item) { $parts.Add($item.ToString()) } }
    [string]::Join(', ', $parts).Replace('|', '\|').ReplaceLineEndings(' ')
}

# The Markdown lines of a table of objects of one type, one column per presented property.
function ConvertTo-PscMarkdownTable {
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][System.Reflection.PropertyInfo[]] $Columns, [object[]] $Rows)
    '| ' + [string]::Join(' | ', [string[]]@($Columns | ForEach-Object Name)) + ' |'
    '|' + [string]::Join('|', [string[]]@(foreach ($column in $Columns) { '---' })) + '|'
    foreach ($row in @($Rows)) {
        '| ' + [string]::Join(' | ', [string[]]@(foreach ($column in $Columns) { ConvertTo-PscMarkdownCell $column.GetValue($row) })) + ' |'
    }
}

# The README's lines: the API object's presented scalar properties as one table, then each presented sequence
# property under its own name, as a table when its elements are PSC records and as a list otherwise.
function ConvertTo-PscReadme {
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)][PscApi] $Api)
    '# PSC'
    ''
    $Api.AssertSurface()
    $Api.Guide(); ''
    '<details>'
    '<summary>CLI modes, parameters and dispatcher calls</summary>'
    ''
    ConvertTo-PscMarkdownTable -Columns @(Get-PscPresentedProperty -Type ([PscOperation])) -Rows $Api.Modes
    ''
    '</details>'
}

function Get-LoweringCapability {
    <#
    .SYNOPSIS
        Reports compiler capabilities, runtime versions, and supported contracts.
    #>
    [CmdletBinding()]
    param()

    [pscustomobject]@{
        Compiler                = 'PSC'
        SourcePath              = $PSCommandPath
        SourceSha256            = (Get-FileHash -LiteralPath $PSCommandPath).Hash
        CompileInputs           = @('SourcePath','SourceAst','ClassNames','StaticData','DeclarationsOnly')
        Product                 = 'Dev.MansfieldPlumbing.PowerShell.Lowering'
        PowerShellVersion       = $PSVersionTable.PSVersion.ToString()
        RuntimeVersion          = [Runtime.InteropServices.RuntimeInformation]::FrameworkDescription
        PersistedAssemblyBuilder = $null -ne ([Type]::GetType('System.Reflection.Emit.PersistedAssemblyBuilder, System.Reflection.Emit'))
        EmitterEngine           = 'PowerShell.IlEmitter'
        SupportedModes          = @('ClrOnly')
        SemanticContract        = 'Typed PowerShell semantics: checked integral arithmetic, Double integral division, round-half-to-even integral conversion, invariant-culture string comparison, IEEE 754 floats, exact reflected member binding'
        DependencyContract      = 'Zero runtime SMA dependencies for ClrOnly output'
    }
}

function ConvertTo-TypedExpression {
    <#
    .SYNOPSIS
        Lowers a PowerShell class method AST into a validated System.Linq.Expressions.LambdaExpression.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, ValueFromPipeline)]
        [System.Management.Automation.Language.FunctionMemberAst] $MethodAst
    )

    Convert-MethodAstToLambda -MethodAst $MethodAst
}

# A primitive array of static data held in the image as field data: its little-endian bytes go into private static
# fields of the type whose initializer copies them into a new array (ldsflda, cpblk). A loader maps the image, so a
# large array is not written as one IL constant per element.
class PscFieldData {
    # TypeBuilder.DefineInitializedData takes a field of more than 1 and fewer than 0x3F0000 bytes: the largest multiple
    # of 8 (the widest primitive) below that bound.
    static [int] $ChunkBytes = 0x3E0000
    [Type] $ElementType
    [int] $Length
    [int] $ElementBytes
    [byte[]] $Bytes
}

# The instances of this compile's classes reached from one class's static data. Each is made once, in the order it was
# reached, by that class's type initializer and kept in Table, so shared references and cycles are kept; its fields are
# assigned after every instance exists (Complete-PscStaticGraph).
class PscStaticGraph {
    [Linq.Expressions.ParameterExpression] $Table = [Linq.Expressions.Expression]::Variable([object[]], 'instances')
    [Collections.Generic.Dictionary[object, int]] $Index = [Collections.Generic.Dictionary[object, int]]::new([Collections.Generic.ReferenceEqualityComparer]::Instance)
    [Collections.Generic.List[object]] $Instances = [Collections.Generic.List[object]]::new()
    [Collections.Generic.List[Type]] $Types = [Collections.Generic.List[Type]]::new()
    [Collections.Generic.List[Linq.Expressions.Expression]] $Statements = [Collections.Generic.List[Linq.Expressions.Expression]]::new()
    # The compile's class models and projected CLR types by name, and the graph each instance already belongs to.
    [hashtable] $Models
    [hashtable] $ProjectedTypes
    [Collections.Generic.Dictionary[object, PscStaticGraph]] $Owners
}

# The instance a static data value is, as a read of the graph's table, or $null when the value is no instance of a class
# of this compile.
function Get-PscStaticInstance {
    param([Parameter(Mandatory)][PscStaticGraph] $Graph, [Parameter(Mandatory)] $Value, [Parameter(Mandatory)][Type] $Type)
    $name = $Value.GetType().Name
    if (-not $Graph.Models.ContainsKey($name)) { return $null }
    $target = $Graph.ProjectedTypes[$name]
    if (-not $Type.IsAssignableFrom($target)) { throw "Static data of type $Type cannot hold an instance of $name." }
    $owner = $null
    if ($Graph.Owners.TryGetValue($Value, [ref]$owner) -and -not [object]::ReferenceEquals($owner, $Graph)) { throw "An instance of $name is reached from the static data of two classes; each class's type initializer makes its own instances." }
    $index = 0
    if (-not $Graph.Index.TryGetValue($Value, [ref]$index)) {
        $index = $Graph.Instances.Count
        $Graph.Index.Add($Value, $index); $Graph.Instances.Add($Value); $Graph.Types.Add($target); $Graph.Owners[$Value] = $Graph
    }
    [Linq.Expressions.Expression]::Convert([Linq.Expressions.Expression]::ArrayAccess($Graph.Table, [Linq.Expressions.Expression]::Constant($index)), $target)
}

# Assigns every field of every instance in the graph, including instances reached while doing so.
function Complete-PscStaticGraph {
    param([Parameter(Mandatory)][PscStaticGraph] $Graph)
    $instanceFields = [Reflection.BindingFlags]::Public -bor [Reflection.BindingFlags]::NonPublic -bor [Reflection.BindingFlags]::Instance -bor [Reflection.BindingFlags]::DeclaredOnly
    for ($i = 0; $i -lt $Graph.Instances.Count; $i++) {
        $value = $Graph.Instances[$i]; $target = $Graph.Types[$i]
        $instance = [Linq.Expressions.Expression]::Convert([Linq.Expressions.Expression]::ArrayAccess($Graph.Table, [Linq.Expressions.Expression]::Constant($i)), $target)
        foreach ($property in @($Graph.Models[$target.Name].Properties | Where-Object { -not $_.IsStatic })) {
            $field = $target.GetField($property.Name, $instanceFields)
            $source = $value.GetType().GetProperty($property.Name)
            if ($null -eq $field -or $null -eq $source) { throw "Static data instance of $($target.Name) has no property $($property.Name)." }
            $Graph.Statements.Add([Linq.Expressions.Expression]::Assign([Linq.Expressions.Expression]::Field($instance, $field), (ConvertTo-StaticDataExpression $source.GetValue($value) $field.FieldType $Graph)))
        }
    }
}

# The statements a type initializer runs before its static data assignments: the table and every instance in it.
function Get-PscStaticGraphPrologue {
    param([Parameter(Mandatory)][PscStaticGraph] $Graph)
    [Linq.Expressions.Expression]::Assign($Graph.Table, [Linq.Expressions.Expression]::NewArrayBounds([object], [Linq.Expressions.Expression]::Constant($Graph.Instances.Count)))
    for ($i = 0; $i -lt $Graph.Instances.Count; $i++) {
        $constructor = $Graph.Types[$i].GetConstructor([Type]::EmptyTypes)
        if ($null -eq $constructor) { throw "Static data instances of $($Graph.Types[$i].Name) need a constructor with no parameters." }
        $made = $script:ExpressionNewMethod.Invoke($null, [object[]]@($constructor, [Linq.Expressions.Expression[]]@()))
        [Linq.Expressions.Expression]::Assign([Linq.Expressions.Expression]::ArrayAccess($Graph.Table, [Linq.Expressions.Expression]::Constant($i)),
            [Linq.Expressions.Expression]::Convert($made, [object]))
    }
    $Graph.Statements
}

function ConvertTo-StaticDataExpression {
    param($Value, [Type] $Type, [PscStaticGraph] $Graph)
    if ($Type -in [IntPtr],[UIntPtr]) { throw 'Native addresses are not durable static data.' }
    if ($null -eq $Value) {
        if ($Type.IsValueType -and $null -eq [Nullable]::GetUnderlyingType($Type)) { throw "Null is not valid for static data of type $Type." }
        return [Linq.Expressions.Expression]::Constant($null, $Type)
    }
    if ($Type.IsArray -and $Type.GetArrayRank() -eq 1) {
        if ($Value -isnot [Array]) { throw "Static data requires an array of $($Type.GetElementType())." }
        $element = $Type.GetElementType()
        if ($element.IsPrimitive -and $element -notin [IntPtr],[UIntPtr] -and $Value.Length -gt 0) {
            # An array of the element type is taken as it is; any other array is checked element by element.
            $typed = $Value
            if ($Value.GetType().GetElementType() -ne $element) { $typed = [Array]::CreateInstance($element, $Value.Length); for ($i = 0; $i -lt $Value.Length; $i++) {
                $item = $Value[$i]
                if ($null -eq $item -or $item.GetType() -ne $element) { throw "Static data type mismatch: expected $element, received $(if ($null -eq $item) { 'null' } else { $item.GetType() })." }
                $typed.SetValue($item, $i)
            } }
            $heldData = [PscFieldData]@{ ElementType = $element; Length = $typed.Length; ElementBytes = [Buffer]::ByteLength($typed) / $typed.Length; Bytes = [byte[]]::new([Buffer]::ByteLength($typed)) }
            [Buffer]::BlockCopy($typed, 0, $heldData.Bytes, 0, $heldData.Bytes.Length)
            $array = [Linq.Expressions.Expression]::NewArrayBounds($element, [Linq.Expressions.Expression]::Constant($typed.Length))
            $script:FieldDataArrays.Add($array, $heldData)
            return $array
        }
        $items = [Collections.Generic.List[Linq.Expressions.Expression]]::new()
        foreach ($item in $Value) { $items.Add((ConvertTo-StaticDataExpression $item $Type.GetElementType() $Graph)) }
        return [Linq.Expressions.Expression]::NewArrayInit($Type.GetElementType(), $items)
    }
    if ($null -ne $Graph) {
        $instance = Get-PscStaticInstance $Graph $Value $Type
        if ($null -ne $instance) { return $instance }
    }
    if ($Type.IsEnum) {
        $sourceType=$Value.GetType()
        $storage=[Enum]::GetUnderlyingType($Type)
        if (!$sourceType.IsEnum -or [Enum]::GetUnderlyingType($sourceType) -ne $storage) { throw "Static data enum type mismatch: expected $Type, received $sourceType." }
        if ($sourceType -ne $Type) {
            if ($null -eq $Graph -or $sourceType.Name -cne $Type.Name -or $Graph.ProjectedTypes[$Type.Name] -ne $Type) { throw "Static data enum has no source mapping: $sourceType to $Type." }
            $sourceNames=[Enum]::GetNames($sourceType);$targetNames=[Enum]::GetNames($Type)
            if ($sourceNames.Length -ne $targetNames.Length) { throw 'Static data enum declarations differ.' }
            foreach($literal in $sourceNames){
                if ($literal -cnotin $targetNames -or [Convert]::ChangeType([Enum]::Parse($sourceType,$literal),$storage) -ne [Convert]::ChangeType([Enum]::Parse($Type,$literal),$storage)) { throw 'Static data enum declarations differ.' }
            }
        }
        $raw=[Convert]::ChangeType($Value,$storage,[Globalization.CultureInfo]::InvariantCulture)
        return [Linq.Expressions.Expression]::Convert([Linq.Expressions.Expression]::Constant($raw,$storage),$Type)
    }
    $underlying = [Nullable]::GetUnderlyingType($Type)
    if ($null -ne $underlying) { return [Linq.Expressions.Expression]::Convert((ConvertTo-StaticDataExpression $Value $underlying $Graph), $Type) }
    if ($Type -ne [string] -and -not $Type.IsPrimitive) { throw "Static data supports primitive values, strings, their nullable forms, instances of this compile's classes and arrays of these, not $Type." }
    if ($Value.GetType() -ne $Type) { throw "Static data type mismatch: expected $Type, received $($Value.GetType())." }
    return [Linq.Expressions.Expression]::Constant($Value, $Type)
}

class PscMethodClosure : System.Linq.Expressions.ExpressionVisitor {
    [Collections.Generic.Dictionary[Reflection.MethodInfo, System.Management.Automation.Language.FunctionMemberAst]] $Bindings = [Collections.Generic.Dictionary[Reflection.MethodInfo, System.Management.Automation.Language.FunctionMemberAst]]::new()
    [Collections.Generic.HashSet[System.Management.Automation.Language.FunctionMemberAst]] $Required = [Collections.Generic.HashSet[System.Management.Automation.Language.FunctionMemberAst]]::new()
    [Collections.Generic.Queue[System.Management.Automation.Language.FunctionMemberAst]] $Pending = [Collections.Generic.Queue[System.Management.Automation.Language.FunctionMemberAst]]::new()

    [void] Require([System.Management.Automation.Language.FunctionMemberAst] $method) {
        if ($this.Required.Add($method)) { $this.Pending.Enqueue($method) }
    }

    [System.Linq.Expressions.Expression] VisitMethodCall([System.Linq.Expressions.MethodCallExpression] $node) {
        if ($this.Bindings.ContainsKey($node.Method)) { $this.Require($this.Bindings[$node.Method]) }
        return ([System.Linq.Expressions.ExpressionVisitor]$this).VisitMethodCall($node)
    }
}

function Get-RequiredClassMethods {
    param([Parameter(Mandatory)][object[]] $Model, [Parameter(Mandatory)][hashtable] $ProjectedTypes,
        [Parameter(Mandatory)][string] $ClassName, [Parameter(Mandatory)][string[]] $MethodNames)
    $closure = [PscMethodClosure]::new()
    $roots = 0
    foreach ($class in $Model) {
        foreach ($method in $class.Methods) {
            $member = $ProjectedTypes[$class.Name].GetMethod($method.Name, (Get-ParameterTypes $method))
            $closure.Bindings.Add($member, $method)
            if ($class.Name -ne $ClassName -or $method.Name -in $MethodNames) {
                $closure.Require($method)
                if ($class.Name -eq $ClassName) { $roots++ }
            }
        }
    }
    if (-not $roots) { throw "No matching methods found in class '$ClassName' to export." }
    foreach ($class in $Model) {
        $instanceInitializers = @($class.Properties | Where-Object { -not $_.IsStatic -and $_.InitialValue })
        $staticInitializers = @($class.Properties | Where-Object { $_.IsStatic -and $_.InitialValue })
        foreach ($constructor in $class.Constructors) {
            $lowered = Convert-MethodAstToLambda -MethodAst $constructor -Initializers $instanceInitializers
            $null = $closure.Visit($lowered.Lambda.Body)
        }
        if (-not $class.Constructors.Count -and $instanceInitializers.Count) {
            $lowered = Convert-InitializersToLambda -ClassAst $class.Ast -Initializers $instanceInitializers
            $null = $closure.Visit($lowered.Lambda.Body)
        }
        if ($staticInitializers.Count) {
            $lowered = Convert-InitializersToLambda -ClassAst $class.Ast -Initializers $staticInitializers -Static
            $null = $closure.Visit($lowered.Lambda.Body)
        }
    }
    while ($closure.Pending.Count) {
        $lowered = Convert-MethodAstToLambda -MethodAst $closure.Pending.Dequeue()
        $null = $closure.Visit($lowered.Lambda.Body)
    }
    return ,$closure.Required
}

# The records of one compile (Export-LoweredAssembly).

# A parsed source and the class the compile targets. ClassAst is $null for a program, whose target is the class of
# its functions.
class PscLoweringSource {
    [System.Management.Automation.Language.ScriptBlockAst] $Ast
    [System.Management.Automation.Language.TypeDefinitionAst] $ClassAst
}

# A static field that -StaticData fills, with the expression that builds its value.
class PscStaticDataField {
    [System.Reflection.FieldInfo] $Field
    [System.Linq.Expressions.Expression] $Expression
}

# A method or constructor with the builder its body is written into. Ast is $null for the constructor PSC supplies
# to a class that declares none.
class PscMemberPlan {
    [System.Management.Automation.Language.FunctionMemberAst] $Ast
    [System.Reflection.MethodBase] $Builder
}

# One class's members to emit. Class is its model (Get-ClassModel).
class PscClassPlan {
    [object] $Class
    [PscMemberPlan[]] $Constructors
    [PscMemberPlan[]] $Methods
}

# PowerShellSemantics in the assembly being compiled. Session is the assembly's session (New-PersistedAssemblySession).
# Methods is $null until an emitted call needs a helper; Needed names the helpers the compile used.
class PscSemanticsPlan {
    [object] $Session
    [PscMemberPlan[]] $Methods
    [System.Collections.Generic.SortedSet[string]] $Needed
}

# What a compile produced. EntryPoint and RuntimeConfig are $null for a library.
class PscLoweredAssembly {
    [string] $OutputPath
    [int] $Length
    [string] $SHA256
    [string] $ClassName
    [string[]] $Classes
    # The PowerShellSemantics helpers this compile switched on, because lowering needed them.
    [string[]] $Helpers
    [string[]] $EmittedMethods
    [bool] $Deterministic
    [string] $EntryPoint
    [string] $RuntimeConfig
    [PscIcon] $ApplicationIcon
}

function Export-LoweredAssembly {
    <#
    .SYNOPSIS
        Compiles the classes of a typed PowerShell source file into a managed assembly.
    .DESCRIPTION
        Every class in the file is compiled into one assembly, so classes may
        use each other's types, fields, constructors and methods. Properties
        become public fields; their initial values run in the static
        initializer (static properties) or before each constructor body.
        -ClassName names the class whose methods are reported and which holds
        the -EntryPoint; it defaults to the first class.
    #>
    [CmdletBinding()]
    param(
        [Parameter()][string] $SourcePath,
        [Parameter()][System.Management.Automation.Language.ScriptBlockAst] $SourceAst,
        [Parameter()][Collections.IDictionary] $StaticData,
        [Parameter()][string] $ClassName,
        [Parameter()][string[]] $ClassNames,
        [switch] $DeclarationsOnly,
        # Select these methods of -ClassName and retain their bound method dependencies.
        [Parameter()][string[]] $MethodNames,
        [Parameter(Mandatory)][string] $OutputPath,
        [switch] $Deterministic = $true,

        # Name of a static method to make the program's entry point. It must
        # return [int] or [void] and take no parameters or one [string[]].
        # The output is then an executable with a runtime configuration
        # beside it, runnable with `dotnet <OutputPath>`.
        [Parameter()][string] $EntryPoint,

        # Compile -SourceAst as a program: its classes, its functions as one class, and its top-level statements as
        # that class's Main([string[]]), the entry point, which binds the script's parameters from the command line.
        [switch] $Program
    )

    $script:PscCompilingProgram = [bool]$Program
    if ($Program) {
        # The script as a program: its function class, with Main, is the target (Get-ScriptFunctionClass -Program).
        if ($null -eq $SourceAst) { throw '-Program compiles -SourceAst.' }
        $null = Get-ScriptFunctionClass -Root $SourceAst -Program
        $parsed = [PscLoweringSource]@{ Ast = $SourceAst; ClassAst = $null }
    }
    elseif ($null -ne $SourceAst) {
        if ($SourcePath) { throw 'Supply SourcePath or SourceAst, not both.' }
        $classes = @($SourceAst.FindAll({ param($n) $n -is [System.Management.Automation.Language.TypeDefinitionAst] -and $n.IsClass }, $true))
        $target = @(if ($ClassName) { $classes | Where-Object Name -eq $ClassName } else { $classes | Select-Object -First 1 })
        if ($target.Count -ne 1) { throw 'SourceAst must contain exactly one target class.' }
        # The caller may compose class copies from independently parsed sources. Extent.Text is provenance,
        # not a serialization of that composed tree. Get-ClassModel and body admission validate the live nodes.
        $parsed = [PscLoweringSource]@{ Ast = $SourceAst; ClassAst = $target[0] }
    } else {
    $fullSourcePath = if ([IO.Path]::IsPathFullyQualified($SourcePath)) {
        [IO.Path]::GetFullPath($SourcePath)
    }
    else {
        [IO.Path]::GetFullPath((Join-Path (Get-Location) $SourcePath))
    }
    if (-not [IO.File]::Exists($fullSourcePath)) {
        throw "Source file not found: '$fullSourcePath'."
    }

    $source = [IO.File]::ReadAllText($fullSourcePath)
    $parsed = Read-PowerShellClass -Source $source -ClassName $ClassName -SourceFile $fullSourcePath
    }
    # Script variables used only as records are lowered as their classes.
    $typedRoot = if ($DeclarationsOnly) { $parsed.Ast } else { ConvertTo-PscRecordSource -Root $parsed.Ast }
    if (-not [object]::ReferenceEquals($typedRoot, $parsed.Ast)) {
        if ($Program) { $null = Get-ScriptFunctionClass -Root $typedRoot -Program; $parsed = [PscLoweringSource]@{ Ast = $typedRoot; ClassAst = $null } }
        else {
            $targetName = $parsed.ClassAst.Name
            $parsed = [PscLoweringSource]@{ Ast = $typedRoot; ClassAst = $typedRoot.Find({ param($n) $n -is [System.Management.Automation.Language.TypeDefinitionAst] -and $n.Name -eq $targetName }, $true) }
        }
    }
    $programIcon = if ($Program) { Get-ProgramIcon -Root $parsed.Ast } else { $null }
    $targetClass = $parsed.ClassAst
    $classAsts = @(if ($DeclarationsOnly) {
        foreach ($declaration in $parsed.Ast.EndBlock.Statements) {
            if ($declaration -is [System.Management.Automation.Language.TypeDefinitionAst] -and $declaration.IsClass -and -not (Test-AttributeClass $declaration)) { $declaration }
        }
    } else {
        $parsed.Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.TypeDefinitionAst] -and $n.IsClass }, $true) | Where-Object { -not (Test-AttributeClass $_) }
    })
    # Declaration-only compilation retains the parser-owned nodes and excludes script execution units.
    $functionClass = $null
    if ($DeclarationsOnly) {
        if ($targetClass -notin $classAsts) { throw 'DeclarationsOnly requires a top-level target class.' }
        $script:ScriptFunctionClasses[$parsed.Ast] = $null
    } else { $functionClass = Get-ScriptFunctionClass -Root $parsed.Ast -Program:$Program }
    if ($Program) { $targetClass = $functionClass }
    if ($null -ne $functionClass) {
        if (-not $ClassNames -or $functionClass.Name -in $ClassNames) { $classAsts += $functionClass }
        else {
            $functionRoot = $functionClass; while ($functionRoot.Parent) { $functionRoot = $functionRoot.Parent }
            $null = $script:ScriptFunctionSources.Remove($functionRoot)
            $script:ScriptFunctionClasses[$parsed.Ast] = $null
        }
    }
    $script:LoweringKeywords = @{}
    foreach ($definition in @(Get-LoweringKeywords $parsed.Ast)) { $script:LoweringKeywords[$definition.Name] = $definition }
    if ($ClassNames) {
        $classAsts = @($classAsts | Where-Object Name -in $ClassNames)
        if ($classAsts.Count -ne @($ClassNames | Sort-Object -Unique).Count -or $targetClass.Name -notin $ClassNames) { throw 'ClassNames must identify existing classes and include ClassName.' }
    }
    Assert-PscInlineOverrides -Classes $classAsts
    $model = @(Get-ClassModel -ClassAsts $classAsts)
    $sourceClasses = [System.Management.Automation.Language.TypeDefinitionAst[]]@($classAsts | Where-Object { -not [object]::ReferenceEquals($_, $functionClass) })
    $null = Get-ClrTypeProjection -Root $parsed.Ast -SelectedClassAst $sourceClasses
    Use-DeclarationScope -Ast $parsed.Ast
    $projection = @{} + $script:LoweringClassTypes
    $requiredMethods = if ($MethodNames) { Get-RequiredClassMethods -Model $model -ProjectedTypes $projection -ClassName $targetClass.Name -MethodNames $MethodNames } else { $null }
    $dataFields = @{}
    if ($null -eq $StaticData) { $StaticData = @{} }
    # One graph of instances per class with static data (PscStaticGraph).
    $graphs = @{}; $models = @{}; foreach ($c in $model) { $models[$c.Name] = $c }
    $owners = [Collections.Generic.Dictionary[object, PscStaticGraph]]::new([Collections.Generic.ReferenceEqualityComparer]::Instance)
    foreach ($key in $StaticData.Keys) {
        $parts = ([string]$key).Split('.')
        if ($parts.Count -ne 2 -or $parts[0] -notin @($model.Name)) { throw "Unknown or unselected static data field '$key'." }
        $field = $projection[$parts[0]].GetField($parts[1], [Reflection.BindingFlags]'Public,Static,DeclaredOnly')
        if ($null -eq $field) { throw "Unknown static data field '$key'." }
        if (-not $graphs.ContainsKey($parts[0])) { $graphs[$parts[0]] = [PscStaticGraph]@{ Models = $models; ProjectedTypes = $projection; Owners = $owners } }
        $dataFields[$key] = [PscStaticDataField]@{ Field = $field; Expression = (ConvertTo-StaticDataExpression $StaticData[$key] $field.FieldType $graphs[$parts[0]]) }
    }
    foreach ($staticGraph in $graphs.Values) { Complete-PscStaticGraph $staticGraph }

    $assemblyName = [IO.Path]::GetFileNameWithoutExtension($OutputPath)
    $session = New-PersistedAssemblySession -AssemblyName $assemblyName
    $declared = [Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly'
    $script:IlMap = @{ Types = @{}; Members = @{}; ImplicitConstructors = @{}; Semantics = [PscSemanticsPlan]@{ Session = $session; Methods = $null; Needed = [System.Collections.Generic.SortedSet[string]]::new([StringComparer]::Ordinal) } }
    try {
        # 1. Output types, so every signature can name any of them. Enums are complete once their literals exist.
        foreach ($enumAst in @($parsed.Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.TypeDefinitionAst] -and $n.IsEnum }, $true))) {
            $enumBuilder = $session.Module.DefineEnum($enumAst.Name, [Reflection.TypeAttributes]::Public, (Get-EnumUnderlyingType $enumAst))
            foreach ($literal in (Get-EnumLiterals $enumAst)) { $null = $enumBuilder.DefineLiteral($literal.Name, $literal.Value) }
            $null = $enumBuilder.CreateType()
            $script:IlMap.Types[$projection[$enumAst.Name]] = $enumBuilder
        }
        foreach ($c in $model) {
            $tb = $session.Module.DefineType($c.Name, [Reflection.TypeAttributes]'Public,Class')
            $session.Types[$c.Name] = $tb
            $script:IlMap.Types[$projection[$c.Name]] = $tb
        }

        # 2. Fields, constructors and methods, in source order.
        $plans = foreach ($c in $model) {
            $tb = $session.Types[$c.Name]
            $projectedType = $projection[$c.Name]
            foreach ($p in $c.Properties) {
                $mf = $projectedType.GetField($p.Name, $declared)
                $script:IlMap.Members[$mf] = $tb.DefineField($mf.Name, (Get-IlType $mf.FieldType), $mf.Attributes)
            }
            $ctorPlans = @(foreach ($ctorAst in $c.Constructors) {
                [Type[]]$types = @()
                if ($ctorAst) { $types = Get-ParameterTypes $ctorAst }
                $mc = $projectedType.GetConstructor($declared, $null, $types, $null)
                $cb = $tb.DefineConstructor($mc.Attributes, [Reflection.CallingConventions]::Standard, [Type[]]@($types | ForEach-Object { Get-IlType $_ }))
                if ($ctorAst) {
                    for ($i = 0; $i -lt $ctorAst.Parameters.Count; $i++) { $null = $cb.DefineParameter($i + 1, [Reflection.ParameterAttributes]::None, $ctorAst.Parameters[$i].Name.VariablePath.UserPath) }
                }
                $script:IlMap.Members[$mc] = $cb
                [PscMemberPlan]@{ Ast = $ctorAst; Builder = $cb }
            })
            foreach ($n in $c.NativeImports) {
                $types = Get-ParameterTypes $n.Ast
                $mm = $projectedType.GetMethod($n.Ast.Name, $declared, $null, $types, $null)
                $names = [string[]]@($n.Ast.Parameters | ForEach-Object { $_.Name.VariablePath.UserPath })
                $script:IlMap.Members[$mm] = Add-NativeImportMethod -TypeBuilder $tb -Name $mm.Name -Import $n.Import `
                    -ReturnType (Get-IlType $mm.ReturnType) -ParameterTypes ([Type[]]@($types | ForEach-Object { Get-IlType $_ })) -ParameterNames $names -Persisted
            }
            $methods = @($c.Methods)
            if ($null -ne $requiredMethods) { $methods = @($methods | Where-Object { $requiredMethods.Contains($_) }) }
            $methodPlans = foreach ($m in $methods) {
                $types = Get-ParameterTypes $m
                $mm = $projectedType.GetMethod($m.Name, $declared, $null, $types, $null)
                $inline = Test-PscInlineMethod $m
                $attributes = $mm.Attributes
                if ($inline) { $attributes = $attributes -bor [Reflection.MethodAttributes]::Final }
                $mb = $tb.DefineMethod($mm.Name, $attributes, (Get-IlType $mm.ReturnType), [Type[]]@($types | ForEach-Object { Get-IlType $_ }))
                if ($inline) { $mb.SetImplementationFlags([Reflection.MethodImplAttributes]::AggressiveInlining) }
                for ($i = 0; $i -lt $m.Parameters.Count; $i++) { $null = $mb.DefineParameter($i + 1, [Reflection.ParameterAttributes]::None, $m.Parameters[$i].Name.VariablePath.UserPath) }
                Set-NativeCallbackAttribute -Builder $mb -Contract (Get-NativeMethodContract $m)
                Set-ProgramEntryAttributes -Method $m -Builder $mb
                $script:IlMap.Members[$mm] = $mb
                [PscMemberPlan]@{ Ast = $m; Builder = $mb }
            }
            if (-not $c.Constructors.Count) {
                $mc = $projectedType.GetConstructor($declared, $null, [Type[]]@(), $null)
                if (@($c.Properties | Where-Object { -not $_.IsStatic -and $_.InitialValue }).Count) {
                    $cb = $tb.DefineConstructor($mc.Attributes, [Reflection.CallingConventions]::Standard, [Type[]]@())
                    $script:IlMap.Members[$mc] = $cb
                    $ctorPlans += [PscMemberPlan]@{ Ast = $null; Builder = $cb }
                } else { $script:IlMap.ImplicitConstructors[$mc] = $tb }
            }
            [PscClassPlan]@{ Class = $c; Constructors = @($ctorPlans); Methods = @($methodPlans) }
        }

        # 3. Bodies.
        $emittedMethods = [System.Collections.Generic.List[string]]::new()
        $entryBuilder = $null
        foreach ($plan in $plans) {
            $c = $plan.Class
            $staticInits = @($c.Properties | Where-Object { $_.IsStatic -and $_.InitialValue })
            $instanceInits = @($c.Properties | Where-Object { -not $_.IsStatic -and $_.InitialValue })
            $fieldInputs = @($dataFields.Values | Where-Object { $_.Field.DeclaringType -eq $projection[$c.Name] })
            if ($staticInits.Count -or $fieldInputs.Count) {
                $lowered = Convert-InitializersToLambda -ClassAst $c.Ast -Initializers $staticInits -Static
                $initializer = $lowered.Lambda
                if ($fieldInputs.Count) {
                $body = [Collections.Generic.List[Linq.Expressions.Expression]]::new()
                $body.Add($lowered.Lambda.Body)
                $staticGraph = $graphs[$c.Name]
                $variables = [Linq.Expressions.ParameterExpression[]]@()
                if ($null -ne $staticGraph -and $staticGraph.Instances.Count) {
                    foreach ($statement in @(Get-PscStaticGraphPrologue $staticGraph)) { $body.Add($statement) }
                    $variables = [Linq.Expressions.ParameterExpression[]]@($staticGraph.Table)
                }
                foreach ($inputField in $fieldInputs) { $body.Add([Linq.Expressions.Expression]::Assign([Linq.Expressions.Expression]::Field($null, $inputField.Field), $inputField.Expression)) }
                $body.Add([Linq.Expressions.Expression]::Empty())
                $initializer = [Linq.Expressions.Expression]::Lambda([Linq.Expressions.Expression]::Block($variables, $body), [Linq.Expressions.ParameterExpression[]]@())
                }
                Write-IlMethodBody -Lambda $initializer -MethodBuilder $session.Types[$c.Name].DefineTypeInitializer() -IsStatic
            }
            foreach ($ctor in $plan.Constructors) {
                $lowered = if ($ctor.Ast) { Convert-MethodAstToLambda -MethodAst $ctor.Ast -Initializers $instanceInits }
                           else { Convert-InitializersToLambda -ClassAst $c.Ast -Initializers $instanceInits }
                Write-IlMethodBody -Lambda $lowered.Lambda -MethodBuilder $ctor.Builder -HasThis -BaseConstructor
            }
            foreach ($method in $plan.Methods) {
                $lowered = Convert-MethodAstToLambda -MethodAst $method.Ast
                Write-IlMethodBody -Lambda $lowered.Lambda -MethodBuilder $method.Builder -IsStatic:$lowered.IsStatic -HasThis:$lowered.HasThis
                if ($c.Name -eq $targetClass.Name) {
                    $emittedMethods.Add($lowered.Name)
                    if ($EntryPoint -and $lowered.Name -ceq $EntryPoint) {
                        # ECMA-335 II.15.4.1.2: a static method returning int32 or void,
                        # taking no parameters or one string[].
                        $types = @($lowered.ParameterTypes)
                        $validReturn = $lowered.ReturnType -in [int], [void]
                        $validParams = $types.Count -eq 0 -or ($types.Count -eq 1 -and $types[0] -eq [string[]])
                        $entryNative = Get-NativeMethodContract $method.Ast
                        if ($entryNative -and $entryNative.Kind -eq 'Callback') { throw ('[{0}:{1}] UnmanagedCallersOnly cannot be an entry point.' -f $method.Ast.Extent.StartLineNumber,$method.Ast.Extent.StartColumnNumber) }
                        if (-not $lowered.IsStatic -or -not $validReturn -or -not $validParams) {
                            throw "[{0}:{1}] Entry point '{2}' must be static, return [int] or [void], and take no parameters or one [string[]]." -f `
                                $method.Ast.Extent.StartLineNumber, $method.Ast.Extent.StartColumnNumber, $EntryPoint
                        }
                        $entryBuilder = $method.Builder
                    }
                }
            }
        }
        # PowerShellSemantics, when an emitted call switched it on: its bodies are lowered after the program's.
        $helpers = [string[]]@()
        if ($null -ne $script:IlMap.Semantics.Methods) {
            foreach ($helper in $script:IlMap.Semantics.Methods) {
                $lowered = Convert-MethodAstToLambda -MethodAst $helper.Ast
                Write-IlMethodBody -Lambda $lowered.Lambda -MethodBuilder $helper.Builder -IsStatic:$lowered.IsStatic -HasThis:$lowered.HasThis
            }
            $helpers = [string[]]@($script:IlMap.Semantics.Needed)
        }
        if ($emittedMethods.Count -eq 0 -and $MethodNames) {
            throw "No matching methods found in class '$($targetClass.Name)' to export."
        }
        if ($EntryPoint -and -not $entryBuilder) {
            throw "Entry point '$EntryPoint' is not an exported method of class '$($targetClass.Name)' (it exports: $($emittedMethods -join ', '))."
        }

        # 4. Save.
        $saveResult = Save-PersistedAssemblySession -Session $session -OutputPath $OutputPath -Deterministic:$Deterministic -EntryPoint $entryBuilder
    }
    finally {
        $script:IlMap = @{ Types = @{}; Members = @{} }
        $script:LoweringKeywords = @{}
        $script:PscCompilingProgram = $false
    }

    $compiled = [PscLoweredAssembly]@{
        OutputPath     = $saveResult.OutputPath
        Length         = $saveResult.Length
        SHA256         = $saveResult.SHA256
        ClassName      = $targetClass.Name
        Classes        = [string[]]@($model | ForEach-Object Name)
        Helpers        = $helpers
        EmittedMethods = $emittedMethods.ToArray()
        Deterministic  = $saveResult.Deterministic
    }
    # A [string] property turns an assigned $null into ''; a library's stay $null, as they were.
    if ($null -ne $saveResult.EntryPoint) { $compiled.EntryPoint = $saveResult.EntryPoint }
    if ($null -ne $saveResult.RuntimeConfig) { $compiled.RuntimeConfig = $saveResult.RuntimeConfig }
    $compiled.ApplicationIcon = $programIcon
    $compiled
}

# Native AOT: the lowered assembly compiled to machine code by ILC (Microsoft's IL compiler, PSC's backend) and
# linked by PSC's own COFF linker. No MSBuild and no .NET SDK: every input is pinned under tools and verified by hash.

# Pinned tool folders already verified against their manifests in this process.
$script:VerifiedPins = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)

# Pinned Native AOT toolchain folders under PSC's NativeAOT folder, found by enumerating it for the newest version of each.
function Get-NativeToolset {
    $tools = Join-Path $PSScriptRoot 'NativeAOT'
    $find = { param([string] $prefix) $found = @(Get-ChildItem -LiteralPath $tools -Directory -Filter ($prefix + '*') | Sort-Object Name); if (-not $found.Count) { throw "Pinned tool '$prefix*' is missing under $tools." }; $found[-1].FullName }
    $toolset = [pscustomobject]@{
        Compiler = & $find 'ilc-1'
        Build = & $find 'ilc-build-'
        Runtime = & $find 'nativeaot-win-x64-'
        Msvc = & $find 'msvc-'
        Sdk = & $find 'windows-sdk-lib-'
    }
    foreach ($folder in $toolset.Compiler, $toolset.Build, $toolset.Runtime, $toolset.Sdk) {
        if ($script:VerifiedPins.Contains($folder)) { continue }
        $manifest = Join-Path $folder 'pin.sha256.csv'
        if (-not [IO.File]::Exists($manifest)) { throw "Pinned tool $folder has no hash manifest." }
        foreach ($entry in Import-Csv -LiteralPath $manifest) {
            $path = Join-Path $folder $entry.Path
            if (-not [IO.File]::Exists($path) -or (Get-FileHash -LiteralPath $path).Hash -cne $entry.Sha256) { throw "Pinned tool file failed verification: $path" }
        }
        $null = $script:VerifiedPins.Add($folder)
    }
    $toolset
}

# ILC's settings for a Windows x64 executable. The feature switches are those the .NET SDK's ILCompiler targets pass
# for PublishAot with InvariantGlobalization and UseSystemResourceKeys (observed from a reference publish); each is
# both a compile-time feature and a runtime knob, as the SDK passes them.
$script:NativeFeatureSwitches = [ordered]@{
    'Microsoft.Extensions.DependencyInjection.VerifyOpenGenericServiceTrimmability' = $true
    'System.ComponentModel.DefaultValueAttribute.IsSupported' = $false
    'System.ComponentModel.Design.IDesignerHost.IsSupported' = $false
    'System.ComponentModel.TypeConverter.EnableUnsafeBinaryFormatterInDesigntimeLicenseContextSerialization' = $false
    'System.ComponentModel.TypeDescriptor.IsComObjectDescriptorSupported' = $false
    'System.Data.DataSet.XmlSerializationIsSupported' = $false
    'System.Diagnostics.Tracing.EventSource.IsSupported' = $false
    'System.Globalization.Invariant' = $true
    'System.Globalization.PredefinedCulturesOnly' = $true
    'System.Linq.Enumerable.IsSizeOptimized' = $true
    'System.Net.SocketsHttpHandler.Http3Support' = $false
    'System.Reflection.Metadata.MetadataUpdater.IsSupported' = $false
    'System.Resources.ResourceManager.AllowCustomResourceTypes' = $false
    'System.Resources.UseSystemResourceKeys' = $true
    'System.Runtime.CompilerServices.RuntimeFeature.IsDynamicCodeSupported' = $false
    'System.Runtime.InteropServices.BuiltInComInterop.IsSupported' = $false
    'System.Runtime.InteropServices.EnableConsumingManagedCodeFromNativeHosting' = $false
    'System.Runtime.InteropServices.EnableCppCLIHostActivation' = $false
    'System.Runtime.InteropServices.Marshalling.EnableGeneratedComInterfaceComImportInterop' = $false
    'System.Runtime.Serialization.EnableUnsafeBinaryFormatterSerialization' = $false
    'System.StartupHookProvider.IsSupported' = $false
    'System.Text.Encoding.EnableUnsafeUTF7Encoding' = $false
    'System.Text.Json.JsonSerializer.IsReflectionEnabledByDefault' = $false
    'System.Threading.Thread.EnableAutoreleasePool' = $false
    'System.Threading.ThreadPool.UseWindowsThreadPool' = $true
    'System.Linq.Expressions.CanEmitObjectArrayDelegate' = $false
}

# The runtime's own assemblies ILC initializes in every image, whatever the program references.
$script:NativeInitialAssemblies = [string[]]@('System.Private.CoreLib', 'System.Private.StackTraceMetadata', 'System.Private.TypeLoader', 'System.Private.Reflection.Execution')

# The simple names of the assemblies an assembly references, read from its metadata.
function Get-AssemblyReferenceName {
    param([Parameter(Mandatory)][string] $Path)
    $stream = [IO.File]::OpenRead($Path)
    $reader = [Reflection.PortableExecutable.PEReader]::new($stream)
    try {
        $metadata = [Reflection.Metadata.PEReaderExtensions]::GetMetadataReader($reader)
        foreach ($handle in $metadata.AssemblyReferences) { $metadata.GetString($metadata.GetAssemblyReference($handle).Name) }
    } finally { $reader.Dispose(); $stream.Dispose() }
}

# The assemblies ILC reads for one program: those the lowered assembly references and the runtime's initial
# assemblies, with everything they reference in turn, found among the Native AOT runtime's assemblies. ILC compiles
# only what is reachable from these, so the rest of the framework leaves the object unchanged (measured on Notepad:
# 15 of 186 assemblies, byte-identical object). A name the runtime does not carry is left for ILC to report.
function Get-NativeReferenceClosure {
    param(
        [Parameter(Mandatory)][string] $AssemblyPath,
        [Parameter(Mandatory)][string[]] $Directory
    )
    $available = [Collections.Generic.Dictionary[string, string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($file in Get-ChildItem -LiteralPath $Directory -File -Filter *.dll) { $available[$file.BaseName] = $file.FullName }
    $closure = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $pending = [Collections.Generic.Queue[string]]::new([string[]]@(@(Get-AssemblyReferenceName -Path $AssemblyPath) + $script:NativeInitialAssemblies))
    while ($pending.Count) {
        $name = $pending.Dequeue()
        if (-not $available.ContainsKey($name) -or -not $closure.Add($available[$name])) { continue }
        foreach ($reference in Get-AssemblyReferenceName -Path $available[$name]) { $pending.Enqueue($reference) }
    }
    [string[]]@($closure | Sort-Object)
}

function Export-NativeImage {
    param(
        [Parameter(Mandatory)][string] $AssemblyPath,
        [Parameter(Mandatory)][string] $OutputPath,
        [ValidateSet('Console', 'Windows')][string] $Subsystem = 'Console',
        [PscIcon] $ApplicationIcon
    )
    $toolset = Get-NativeToolset
    $managed = Join-Path $toolset.Runtime 'runtimes\win-x64\lib\net11.0'
    $native = Join-Path $toolset.Runtime 'runtimes\win-x64\native'
    $object = [IO.Path]::ChangeExtension($OutputPath, '.obj')
    $response = [IO.Path]::ChangeExtension($OutputPath, '.ilc.rsp')

    # 1. ILC: the lowered assembly to one native object.
    $arguments = [System.Collections.Generic.List[string]]::new()
    $arguments.Add($AssemblyPath)
    $arguments.Add('-o:' + $object)
    foreach ($reference in Get-NativeReferenceClosure -AssemblyPath $AssemblyPath -Directory $managed, $native) { $arguments.Add('-r:' + $reference) }
    foreach ($assembly in $script:NativeInitialAssemblies) { $arguments.Add('--initassembly:' + $assembly) }
    foreach ($option in '--targetos:win', '--targetarch:x64', '-O',
        '--export-dynamic-symbol:DotNetRuntimeDebugHeader,DATA', '--export-dynamic-symbol:DotNetRuntimeContractDescriptor,DATA',
        '--directpinvoke:System.Globalization.Native', '--directpinvoke:System.IO.Compression.Native',
        ('--directpinvokelist:' + (Join-Path $toolset.Build 'build\WindowsAPIs.txt')),
        '--stacktracedata:frames', '--scanreflection', '--methodbodyfolding:generic', '--singlewarn', '--resilient',
        '--generateunmanagedentrypoints:System.Private.CoreLib,HIDDEN', '--feature:System.Diagnostics.Debugger.IsSupported=false', '--runtimeknob:RUNTIME_IDENTIFIER=win-x64') {
        $arguments.Add($option)
    }
    foreach ($switch in $script:NativeFeatureSwitches.Keys) {
        $value = $script:NativeFeatureSwitches[$switch].ToString().ToLowerInvariant()
        $arguments.Add("--feature:$switch=$value"); $arguments.Add("--runtimeknob:$switch=$value")
    }
    [IO.File]::WriteAllLines($response, $arguments)
    $compiler = Join-Path $toolset.Compiler 'tools\ilc.exe'
    $output = & $compiler "@$response" 2>&1
    if ($LASTEXITCODE -ne 0) { throw ("ILC failed ($LASTEXITCODE):`n" + ($output -join "`n")) }

    # 2. PSC's COFF linker: the object, the Native AOT runtime, and the Windows import libraries.
    $inputs = [System.Collections.Generic.List[string]]::new()
    $inputs.Add($object)
    foreach ($name in 'bootstrapper.obj', 'Runtime.WorkstationGC.lib', 'eventpipe-disabled.lib', 'Runtime.VxsortDisabled.lib', 'standalonegc-disabled.lib', 'aotminipal.lib',
        'zlibstatic.lib', 'brotlicommon.lib', 'brotlienc.lib', 'brotlidec.lib', 'zstd_static.lib', 'System.Globalization.Native.Aot.lib', 'System.IO.Compression.Native.Aot.lib') { $inputs.Add((Join-Path $native $name)) }
    foreach ($name in 'advapi32.lib', 'bcrypt.lib', 'crypt32.lib', 'iphlpapi.lib', 'kernel32.lib', 'mswsock.lib', 'ncrypt.lib', 'normaliz.lib', 'ntdll.lib',
        'ole32.lib', 'oleaut32.lib', 'secur32.lib', 'Synchronization.lib', 'user32.lib', 'version.lib', 'ws2_32.lib') { $inputs.Add((Join-Path $toolset.Sdk "um\x64\$name")) }
    $libraries = @((Join-Path $toolset.Msvc 'lib\x64'), (Join-Path $toolset.Sdk 'ucrt\x64'), (Join-Path $toolset.Sdk 'um\x64'))
    $resolution = Resolve-CoffLink -Inputs $inputs.ToArray() -LibraryDirectories $libraries -DefaultLibraries @('ucrt.lib') -IgnoredDefaultLibraries @('libucrt.lib') -Entry 'wmainCRTStartup'
    if ($resolution.Unresolved.Count) { throw ("Native link: unresolved external symbols:`n" + ($resolution.Unresolved -join "`n")) }
    $image = Write-CoffImage -Resolution $resolution -Path ([PscTreeText]::FullPath($OutputPath)) -Merges @('.managedcode=.text', 'hydrated=.bss') -Subsystem $(if ($Subsystem -eq 'Windows') { 2 } else { 3 }) -StackReserve 1572864 -ApplicationIcon $ApplicationIcon
    [pscustomobject]@{ OutputPath = [IO.Path]::GetFullPath($OutputPath); Object = $object; ObjectLength = (Get-Item -LiteralPath $object).Length; ImageLength = (Get-Item -LiteralPath $OutputPath).Length; Image = $image }
}

# Bounded CIL acquisition. The original module is trusted input; metadata tokens
# are resolved in its own module, never copied into the destination token space.
# These records are typed input to the same persisted emitter as AST lowering.
class PscCilInstruction {
    [int] $Offset
    [Reflection.Emit.OpCode] $Opcode
    [object] $Operand
    [byte[]] $OperandBytes
    [bool] $OperandResolved
    [int] $EndOffset
}
# Read-only structural inquiry. Authoring-side SMA ASTs and PE metadata are
# references, never executable source. No project graph or target assembly load.
enum PscQueryKind { Call; MemberAccess; Declaration; Index; CilMethod; CilOp }
class PscMatch {
    [string] $Domain
    [string] $ArtifactPath
    [string] $ArtifactSha256
    [string] $Owner
    [PscQueryKind] $Kind
    [string] $Name
    [int] $StartOffset
    [int] $EndOffset
    [int] $Line
    [int] $Column
    [int] $MethodToken
    [object] $Target
    [bool] $ParseIncomplete
    [int] $SourceRevision = -1
    [Guid] $DocumentIdentity
}
class PscQueryCoverage {
    [int] $ArtifactsOpened
    [int] $ArtifactsCompleted
    [int] $Parsed
    [int] $SkippedByDomain
    [int] $ParseFailures
    [int] $ReadFailures
    [int] $UnexaminedDynamic
    [int] $MethodsExamined
    [int] $MethodsSkipped
    [int] $BodiesOpened
    [int] $InstructionsExamined
    [int] $SitesExamined
    [long] $VisitorCallbacks
    [int] $Matches
    [bool] $Exhausted
    [bool] $StoppedByLimit
    [string] $Status
    [string[]] $Diagnostics
}
class PscQuerySpec {
    [PscQueryKind] $Kind
    [string] $Name
    [string] $Owner
    [int] $Take = [int]::MaxValue
    [string] $Literal
    PscQuerySpec([PscQueryKind]$kind,[string]$name,[string]$owner,[int]$take){
        if($take -lt 1){throw [ArgumentOutOfRangeException]::new('take')}
        $this.Kind=$kind;$this.Name=$name;$this.Owner=$owner;$this.Take=$take
    }
    [bool] Matches([string]$name,[string]$owner,[bool]$ordinal){
        [StringComparison]$comparison=[StringComparison]::OrdinalIgnoreCase
        if($ordinal){$comparison=[StringComparison]::Ordinal}
        return ([string]::IsNullOrEmpty($this.Name) -or [string]::Equals($name,$this.Name,$comparison)) -and ([string]::IsNullOrEmpty($this.Owner) -or [string]::Equals($owner,$this.Owner,$comparison))
    }
}
class PscSourceQueryVisitor : System.Management.Automation.Language.AstVisitor2 {
    [PscQuerySpec] $Spec
    [int] $ExactStart = -1
    [int] $ExactEnd = -1
    [int] $Resume
    [int] $Seen
    [int] $Unknown
    [int] $Limit
    [bool] $Stopped
    [string] $Path
    [string] $Digest
    [bool] $ParseIncomplete
    [Collections.Generic.List[PscMatch]] $Hits = [Collections.Generic.List[PscMatch]]::new()
    static [string] OwnerOf([System.Management.Automation.Language.Ast]$node){
        $parent=$node.Parent
        while($null -ne $parent){
            if($parent -is [System.Management.Automation.Language.FunctionMemberAst]){return $parent.Parent.Name+'.'+$parent.Name}
            if($parent -is [System.Management.Automation.Language.FunctionDefinitionAst]){
                if($parent.Parent -is [System.Management.Automation.Language.FunctionMemberAst]){return $parent.Parent.Parent.Name+'.'+$parent.Name}
                return $parent.Name
            }
            if($parent -is [System.Management.Automation.Language.TypeDefinitionAst]){return $parent.Name}
            $parent=$parent.Parent
        }
        return '<script>'
    }
    [System.Management.Automation.Language.AstVisitAction] Observe([System.Management.Automation.Language.Ast]$node,[string]$name,[bool]$dynamic){
        $this.Seen++
        if($this.Seen -le $this.Resume){return [System.Management.Automation.Language.AstVisitAction]::Continue}
        if($dynamic){$this.Unknown++;return [System.Management.Automation.Language.AstVisitAction]::Continue}
        $owner=[PscSourceQueryVisitor]::OwnerOf($node)
        if(($this.ExactStart -lt 0 -or ($this.ExactStart -eq $node.Extent.StartOffset -and $this.ExactEnd -eq $node.Extent.EndOffset)) -and $this.Spec.Matches($name,$owner,$false) -and (!$this.Spec.Literal -or $node.Extent.Text.Contains($this.Spec.Literal,[StringComparison]::Ordinal))){
            $hit=[PscMatch]::new();$hit.Domain='SourceAst';$hit.ArtifactPath=$this.Path;$hit.ArtifactSha256=$this.Digest;$hit.Owner=$owner;$hit.Kind=$this.Spec.Kind;$hit.Name=$name
            $hit.StartOffset=$node.Extent.StartOffset;$hit.EndOffset=$node.Extent.EndOffset;$hit.Line=$node.Extent.StartLineNumber;$hit.Column=$node.Extent.StartColumnNumber;$hit.Target=$node;$hit.ParseIncomplete=$this.ParseIncomplete
            $this.Hits.Add($hit)
            if($this.Hits.Count -eq $this.Limit){$this.Stopped=$true;return [System.Management.Automation.Language.AstVisitAction]::StopVisit}
        }
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
    [System.Management.Automation.Language.AstVisitAction] VisitCommand([System.Management.Automation.Language.CommandAst]$node){
        if($this.Spec.Kind -eq [PscQueryKind]::Call){$name=$node.GetCommandName();return $this.Observe($node,$name,[string]::IsNullOrEmpty($name))}
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
    [System.Management.Automation.Language.AstVisitAction] VisitInvokeMemberExpression([System.Management.Automation.Language.InvokeMemberExpressionAst]$node){
        if($this.Spec.Kind -eq [PscQueryKind]::Call){
            if($node.Member -is [System.Management.Automation.Language.StringConstantExpressionAst]){return $this.Observe($node,$node.Member.Value,$false)}
            return $this.Observe($node,'',$true)
        }
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
    [System.Management.Automation.Language.AstVisitAction] VisitMemberExpression([System.Management.Automation.Language.MemberExpressionAst]$node){
        if($this.Spec.Kind -eq [PscQueryKind]::MemberAccess){
            if($node.Member -is [System.Management.Automation.Language.StringConstantExpressionAst]){return $this.Observe($node,$node.Member.Value,$false)}
            return $this.Observe($node,'',$true)
        }
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
    [System.Management.Automation.Language.AstVisitAction] VisitFunctionDefinition([System.Management.Automation.Language.FunctionDefinitionAst]$node){
        if($this.Spec.Kind -eq [PscQueryKind]::Declaration -and $node.Parent -isnot [System.Management.Automation.Language.FunctionMemberAst]){return $this.Observe($node,$node.Name,$false)}
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
    [System.Management.Automation.Language.AstVisitAction] VisitFunctionMember([System.Management.Automation.Language.FunctionMemberAst]$node){
        if($this.Spec.Kind -eq [PscQueryKind]::Declaration){return $this.Observe($node,$node.Name,$false)}
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
    [System.Management.Automation.Language.AstVisitAction] VisitTypeDefinition([System.Management.Automation.Language.TypeDefinitionAst]$node){
        if($this.Spec.Kind -eq [PscQueryKind]::Declaration){return $this.Observe($node,$node.Name,$false)}
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
    [System.Management.Automation.Language.AstVisitAction] VisitIndexExpression([System.Management.Automation.Language.IndexExpressionAst]$node){
        if($this.Spec.Kind -eq [PscQueryKind]::Index){return $this.Observe($node,'Index',$false)}
        return [System.Management.Automation.Language.AstVisitAction]::Continue
    }
}
# Document core follows Notepad.ps1 (17b76e2), NotepadPiece/NotepadEdit/NotepadDocument:
# immutable original storage, append-only insertion storage, ordered pieces and a grouped journal.
# The search/UI layer is not imported. A replacement consumes structural references of this revision.
class PscDocumentPiece {
    [int] $Buffer
    [int] $Start
    [int] $Length
    PscDocumentPiece([int]$buffer,[int]$start,[int]$length){
        $this.Buffer=$buffer; $this.Start=$start; $this.Length=$length
    }
}
class PscDocumentEdit {
    [int] $Position
    [PscDocumentPiece[]] $Removed
    [PscDocumentPiece[]] $Inserted
    PscDocumentEdit([int]$position,[PscDocumentPiece[]]$removed,[PscDocumentPiece[]]$inserted){
        $this.Position=$position; $this.Removed=$removed; $this.Inserted=$inserted
    }
}
class PscDocumentGroup {
    [Collections.Generic.List[PscDocumentEdit]] $Edits = [Collections.Generic.List[PscDocumentEdit]]::new()
}
class PscDocument {
    [string] $Path
    [int] $Revision
    [int] $Length
    hidden [string] $Original
    hidden [Text.StringBuilder] $Added = [Text.StringBuilder]::new()
    hidden [Collections.Generic.List[PscDocumentPiece]] $Pieces = [Collections.Generic.List[PscDocumentPiece]]::new()
    hidden [Collections.Generic.List[PscDocumentGroup]] $Journal = [Collections.Generic.List[PscDocumentGroup]]::new()
    hidden [int] $JournalPosition
    hidden [string] $SavedHash
    hidden [Guid] $Identity = [Guid]::NewGuid()
    PscDocument([string]$path){
        $this.Path=[PscTreeText]::FullPath($path)
        $this.Original=[PscTreeText]::Read($this.Path); $this.Length=$this.Original.Length
        $this.SavedHash=[PscTreeText]::Hash($this.Original)
        if($this.Length){$this.Pieces.Add([PscDocumentPiece]::new(0,0,$this.Length))}
    }
    [string] Text(){
        $builder=[Text.StringBuilder]::new($this.Length)
        foreach($piece in $this.Pieces){
            if($piece.Buffer -eq 0){[void]$builder.Append($this.Original,$piece.Start,$piece.Length)}
            else{[void]$builder.Append($this.Added.ToString($piece.Start,$piece.Length))}
        }
        return $builder.ToString()
    }
    [bool] Modified(){return [PscTreeText]::Hash($this.Text()) -cne $this.SavedHash}
    hidden [System.Management.Automation.Language.ScriptBlockAst] Parse([string]$text){
        $tokens=$null; $errors=$null
        $ast=[System.Management.Automation.Language.Parser]::ParseInput($text,$this.Path,[ref]$tokens,[ref]$errors)
        if($errors.Count){throw "Document parse failed at $($errors[0].Extent.StartLineNumber): $($errors[0].Message)"}
        return $ast
    }
    [PscMatch[]] Query([PscQueryKind]$kind,[string]$name,[string]$owner,[int]$limit){
        return $this.Find($kind,$name,$owner,'',$limit)
    }
    [PscMatch[]] Find([PscQueryKind]$kind,[string]$name,[string]$owner,[int]$limit){return $this.Query($kind,$name,$owner,$limit)}
    [PscMatch] Resolve([PscMatch]$match){
        $text=$this.Text();$digest=[PscTreeText]::Hash($text)
        if($null -eq $match -or $match.Domain -cne 'SourceAst' -or $match.ParseIncomplete -or $match.SourceRevision -ne -1 -or $match.DocumentIdentity -ne [Guid]::Empty -or $match.ArtifactPath -cne $this.Path -or $match.ArtifactSha256 -cne $digest){throw 'Resolve requires a current read-only source reference.'}
        if($match.Target -isnot [System.Management.Automation.Language.Ast] -or $match.StartOffset -lt 0 -or $match.EndOffset -le $match.StartOffset -or $match.EndOffset -gt $text.Length){throw 'Resolve requires a valid source extent.'}
        $extent=([System.Management.Automation.Language.Ast]$match.Target).Extent
        if($extent.StartOffset -ne $match.StartOffset -or $extent.EndOffset -ne $match.EndOffset -or $extent.Text -cne $text.Substring($match.StartOffset,$match.EndOffset-$match.StartOffset)){throw 'Resolve source extent differs.'}
        $visitor=[PscSourceQueryVisitor]::new();$visitor.Spec=[PscQuerySpec]::new($match.Kind,$match.Name,$match.Owner,1);$visitor.Path=$this.Path;$visitor.Digest=$digest;$visitor.Limit=1;$visitor.ExactStart=$match.StartOffset;$visitor.ExactEnd=$match.EndOffset
        $this.Parse($text).Visit($visitor)
        if($visitor.Hits.Count -ne 1 -or $visitor.Hits[0].Target.GetType() -ne $match.Target.GetType()){throw 'Resolve could not reproduce structural reference.'}
        $resolved=$visitor.Hits[0];$resolved.SourceRevision=$this.Revision;$resolved.DocumentIdentity=$this.Identity;return $resolved
    }
    [PscMatch[]] Find([PscQueryKind]$kind,[string]$name,[string]$owner,[string]$literal,[int]$limit){
        if($limit -lt 1 -or $limit -gt 256 -or $kind -in [PscQueryKind]::CilMethod,[PscQueryKind]::CilOp){throw 'Document query requires a source kind and a limit of 1..256.'}
        $text=$this.Text(); $ast=$this.Parse($text)
        $visitor=[PscSourceQueryVisitor]::new(); $visitor.Spec=[PscQuerySpec]::new($kind,$name,$owner,$limit)
        $visitor.Spec.Literal=$literal; $visitor.Path=$this.Path; $visitor.Digest=[PscTreeText]::Hash($text); $visitor.Limit=$limit
        $ast.Visit($visitor)
        foreach($hit in $visitor.Hits){$hit.SourceRevision=$this.Revision;$hit.DocumentIdentity=$this.Identity}
        return $visitor.Hits.ToArray()
    }
    hidden [int] SplitAt([int]$position){
        $offset=0
        for($i=0;$i -lt $this.Pieces.Count;$i++){
            $piece=$this.Pieces[$i]
            if($position -eq $offset){return $i}
            if($position -lt $offset+$piece.Length){
                $left=$position-$offset
                $this.Pieces[$i]=[PscDocumentPiece]::new($piece.Buffer,$piece.Start,$left)
                $this.Pieces.Insert($i+1,[PscDocumentPiece]::new($piece.Buffer,$piece.Start+$left,$piece.Length-$left))
                return $i+1
            }
            $offset+=$piece.Length
        }
        return $this.Pieces.Count
    }
    hidden [int] PiecesLength([PscDocumentPiece[]]$pieces){
        $total=0; foreach($piece in $pieces){$total+=$piece.Length}; return $total
    }
    hidden [PscDocumentPiece[]] ReplacePieces([int]$position,[int]$length,[PscDocumentPiece[]]$inserted){
        if($position -lt 0 -or $length -lt 0 -or $position -gt $this.Length-$length){throw 'Invalid document extent.'}
        $first=$this.SplitAt($position); $last=$this.SplitAt($position+$length)
        $removed=$this.Pieces.GetRange($first,$last-$first).ToArray()
        $this.Pieces.RemoveRange($first,$last-$first); $this.Pieces.InsertRange($first,$inserted)
        $this.Length=$this.Length-$length+$this.PiecesLength($inserted)
        return $removed
    }
    [void] Replace([PscMatch]$match,[string]$replacement){$this.Replace([PscMatch[]]@($match),[string[]]@($replacement))}
    [void] Replace([PscMatch[]]$matches,[string[]]$replacements){
        if(!$matches.Length -or $matches.Length -gt 256 -or $matches.Length -ne $replacements.Length){throw 'Replacement requires 1..256 paired references and payloads.'}
        $text=$this.Text(); $digest=[PscTreeText]::Hash($text)
        $order=[Collections.Generic.SortedDictionary[int,int]]::new()
        for($i=0;$i -lt $matches.Length;$i++){
            $hit=$matches[$i]
            if($null -eq $hit -or $hit.Domain -cne 'SourceAst' -or $hit.ParseIncomplete -or $hit.ArtifactPath -cne $this.Path -or $hit.ArtifactSha256 -cne $digest -or $hit.SourceRevision -ne $this.Revision -or $hit.DocumentIdentity -ne $this.Identity){throw 'Stale or foreign document reference.'}
            if($hit.Target -isnot [System.Management.Automation.Language.Ast] -or $hit.StartOffset -lt 0 -or $hit.EndOffset -le $hit.StartOffset -or $hit.EndOffset -gt $text.Length){throw 'Invalid document reference extent.'}
            $extent=([System.Management.Automation.Language.Ast]$hit.Target).Extent
