    static [Reflection.Emit.OpCode] Opcode([int]$value){
        if(![PscCilByteCursor]::Ops.ContainsKey($value)){throw [IO.InvalidDataException]::new('Unknown CIL opcode')}
        return [PscCilByteCursor]::Ops[$value]
    }
