            ShortInlineBrTarget {$width=1}
            InlineVar {$width=2}
            InlineI {$width=4}
            InlineBrTarget {$width=4}
            InlineField {$width=4}
            InlineMethod {$width=4}
            InlineType {$width=4}
            InlineTok {$width=4}
            InlineSig {$width=4}
            InlineString {$width=4}
            ShortInlineR {$width=4}
            InlineI8 {$width=8}
            InlineR {$width=8}
