    foreach ($h in $result.Handlers) {
        if (!$offsets.Contains($h.TryOffset) -or !$offsets.Contains($h.HandlerOffset) -or !$offsets.Contains($h.HandlerOffset+$h.HandlerLength)) { throw 'Invalid exception region boundaries.' }
        $last=$result.Instructions | Where-Object EndOffset -eq ($h.HandlerOffset+$h.HandlerLength)
        if ($last.Opcode.Name -ne 'endfinally') { throw 'Finally region must end with endfinally.' }
    }
    return $result
}

# Typed CIL stack elimination. Blocks carry explicit incoming virtual values;
# edges carry parallel arguments. Locals remain addressable storage, not SSA.
# The managed re-emitter admits only scalar methods without exception regions.
class PscIrInstruction {
    [int]$Offset
    [string]$Operation
    [Reflection.Emit.OpCode]$Opcode
    [object]$Operand
    [int[]]$Inputs
    [int]$Result = -1
}
class PscIrEdge {
    [int]$Target
    [int[]]$Arguments
}
class PscIrBlock {
    [int]$Offset
    [int[]]$Parameters
    [PscIrInstruction[]]$Instructions
    [PscIrEdge[]]$Edges
    [bool]$Visited
}
class PscIrMethod {
    [PscCilMethod]$Source
    [PscIrBlock[]]$Blocks
    [Collections.Generic.List[type]]$Types = [Collections.Generic.List[type]]::new()
    [int] NewValue([type]$Type) { $id=$this.Types.Count; $this.Types.Add($Type); return $id }
}
function Get-PscIrStorageType([type]$Type) {
    if($Type.IsEnum){$Type=[Enum]::GetUnderlyingType($Type)}
    if($Type -in [bool],[char],[byte],[sbyte],[short],[ushort],[uint]){return [int]}
    if($Type -eq [ulong]){return [long]}
    return $Type
}
function Get-PscIrIndex([PscCilInstruction]$Instruction) {
    $name=$Instruction.Opcode.Name
    $last=$name.Substring($name.LastIndexOf('.')+1)
    if($last -in '0','1','2','3'){return [int]$last}
    return [int]$Instruction.Operand
}
function Get-PscIrConstant([PscCilInstruction]$Instruction) {
    $name=$Instruction.Opcode.Name
    if($name -eq 'ldc.i4.m1'){return -1}
    if($name.StartsWith('ldc.i4.') -and $name.Length -eq 8 -and $name[-1] -ne 's'){return [int]$name.Substring(7)}
    return $Instruction.Operand
}
function Pop-PscIrValues([Collections.Generic.List[int]]$Stack,[int]$Count,[int]$Offset) {
    if($Stack.Count -lt $Count){throw "CIL stack underflow at $Offset"}
    $values=[int[]]::new($Count)
    for($i=$Count-1;$i -ge 0;$i--){$at=$Stack.Count-1;$values[$i]=$Stack[$at];$Stack.RemoveAt($at)}
    return ,$values
}
function Assert-PscIrAssignment([type]$Actual,[type]$Expected,[int]$Offset) {
    $expectedType=Get-PscIrStorageType $Expected
    if($Actual -eq $expectedType){return}
    if($Actual -in [float],[double] -and $expectedType -in [float],[double]){return}
    if(!$expectedType.IsValueType -and ($Actual -eq [void] -or (!$Actual.IsValueType -and $expectedType.IsAssignableFrom($Actual)))){return}
    throw "CIL stack type $Actual cannot assign to $Expected at $Offset"
}
function ConvertTo-PscIr([PscCilMethod]$Body) {
    $ir=[PscIrMethod]::new();$ir.Source=$Body
