        foreach($c in $raw[$b.Offset]){
            $n=$c.Opcode.Name;$node=[PscIrInstruction]::new();$node.Offset=$c.Offset;$node.Opcode=$c.Opcode;$node.Operation=$n;$node.Operand=$c.Operand;$node.Inputs=[int[]]::new(0);$type=$null
            if($n.StartsWith('ldarg')){$idx=Get-PscIrIndex $c;$node.Operation='arg';$node.Operand=$idx;$type=Get-PscIrStorageType $argsTypes[$idx]}
            elseif($n.StartsWith('ldloc')){$idx=Get-PscIrIndex $c;$node.Operation='local.read';$node.Operand=$idx;$type=Get-PscIrStorageType $Body.Locals[$idx].LocalType}
            elseif($n.StartsWith('stloc')){$idx=Get-PscIrIndex $c;$node.Operation='local.write';$node.Operand=$idx;$node.Inputs=Pop-PscIrValues $stack 1 $c.Offset;Assert-PscIrAssignment $ir.Types[$node.Inputs[0]] $Body.Locals[$idx].LocalType $c.Offset}
            elseif($n.StartsWith('ldc.i4')){$node.Operation='constant';$node.Operand=[int](Get-PscIrConstant $c);$type=[int]}
            elseif($n -in 'ldc.i8','ldc.r4','ldc.r8'){$node.Operation='constant';$type=$c.Operand.GetType()}
            elseif($n -eq 'ldnull'){$node.Operation='null';$type=[void]}
