            elseif($n -eq 'pop'){$node.Inputs=Pop-PscIrValues $stack 1 $c.Offset}
            elseif($n -in 'add','add.ovf','sub','sub.ovf','mul','mul.ovf','div','ceq','clt','cgt','cgt.un'){
                $node.Inputs=Pop-PscIrValues $stack 2 $c.Offset;$a=$ir.Types[$node.Inputs[0]];$z=$ir.Types[$node.Inputs[1]]
                if($n -in 'ceq','clt','cgt','cgt.un'){
                    if($a -ne $z -and !($a -in [float],[double] -and $z -in [float],[double]) -and !(!$a.IsValueType -and !$z.IsValueType) -and $a -ne [void] -and $z -ne [void]){throw "Incompatible comparison $a / $z at $($c.Offset)"};$type=[int]
                }else{
                    if($a -in [float],[double] -and $z -in [float],[double]){$type=[float];if($a -eq [double] -or $z -eq [double]){$type=[double]}}
                    elseif($a -eq $z -and $a -in [int],[long],[IntPtr],[UIntPtr]){$type=$a}
                    else{throw "Incompatible numeric operands $a / $z at $($c.Offset)"}
