            elseif($n -in 'conv.i4','conv.r4','conv.r8'){$node.Inputs=Pop-PscIrValues $stack 1 $c.Offset;if($ir.Types[$node.Inputs[0]] -notin [int],[long],[float],[double],[IntPtr],[UIntPtr]){throw 'Invalid numeric conversion'};$type=[int];if($n -eq 'conv.r4'){$type=[float]}elseif($n -eq 'conv.r8'){$type=[double]}}
