            elseif($n -in 'brtrue','brtrue.s','brfalse','brfalse.s'){$node.Operation='branch';$node.Inputs=Pop-PscIrValues $stack 1 $c.Offset;$targets.Add([int]$c.Operand);$targets.Add($c.EndOffset)}
            elseif($n -eq 'ret'){$node.Operation='return';if($Body.Method.ReturnType -ne [void]){$node.Inputs=Pop-PscIrValues $stack 1 $c.Offset;Assert-PscIrAssignment $ir.Types[$node.Inputs[0]] $Body.Method.ReturnType $c.Offset};if($stack.Count){throw 'Nonempty ret stack'}}
            elseif($n -eq 'endfinally'){if($stack.Count){throw 'Nonempty finally stack'}}
            elseif($n -ne 'nop'){throw "Unsupported IR opcode $n"}
            if($null -ne $type){$node.Result=$ir.NewValue($type);$stack.Add($node.Result)}
            $nodes.Add($node)
        }
        $b.Instructions=$nodes.ToArray();$last=$raw[$b.Offset][-1]
        if(!$targets.Count -and $last.Opcode.Name -notin 'ret','endfinally'){if($last.EndOffset -ge $Body.Length){throw 'CIL fallthrough beyond method'};$targets.Add($last.EndOffset)}
        $edges=[Collections.Generic.List[PscIrEdge]]::new()
        foreach($target in $targets){
            if(!$byOffset.ContainsKey($target)){throw "Invalid IR edge $target"};$dest=$byOffset[$target]
            if($null -eq $dest.Parameters){$dest.Parameters=[int[]]::new($stack.Count);for($i=0;$i -lt $stack.Count;$i++){$dest.Parameters[$i]=$ir.NewValue($ir.Types[$stack[$i]])};$q.Enqueue($dest)}
            if($dest.Parameters.Length -ne $stack.Count){throw "Incompatible stack height at merge $target"}
            for($i=0;$i -lt $stack.Count;$i++){$want=$ir.Types[$dest.Parameters[$i]];$got=$ir.Types[$stack[$i]]
                if($want -eq $got){continue}
                if(!$want.IsValueType -and ($got -eq [void] -or (!$got.IsValueType -and $want.IsAssignableFrom($got)))){continue}
                if(!$got.IsValueType -and ($want -eq [void] -or (!$want.IsValueType -and $got.IsAssignableFrom($want)))){$ir.Types[$dest.Parameters[$i]]=$got;$q.Enqueue($dest);continue}
                throw "Incompatible stack types at merge $target : $want versus $got"}
