    foreach($b in $ir.Blocks){if(!$b.Visited){throw "Unreachable CIL block $($b.Offset) not yet admitted"}}
    # Reference join refinement can revisit blocks. Compact obsolete values and
    # retain only explicit parameters/results from the final graph.
    $live=[Collections.Generic.SortedSet[int]]::new()
    foreach($b in $ir.Blocks){foreach($id in $b.Parameters){[void]$live.Add($id)};foreach($n in $b.Instructions){if($n.Result -ge 0){[void]$live.Add($n.Result)}}}
