        foreach($n in $b.Instructions){for($i=0;$i -lt $n.Inputs.Length;$i++){$n.Inputs[$i]=$map[$n.Inputs[$i]];if(!$defined.Contains($n.Inputs[$i])){throw 'IR input lacks block-local definition'}};if($n.Result -ge 0){$n.Result=$map[$n.Result];if(!$defined.Add($n.Result)){throw 'Duplicate IR definition'}}}
